using namespace std;

bool MN (string n, int s)
{
	if (n[0] == '1')
	{
		for (int i = 1; i < s; i++)
		{
			n[i - 1] = n[i];
			s--;
			return MN (n, s);
		}
	}
	else
	{
		if (n[1] == '4')
		{
			if (n[2] == '4')				
				return false;
			else
				for (int i = 2; i < s; i++)
				{
					n[i - 2] = n[i];
					s -= 2;
					return MN (n, s);
				}
		}
		else
		{
			for (int i = 1; i < s; i++)
			{
				n[i - 1] = n[i];
				s--;
				return MN (n, s);
			}
		}
	}
}			


