int n, k, l, d[MM];

bool vis[MM][MM][MM];
bool solve(int pos, int tide, bool inc)
{
	if (pos >= n + 1) return true;
	if (vis[pos][tide][inc]) return false;
	vis[pos][tide][inc] = true;
	int ntide = tide + (inc ? 1 : -1);
	bool ninc = inc;
	if (ntide == 0) ninc = true;
	else if (ntide == k) ninc = false;

	for(int i = 0; i < 2; i++)
	{
		if (d[pos + i] + ntide <= l)
			if (solve(pos + i, ntide, ninc)) return true;
	}
	return false;
}

