long long modpow(long long x,long long y,int p){
	long long res=1;
	for(;y;y>>=1,(x*=x)%=p)
		if(y&1)(res*=x)%=p;
	return res;
}
bool check(int b,int p){
	for(int i=1;i*i<p;i++)
		if((p-1)%i==0){
			a[tot++]=i;
			if(i*i!=p-1)
				a[tot++]=(p-1)/i;
		}
	sort(a,a+tot);
	for(int i=0;i<tot;i++)
		if(a[i]!=1&&modpow(b,(p-1)/a[i],p)==1)return 0;
	return 1;
}
