void work3() {
	for(int i=0;i<16;i++) if(num[i]>(n/2)) return ;
	memset(num,0,sizeof(num)); ans = 0;
	for(int i=1;i<=n;i++) ans += a[i];
	int tot = 0,mann = 0, cl;
	for(int i=1;i<=n/2;i++) {
		if(s[i]==s[n-i+1]) {
			num[s[i]-'a']++; tot++;
			ans -= min(a[i],a[n-i+1]);
		}
	}
	for(int i=0;i<26;i++) if(num[i]>mann) mann = num[i], cl = i;
	if(tot>=(mann<<1)) return ;
	tot = 2*mann - tot;
	for(int i=1;i<=n/2;i++) {
		if(s[i]==s[n-i+1]) continue;
		if(s[i]==cl+'a') q.push(a[n-i+1]);
		else if(s[n-i+1]==cl+'a') q.push(a[i]);
		else q.push(min(a[n-i+1],a[i]));
	}
	while(tot--) {
		ans -= q.top(); q.pop();
	}
}

