template<typename T> inline bool chkmax(T &aa, T bb) { return aa < bb ? aa = bb, true : false; }
template<typename T> inline bool chkmin(T &aa, T bb) { return aa > bb ? aa = bb, true : false; }
typedef pair<ll,ll> pll;typedef vector<ll> vll;typedef pair<int,int> pii;typedef vector<int> vi;typedef vector<vi> vvi;
const ll SLIM=sqrt((ld)1e11)+4;
/*
(n+k)*r+t+q=A // k>=q
(n+k)*r+t+q=A+1 // k>=q>=1 if gap exists, k>=1 o/w

(n+k)*r+q = A-t
k*r+q = A-t-n*r

k*r+q = RHS
0<=q<=t

k = RHS/r to (RHS-t)/r

Find highest k st k>=q

(w+q)*r+q = A-t-n*r
Find highest w+q st 0<=w<=n-t, 0<=q<=t
This means q must be minimized.

Suppose q is free. Then w can be binsearched?
If k is too high, then w is too high
*/

ll solve(ll n, ll t, ll A, bool qone) {
  if (A<t) return -1;
  if (n<=SLIM) {
    //printf("AA");
    for (ll k=n;k>=0;k--) {
      ll q=(A-t)%(n+k);
      if (qone && q==0) continue;
      if (k>=q && k-q <= n-t && q<=t) {
        assert(0<=q&&q<=t&&q<=k&&0<=k-q&&k-q<=n-t);
        return k;
      }
    }
    return -1;
  }
  else {
    //printf("BB");
    ll rlim=2+((A-t)/n);
    ll final=-1;
    for (ll r=1;r<=rlim;r++) {
      ll rhs=(A-t-n*r);
      if (rhs<0) break;
      ll kmin=((rhs+1+r)/(r+1)); ll kmax=min(n,rhs/r)+1;
      while(kmin<kmax) {
        ll k=(kmin+kmax)/2;
        ll q=rhs-r*k;
        bool toolow= (k-q<=n-t) || (qone&&q==0);
        if (toolow) kmin=k+1;
        else kmax=k;
      }
      ll k=kmin-1;
      ll q=rhs%k;
      //if (r==1) printf("k:%lld q:%lld t:%lld rhs:%lld A:%lld\n",k,q,t,rhs,A);
      if (r*k+q==rhs&&q<=t&&k-q<=n-t) {
        assert(0<=q&&q<=t&&q<=k&&0<=k-q&&k-q<=n-t);
        assert((n+k)*r+q == A-t);
        chkmax(final,k);
      }
    }
    {
      ll q=A-t;
      ll w=n-t;
      if (!qone || q>=1) {
        if (q<=t && t+q==A) {
          chkmax(final,q+w);
        }
      }
    }
    return final;
  }
}
