// xをb進法にする
template <typename T>
vector<T> convert_base(T x, T b)
{
    vector<T> res;
    // t : digit
    T t = 1, k = abs(b);
    while (x != 0)
    {
        res.emplace_back((x * t) % k);
        if (res.back() < 0)
            res.back() += k;
        x -= res.back() * t;
        x /= k;
        t *= b / k;
    }
    if (res.empty())
        res.emplace_back(0);
    return res;
}

ll int_pow(ll x, ll n)
{
    ll res = 1;
    while (n > 0)
    {
        if (n & 1)
            res *= x;
        x *= x;
        n >>= 1;
    }
    return res;
}

ll w, M;

int main()
{
    cin >> w >> M;
    vector<ll> dig = convert_base(M, w);
    for (int i = 0; i < dig.size(); i++)
    {
        if (1 < dig[i] && dig[i] < w - 1)
        {
            cout << "NO" << endl;
            return 0;
        }
        else if (dig[i] == w - 1)
        {
            M += int_pow(w, i);
            dig = convert_base(M, w);
        }
    }
    cout << "YES" << endl;
}

