using namespace std;

typedef long long ll;
typedef vector<ll> vi;
typedef vector<vi> vvi;

ll BinExp(ll bas, ll exp){
   ll ans=1, temp=bas;
    while(exp){
        if(exp&1) ans*=temp;
        temp*=temp;
        exp>>=1;
    }
    return ans;
}

ll BinModExp(ll bas, ll exp, ll mod){
   ll ans=1, temp=bas%mod;
    while(exp){
        if(exp&1) ans=(ans*temp)%mod;
        temp=(temp*temp)%mod;
        exp>>=1;
    }
    return ans;
}

vvi Multiply_Matrix(vvi A, vvi B, ll mod){
    if(A[0].size()!=B.size()) return vvi();
    vvi C(A.size(), vi(B[0].size(), 0));
    for(int i=0; i<C.size(); i++)
        for(int j=0; j<C[i].size(); j++)
            for(int k=0; k<B.size(); k++)
                C[i][j]=(C[i][j]+(A[i][k]*B[k][j])%mod)%mod;
    return C;
}

vvi Expon_Matrix(vvi A, int exp, ll mod){
    if(exp==1) return A;
    if(exp&1) return Multiply_Matrix(Expon_Matrix(Multiply_Matrix(A, A, mod), exp>>1, mod), A, mod);
    return Expon_Matrix(Multiply_Matrix(A, A, mod), exp>>1, mod);
}

ll Nfibo(ll n, ll mod){
    vvi A;
    A.assign(2,vi(2));
    A[0][0]=1;
    A[0][1]=1;
    A[1][0]=1;
    A[1][1]=0;
    A=Expon_Matrix(A, n, mod);
    return (A[0][0]+A[0][1])%mod;
}
int main(){
    ll n, k, l, m;
    while(scanf("%I64d %I64d %I64d %I64d", &n, &k, &l, &m)!=EOF){
        if(BinExp(2, l)<k){
            printf("0\n");
        }else{
            ll A=BinModExp(2, n, m);
            ll B=Nfibo(n, m);
            ll ans=1;
//          cout<<A<<" "<<B<<endl;
            for(int i=0; i<l;i++){
                if(k&(1LL<<i)){
                    ans*=A-B+m;
                }else{
                    ans*=B;
                }
                ans%=m;
            }
            printf("%I64d\n", ans);
        }
    }
    return 0;
}

