void solve() {
	int f, r, i, j, k, l, x, y;

	cin >> N >> V >> E;
	FOR(i, N) cin >> A[i];
	FOR(i, N) cin >> B[i];

	FOR(x, N) FOR(y, N) mat[x][y] = 9999;
	FOR(x, N) mat[x][x] = 0;
	FOR(i, E) {
		cin >> x >> y;
		mat[x - 1][y - 1] = mat[y - 1][x - 1] = 1;
	}
	FOR(i, N) FOR(j, N) FOR(k, N) mat[j][k] = min(mat[j][k], mat[j][i] + mat[i][k]);
	FOR(x, N) FOR(y, N) {
		if (mat[x][y] > N) continue;
		j = min(A[x] - B[x], B[y] - A[y]);
