		flow(x, y, j);
	}

	FOR(x, N) if (A[x] != B[x]) return (void)_P("NO\n");
	_P("%d\n", R.size());
	FOR(i, R.size()) _P("%d %d %d\n", R[i].first.first + 1, R[i].first.second + 1, R[i].second);
}

