const int MOD = 1e9 + 7;


vector< vector<int> > mult(vector< vector<int> > a, vector< vector<int> > b) {
    int n = (int)a.size() - 1;
    int m = (int)b[1].size() - 1;
    vector< vector<int> > c(n + 1, vector<int> (m + 1, 0));
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            for (int k = 1; k < (int)a[1].size(); ++k) {
                c[i][j] += ((long long)a[i][k] * (long long)b[k][j]) % MOD;
                if (c[i][j] >= MOD) c[i][j] -= MOD;
            }
        }
    }
    return c;
}


vector< vector<int> > power(vector< vector<int> > a, int b) {
    vector< vector<int> > res = a;
    --b;
    while (b) {
        if (b & 1) {
            res = mult(res, a);
        }
        a = mult(a, a);
        b >>= 1LL;
    }
    return res;
}


