int n,k;
bool bad[N];
vector<int>divi[N],need[N];
void add(int &a,int b){
	a+=b;
	if(a >= M)a-=M;
	if(a < 0)a+=M;
}
int power(int base,int to){
	int ret = 1;
	while(to){
		if(to&1)ret = ret*1LL*base%M;
		to>>=1;
		base = base*1LL*base%M;
	}
	return ret;
}
int main(){
	scanf("%d%d",&n,&k);
	for(int i = 2;i < N;i++)
		if(divi[i].empty())
			for(int j = i;j < N;j+=i){
				if(!(j%(i*1LL*i)))bad[j] = 1;
				divi[j].push_back(i);
			}
	for(int i = 2;i < N;i++)
		for(int j = i;j < N;j+=i)
			need[j].push_back(i);
	int ans = 0,sum = 0,temp = 0;
	for(int i = 1;i <= k;i++){
		sum = power(i,n);
		for(auto j : need[i]){
			if(bad[j])continue;
			add(temp,-power((i - 1)/j,n)*(divi[j].size()%2 ? 1 : -1));
			add(temp,power(i/j,n)*(divi[j].size()%2 ? 1 : -1));
		}
		add(sum,-temp);
		add(ans,sum^i);
	}
	printf("%d\n",ans);
}

