  ll int binomial(ll int n, ll int k,ll m) 
{ 
    ll int C[k+1]; 
    memset(C, 0, sizeof(C)); 

    C[0] = 1;  // nC0 is 1 

    for (ll int i = 1; i <= n; i++) 
    { 
        // Compute next row of pascal triangle using 
        // the previous row 
        for (int j = min(i, k); j > 0; j--) 
            C[j] = add(C[j],C[j-1]); 
    } 
    return C[k]%m; 
} 
