int bfs(int x, int y) {
	queue<pair<int, pair<int, int>>>q;
	q.push({ x,{y,0} });
	while (q.size()) {
		x = q.front().first;
		y = q.front().second.first;
		int c = q.front().second.second;
		q.pop();
		if (!x && !y)return c;
		if (x - 1 >= 0)
			q.push({ x - 1,{ y,c + 1 } });
		if (y - 1 >= 0)
			q.push({ x ,{ y - 1,c + 1 } });
		if (y - 1 >= 0 && x - 1 >= 0)
			q.push({ x - 1 ,{ y - 1,c + 1 } });
	}
}

