vector<unsigned long long> acc;
unsigned long long solve(unsigned long long w, int x){
	if(x == -1) return 0;
	// if(w >= acc[x]) return w - acc[x];
	auto it = f.find(make_pair(w, x));
	if(it != f.end()) return it->second;
	unsigned long long ans = solve(w, x - 1);
	for(int i = 1; i <= u[x].second; i++){
		unsigned long long v = u[x].first * i;
		if(v <= w){
			ans = max(ans, v + solve(w - v, x - 1));
		}
	}
	return f[make_pair(w,x)]=ans;
}
int main(){
	unsigned long long w; scanf("%llu", &w);
	map<unsigned long long, unsigned long long> g;
	for(i = 1; i <= 8; i++){
		unsigned long long x; scanf("%llu", &x);
		g[i] = x;
	}
	while(!g.empty()){
		auto [pt, qt] = *g.begin(); g.erase(g.begin());
		if(qt == 0) continue;
		if(qt <= 2) u.push_back(pair(pt, qt));
		else {
			if(qt%2){
				u.push_back(pair(pt, 1));
				g[pt*2] += qt/2;
			} else {
				u.push_back(pair(pt, 2));
				g[pt*2] += (qt-2)/2;
			}
		}
	}
	unsigned long long ac = 0;
	for(auto [pt, qt] : u) {
		ac += pt * qt;
		acc.push_back(ac);
	}
	cout << solve(w, int(u.size()) - 1) << endl;
	return 0;
}

