	double beta = p[idx].alpha - atan2(p[idx].x - s, p[idx].y);
	return p[idx].x + tan(beta) * p[idx].y;
}

int main()
{
	ios::sync_with_stdio(0);
	cin.tie(0);
	cin >> n >> l >> r;
	FOR (i, 0, n - 1)
	{
		cin >> p[i].x >> p[i].y >> p[i].alpha;
		p[i].alpha *= M_PI / 180.0;
	}
	FOR (mask, 0, (1 << n) - 1)
		FOR (i, 0, n - 1)
		{
			double tmp = l;
			if (mask & (1 << i))
			{
				int mask2 = mask - (1 << i);
				FOR (j, 0, n - 1)
					if (mask2 & (1 << j))
						tmp = max(tmp, calc(i, dp[j][mask2]));
				if (!mask2)
					tmp = max(tmp, calc(i, l));
			}
			dp[i][mask] = tmp;
			ans = max(ans, dp[i][mask] - l);
		}
	cout.precision(9);
	cout << fixed << min(ans, r - l) << endl;
	return 0;
}

