typedef pair<int, int> pos;

int gcd(int a, int b)
{
    if (a >= b) {
        if (a%b == 0)
            return b;
        else
            return gcd(b, a%b);
    } else {
        if (b%a == 0)
            return a;
        else
            return gcd(a, b%a);
    }
}

pos simplify(pos a) {
	if (a.first == 0 && a.second != 0) {
		a.second = 1;
		return a;
	} else if (a.first != 0 && a.second == 0) {
		a.first = 1;
		return a;
	} else if (a.first < 0 && a.second < 0) {
		a.first = -a.first;
		a.second = -a.second;
	}

	while(true) {
		int ggcd = gcd(a.first, a.second);
		if (ggcd == 1) break;
		a.first /= ggcd;
		a.second /= ggcd;		
	}

	return a;
}

int main() {
	pos a, b, c;
	bool ans = false;

	cin >> a.first >> a.second >> b.first >> b.second >> c.first >> c.second;

	pos ab, bc;
	ab.first = a.first - b.first;
	ab.second = a.second - b.second;

	bc.first = b.first - c.first;
	bc.second = b.second - c.second;

	if (simplify(ab) == simplify(bc)) {
		ans = false;
	} else {
		ans = true;
	}

	cout << (ans ? "Yes" : "No") << endl;
	return 0;

}

