#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int M = sqrt(1e11) + 4;

ll n, k, l, r, ans = -1;

void calcA(ll t, bool flag = false) {
    for (ll a = 0; a <= n; ++a) {
        ll gt = t / (a + n);
        for (int j = -1; j <= 1; ++j) {
            ll g = gt + j;
            if (g < 0) {
                continue;
            }
            ll ato = t - r - n * g - a * g;
            if (ato < 0 || ato > a || ato > r || (n - r) < a - ato || (flag && ato == 0)) {
                continue;
            }

            ans = max(ans, a);
        }
    }
}

void calcG(ll t, bool flag = false) {
    for (ll g = 0; g < M; ++g) {
        ll tg = t - n * g - r;
        if (tg < 0) {
            continue;
        }
        ll ag = tg / g;
        for (int j = -2; j <= 1; ++j) {
            ll a = ag + j;
            ll ato = tg - a * g;
            if (ato < 0 || ato > a || ato > r || (n - r) < a - ato || (flag && ato == 0)) {
                continue;
            }
            ans = max(ans, a);
        }
    }
}

void calcA() {
    calcA(k);
    calcA(k + 1, true);
}

void calcG() {
    calcG(k);
    calcG(k + 1, true);
}

void solve() {
    cin >> n >> l >> r >> k;
    l--, r--;
    r = (r - l + n) % n + 1;

    if (n < M) {
        calcA();
    } else {
        calcG();
    }

    cout << ans;
}

int main() {
    ios::sync_with_stdio(0);
    cout.tie(0), cin.tie(0);

    solve();

    return 0;
}

