  long long ans = 0;
  for (int x = 1; x <= 9; ++x) {
    for (int y = x; y <= 9; ++y) {
      if (gcd(x, y) != 1) continue;
      long long res = solve(x, y);
      ans = (ans + res) % mod;
      if (x != y)
        ans = (ans + res) % mod;
    }
  }
  printf("%lld\n", ans);
  return 0;
}

