int n, h, m, digh=0, digm=0, rst=0;
vi h7, m7, nowh, nowm;


bool convert()
{
  while (h)
  {
    h7.pb(h%7);
    h /= 7;
    ++digh;

    if (digh>7) return 0;
  }
  reverse(all(h7));

  while (m)
  {
    m7.pb(m%7);
    m /= 7;
    ++digm;

    if (digm>7) return 0;
  }
  reverse(all(m7));

if (digm+digh > 7) return 0;
return 1;
}


bool check_m()
{
  rep(i, digm)
  {
    if (nowm[i] != m7[i]) return 0;
  }

return 1;
}

bool check_h()
{
  rep(i, digh)
  {
    if (nowh[i] != h7[i]) return 0;
  }

return 1;
}


bool check_unique()
{
  bit vis=0;

  for (auto j: nowh)
  {
    if (vis[j]) return 0;
    vis[j] = 1;
  }

  for (auto j: nowm)
  {
    if (vis[j]) return 0;
    vis[j] = 1;
  }

return 1;
}


void shift_h()
{
  for (int i=digh-1; i>0; --i)
  {
    if (nowh[i] > 6)
    {
      nowh[i] = 0;
      ++nowh[i-1];
    }
    else break;
  }

  if (check_h() && check_m())
  {
    rst += check_unique();
    cout<<rst; exit(0);
  }
}

void shift_m()
{
  for (int i=digm-1; i>0; --i)
  {
    if (nowm[i] > 6)
    {
      nowm[i] = 0;
      ++nowm[i-1];
    }
    else break;
  }

  if (check_h() && check_m())
  {
    rst += check_unique();
    cout<<rst; exit(0);
  }

  if (check_m())
  {
    rst += check_unique();
    rep(i, digm) nowm[i] = 0;
    ++nowh[digh-1];

    shift_h();
  }
}


void iterate()
{
  rep(q, digh) nowh.pb(0);
  rep(q, digm) nowm.pb(0);

  while (true)
  {
    ++nowm[digm-1];
    shift_m();

    rst += check_unique();

    ps(nowm); ps(nowh);
    pv(rst);endr;
  }

cout<<rst;
}


