const int mod = 1e9 + 7;

int pw (int a,int p,int mod ) {
    int res=1%mod,x=a%mod;
    while (p) {
        if (p&1) res=(res*x)%mod;
        x=(x*x)%mod; p>>=1;
    }
    return res;
}

int C(int k, int n) {
    int a=1, b=1, c=1;
    for(int i=1;i<=n;i++) a=(a*i)%(mod);

    for(int i=1;i<=k;i++) b=(b*i)%(mod);

    for(int i=1;i<=(n-k);i++) c=(c*i)%(mod);

    b=pw(b,mod-2,mod);
    c=pw(c,mod-2,mod);
    a=(a*b)%mod;
    a=(a*c)%mod;
    return a;
}

