		int mul = 0;
		if(f >= i - 1 && i > 1) mul += C(i - 2, f - 1);
		if(f >= i) mul += 2 * C(i - 1, f - 1);
		if(f >= i + 1) mul += C(i, f - 1);
		mul %= mod;
		okcnt = (okcnt + add * mul) % mod;
	}
	for(int i=1;i<=w;i++){
