            } return 0;
        }
    } for (y = 1; y < a.size() - 1; ++y) {
        if (a[y] == k) {
            cout << p + 1 << endl;
            return 0;
        }
        if (a[y] != a[y + 1] - 1) {
            if (k >= a[y] && k <= a[y + 1]) {
                cout << k - a[y] - 1 << endl;
                return 0;
            }else {
                p += a[y + 1] - a[y] - 1;
            }
        }
    } if (k > a[a.size() - 1])
        cout << k - a[a.size() - 1] - 1 << endl;
    else if (k == a[a.size() - 1])
        cout << p + 1 << endl;
    return 0;
}

