using namespace std; 
#define int long long 
const int M = 998244353;

int power(int a,int b){
    int res=1;a%=M;
    while(b){
        if(b&1)res=res*a%M;
        a=a*a%M;b>>=1;
    }
    return res;
}

int32_t main(){
    ios_base::sync_with_stdio(false); 
    cin.tie(NULL); cout.tie(NULL);
    int n,m,k;
    cin>>n>>m>>k;
    m = power(m,M-2);
    vector<int> fact(k+1,1);
    for(int i=1;i<=k;++i)
        fact[i]=i*fact[i-1]%M;
    auto ncd = [&](int d){
        if(n<d)return 0LL;
        int res=1;
        for(int i=n;i>=n-d+1;--i){
            res = res*i%M;
        }
        return res*power(fact[d],M-2)%M;
    };
    auto dci = [&](int i,int d){
        return fact[d]*power(fact[d-i]*fact[i]%M,M-2)%M;
    };
    auto ways = [&](int d){
        int res=0;
        int cnt = 1;
        for(int i=d;i>=0;--i){
            res = (res+cnt*power(i,k)%M*dci(i,d)%M+M)%M;
            cnt = -cnt;
        }
        return res;
    };
    int ans=0;
    for(int d=1;d<=k;++d){
        int tmp = power(m,d)*ncd(d)%M;
        tmp = (tmp*ways(d)%M);
        ans =(ans+tmp+M)%M;
    }
    cout << ans << endl;
    return 0;
}

