	a %= mod;
	if (!(b & 1)) return pow((a * a) % mod, b >> 1, mod) % mod;
	if (b & 1) return a * pow(a, b - 1, mod) % mod;
	return 1;
}
ll inv(int i) {
	return pow(i, mod - 2, mod) % mod;
}

int main() {
	int n, m;
	cin >> n >> m;
	ll res = m + 1;
	for (int i = 2; i <= n; i++) {
		ll tmp = m * inv(i);
		tmp %= mod;
		res  += tmp;
		res %= mod;
	}
	ll tmp = n * inv(m + 1);
	tmp %= mod;
	tmp++;
	res *= tmp;
	res %= mod;
	res = (res + mod) % mod;
	cout << res << endl;
	return 0;
}

