const int N = 2025;
const int M = 65;
const int MOD = 998244353;

int dp2[N][M][N]; // [sum][len][last] easy MLE
int dp1[N][N];

int n, k;

void add(int &a, int b){
  a += b;
  if(a >= MOD)
    a -= MOD;
}

void solve1(){
  for(int i = 0 ; i <= n; i ++ )
    dp1[0][i]=1;
  int ans = 0;
  for(int i = 1; i <= n; i ++ ){
    for(int j = 1; j <= n; j ++ ){
      if(i >= j){
        add(dp1[i][j],dp1[i-j][j]);
        add(ans, dp1[i][j]);
      }    
      add(dp1[i][j],dp1[i][j-1]);
    }
  }
  cout << ans << "\n";
}

void solve2(){
  for(int i = 0 ; i < N; i  ++ )
    dp2[0][0][i]=1;
  int ans = 0;
  for(int i = 1; i <= n; i ++ ){
    for(int j = 1; j < M; j ++ ){
      for(int x = n; x >= 1; x -- ){
        if(i >= j*x){
          add(dp2[i][j][x],dp2[i - j * x][j - 1][x]);
          add(ans, dp2[i][j][x]);
        }
        add(dp2[i][j][x],dp2[i][j][x+1]);
      }
    }
  }
  cout << ans << "\n";
}

bool can(vector<int> t){
  if(t.size() > n)
    return false;
  for(int op = 0; op < k ; op ++ ){
    vector<int> nx;
    reverse(t.begin(), t.end());
    for(int i = 0 ; i < t.size();i ++ ){
      for(int j = 0; j < t[i]; j ++ )
        nx.push_back(i + 1);
    }
    t = nx;
    if(t.size() > n)
      return false;
  }
  return true;
}

int res = 0;

void brute(vector<int> t){
  if(t.empty()){
    for(int i = 1; i <= n; i ++ ){
      t.push_back(i);
      if(!can(t))
        return;
      brute(t);
      t.pop_back();
    }
    return;
  }
  res ++ ;
  for(int i = t.back(); i <= n; i ++ ){
    t.push_back(i);
    if(!can(t))
      return;
    brute(t);
    t.pop_back();
  }
}

int main(){
  fastIO;
  cin >> n >> k;
  if(k == 1) solve1();
  else if(k == 2){
    solve2();
  }
  else{
    brute({});
    cout << res << "\n";
  }
  return 0;
}

