} ans, base; 

Matrix operator * (Matrix a, Matrix b) {
	Matrix c; c.init();
	for(int i = 0; i < 2; i++) {
		for(int j = 0; j < 2; j++) {
			for(int k = 0; k < 2; k++) {
				c.num[i][j] = (c.num[i][j] + 1ll * a.num[i][k] * b.num[k][j] % mod) % mod;
			}
		}
	}
	return c;
}

inline void qpow(ll b) {
	if(b < 0) return;
	base.init(); 
	base.num[0][0] = base.num[0][1] = base.num[1][0] = 1;
	while(b) {
		if(b & 1) ans = ans * base;
		base = base * base;
		b >>= 1;
	}
}

inline int fib(int x) {
	ans.num[0][0] = ans.num[0][1] = 1;
	if(x == 0) return 0;
	qpow(x - 2);
	return ans.num[0][0];
}

