	a = f[p].substr(0, lens - 1);
	b = f[p].substr(len[p] - lens + 1, lens - 1);
	c = f[p + 1].substr(len[p + 1] - lens + 1, lens - 1);


	int n0, n1, n2, n3; ll pos = n - p, ret = 0;
