int dinic() {
    int res = 0;
    while(true) {
        fill(graph.lev, graph.lev + N, 0);
        fill(graph.ptr, graph.ptr + N, 0);
        graph.lev[s] = 1;
        if(!bfs()) {
            break;
        }
        while(int flow = dfs(s, 1)) {
            res += flow;
        }
    }
    return res;
}

void solve() {
    if(min(n, m) >= 20) {
        cout << 1ll * n * m / 2 * 2 << "\n";
        return;
    }
    s = 0, t = N - 1;
    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < m; ++j) {
            if(i + j & 1) {
                for(pii p: adj) {
                    int I = i + p.xx;
                    int J = j + p.yy;
                    if(I < 0 || J < 0 || I >= n || J >= m) {
                        continue;
                    } else {
                        add_edge(id(i, j), id(I, J), 1);
                    }
                }
                add_edge(s, id(i, j), 1);
            } else {
                add_edge(id(i, j), t, 1);
            }
        }
    }
    cout << 2 * dinic() << "\n";
}

