int32_t answer = 0;

int32_t get_root(int32_t vertex, int32_t* parents) {
	if(parents[vertex] == vertex)
		return vertex;
	return parents[vertex] = get_root(parents[vertex], parents);
}

bool join(int32_t v1, int32_t v2, int32_t* parents) {
	int32_t root1 = get_root(v1, parents);
	int32_t root2 = get_root(v2, parents);
	if(root1 == root2)
		return false;
	parents[root1] = root2;
	return true;
}

void check(int32_t num_steps, int32_t* choices, std::vector<std::pair<int32_t, int32_t> >& edges, int32_t leaf_target) {
	int32_t* deg = new int32_t[num_steps + 1];
	int32_t* parents = new int32_t[num_steps + 1];
	for(int32_t i = 0 ; i <= num_steps; i++) {
		deg[i] = 0;
		parents[i] = i;
	}

	for(int32_t i = 0 ; i < num_steps; i++) {
		deg[edges[choices[i]].first]++;
		deg[edges[choices[i]].second]++;
		if(!join(edges[choices[i]].first, edges[choices[i]].second, parents))
			return;
	}

	int32_t num_leaves = 0;
	for(int32_t i = 0;  i <= num_steps; i++)
		num_leaves += (deg[i] == 1 ? 1 : 0);

	if(num_leaves == leaf_target)
		answer++;

	delete [] parents;
	delete [] deg;
}

void enumerate(int32_t step, int32_t num_steps, int32_t* choices, std::vector<std::pair<int32_t, int32_t> >& edges, int32_t leaf_target) {
	if(step == num_steps) {
		check(num_steps, choices, edges, leaf_target);
	} else {
		for(int32_t i = (step == 0 ? 0 : choices[step - 1] + 1); i < edges.size(); i++) {
			choices[step] = i;
			enumerate(step + 1, num_steps, choices, edges, leaf_target);
		}
	}
}

int main() {
	int32_t n, m, num_ends;
	std::cin >> n >> m >> num_ends;

	std::vector<std::pair<int32_t, int32_t> > edges;
	for(int32_t i = 0 ; i < m ; i++) {
		int32_t src, dst;
		std::cin >> src >>  dst;
		src--;
		dst--;

		edges.emplace_back(src, dst);
	}
	//for(itn32_t i = 0; i < n ; i++)

	int32_t* choices = new int32_t[n - 1];
	enumerate(0, n - 1, choices, edges, num_ends);

	std::cout << answer;
	return 0;
}

