#include <bits/stdc++.h>

#define long long long

using namespace std;

const int MAXN = 1e5 + 10;
const int LIM = 2e9;
const int MAXX = 5e2 + 10;
const int MAXY = 1e5 + 10;

int L, R, K, prSize;
int cnt[MAXN], pr[MAXN];

long f[MAXX][MAXY];

bool fre[MAXN];

void Init() {
	for (int i = 2; 1LL * i * i < MAXN; ++i) if (fre[i] == false)
		for (int j = 2 * i; j < MAXN; j += i) fre[j] = true;
	for (int i = 2; i < MAXN; ++i) {
		if (fre[i] == false) pr[prSize++] = i;
		cnt[i] = prSize;
	}
	for (int i = 0; i < MAXX; ++i)
		for (int j = 0; j < MAXY; ++j) {
			if (i == 0) f[i][j] = j;
			else f[i][j] = f[i - 1][j] - f[i - 1][j / pr[i - 1]];
		}
}

bool isPrime(int n) {
	for (int i = 2; 1LL * i * i <= n; ++i) if (n % i == 0) return false;
	return true;
}

long Calc(int n, long m) {
	if (!n) return m;
	if (pr[n - 1] >= m) return 1;
	if (n < MAXX && m < MAXY) return f[n][m];
	return Calc(n - 1, m) - Calc(n - 1, m / pr[n - 1]);
}

int main() {
	Init();
	cin >> L >> R >> K;
	if (isPrime(K) == false) {
		cout << 0 << '\n';
	} else {
		if (1LL * K * K > LIM) cout << (L <= K && K <= R) << '\n';
		else {
			--L;
			// cout << R / K << " " << L / K << ' ' << cnt[K] << '\n';
			// cout << Calc(cnt[K] - 1, R / K) << ' ' << Calc(cnt[K] - 1, L / K) << '\n';
			cout << Calc(cnt[K] - 1, R / K) - Calc(cnt[K] - 1, L / K) << '\n';
		}
	}
	return 0;
}

