int Cost(int numofcity, int tank)
{
	int cities = numofcity - 1;
	int fact = 1;
	int money = 0;
	while (cities!=-1)
	{
		if (cities==tank-1)
		{
			return money;
		}
		if (fact == 1)
		{
			money = tank;
		}
		else
		{
			money = money + fact;
		}
		cities--;
		fact++;
	}
}

