ll solve(ll r, ll c, ll k, ll n){
  if(dp[r][c]!=-1){
    return dp[r][c];
  }
  ll x, y = 0, z;
  // tr2(r,c);
  if (c==0){
    z = power((power(k,n) - power(k-1, n) + MOD)%MOD, r);
    dp[r][c] = z;
    return z;
  }
  if(r==1){
    z = power(k, n-c);
    dp[r][c] = z;
    return z;
  }

  x = (((power(k, n-c) - power(k-1, n-c) + MOD)%MOD)*solve(r-1, c, k, n)%MOD)*power(k-1, c)%MOD;
  for(int i = 1; i<=c; i++){
    y += ((com[c][i]*solve(r-1, c - i, k, n)%MOD)*power(k-1, c - i)%MOD)*power(k, n-c);
    y %= MOD;
  }
  z = (x+y)%MOD;
  dp[r][c] = z;
  // tr3(r, c, z);
  return z;
}
