struct nn{
	LL a[MX][MX];
	void MEM(){rep(i,0,maxn)rep(j,0,maxn)a[i][j]=0;}
}hlp;

nn MUL(nn A,nn B){
	nn C;C.MEM();
	rep(i,1,tot)rep(j,1,tot){
		C.a[i][j]=0;
		rep(r,1,tot){
			C.a[i][j]+=A.a[i][r]*B.a[r][j]%MOD;
			C.a[i][j]%=MOD;
		}
	}
	return C;
}

LL KSM(int y){
	nn res;res.MEM();
	LL ans;
	res.a[1][1]=1;
	while(y){
		if(y%2==1)res=MUL(res,hlp);
		hlp=MUL(hlp,hlp);
		y/=2;
	}
	rep(num,0,maxn)ans=(ans+res.a[1][get[k][num]])%MOD;
	return ans;
}

