int multiply(int x, vector<int> &result, int res_size) {
	int carry = 0;

	for (int i = 0; i < res_size; i++) {
		int prod = result[i] * x + carry;

		result[i] = prod % 10;

		carry = prod / 10;
	}

		while (carry) {
			result[res_size] = carry % 10;
			carry = carry / 10;
			res_size++;
			}
	return res_size;
}

vector<int> power(int x, int n) {
	int temp = x;
	vector<int> result(range);
	int res_size = 0;


	while (temp != 0) {
		result[res_size] = temp % 10;
		res_size++;
		temp = temp / 10;
	}

	for (int i = 2; i <= n; i++)
		res_size = multiply(x, result, res_size);

	// cout << x << "^" << n << " = ";
