#define BASE 1000000007;
using namespace std;
map<pair<__int32, __int32>, __int32> storedvalue;
__int32 findvalue(__int32 i, __int32 j)
{
	__int32 result;
	pair<__int32, __int32> index = make_pair(i, j);
	if (storedvalue.count(index))return storedvalue[index];
	if (i > j)result = findvalue(j,i);
	else if (i == 1)result = j;
	else if (i == j)result = 1;
	else if (j == i + 1 && i % 2 == 1)result = 2;
	else if (i == 2 && j % 2 == 0)result = j - 1;
	else if (i == 2 && j % 2 == 1)result = j + 1;
	else if (j % 4 == 1 || j % 4 == 2)result = 2 + findvalue(i-2,j);
	else if (j % 4 == 3 || j % 4 == 0)result = -2 + findvalue(i - 2, j);
	else result = 0;
	storedvalue.insert(make_pair(index, result));
	return result;
}

int main()
{
	int q;
	cin >> q;
	for (int i = 0; i < q; i++)
	{
		__int32 x1, y1, x2, y2, K;
		cin >> x1 >> y1 >> x2 >> y2 >> K;
		int ans = 0;
		for (__int32 j = x1; j <= x2; j++)
		{
			for (__int32 k = y1; k <= y2; k++)
			{
				__int32 temp = findvalue(j, k);
				if (temp > K)continue;
				else ans = (ans + temp) % BASE;
			}
		}
		cout << ans << endl;
	}
}

