using namespace std;

const int MOD = 998244353, MAXN = 500005;
int fact[MAXN];

void calcFacts() {
    fact[0] = 1;
    for (int i = 1; i < MAXN; i++)
        fact[i] = (fact[i - 1] * i) % MOD;
}

int powMod(int a, int e) {
    int r = 1;
    while (e) {
        if (e & 1)
            r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int invMod(int a) {
    return powMod(a, MOD - 2);
}

int choose(int n, int k) {
    if (k > n)
        return 0;
    return (fact[n] * invMod((fact[k] * fact[n - k]) % MOD)) % MOD;
}

int main() {
    calcFacts();

    int n, k;
    cin >> n >> k;

    int answer = 0;
    for (int i = 1; i < MAXN; i++) {
        answer = (answer + choose(n / i - 1, k - 1)) % MOD;
    }

    cout << answer;
}

