const int N = (int)3e4;
int n, a, q;
namespace convolution
{
	int rev[N << 2], len;
	inline int initialize(int n)
	{
		len = 1;
		int tmp = 0;
		for(; len < n << 1; ++ tmp, len <<= 1);
		rev[0] = 0;
		for(int i = 1; i < len; ++ i)
			rev[i] = rev[i >> 1] >> 1 | (i & 1) << tmp - 1;
	}
	struct complex
	{
		double rl, img;
		inline complex() {}
		inline complex(double _rl, double _img)
		{
			rl = _rl, img = _img;
		}
		inline complex friend operator +(complex a, complex b)
		{
			return complex(a.rl + b.rl, a.img + b.img);
		}
		inline complex friend operator -(complex a, complex b)
		{
			return complex(a.rl - b.rl, a.img - b.img);
		}
		inline complex friend operator *(complex a, complex b)
		{
			return complex(a.rl * b.rl - a.img * b.img, a.rl * b.img + b.rl * a.img);
		}
	}A[N << 2], B[N << 2];
	double PI = acos(-1);
	inline void FFT(complex *a, int opt)
	{
		for(int i = 0; i < len; ++ i)
			if(rev[i] < i)
				std::swap(a[i], a[rev[i]]);
		for(int i = 2; i <= len; i <<= 1)
		{
			complex omega_i = complex(cos(2 * PI * opt / i), sin(2 * PI * opt / i));
			for(int j = 0; j < len; j += i)
			{
				complex omega = complex(1, 0);
				for(int k = j; k < j + i / 2; ++ k)
				{
					complex u = a[k], t = a[k + i / 2] * omega;
					a[k] = u + t, a[k + i / 2] = u - t;
					omega = omega * omega_i; 
				}
			}
		}
		if(opt == -1)
			for(int i = 0; i < len; ++ i)
				a[i].rl /= len;
	}
	inline void work(int *a, int *b, int n, long long *res)
	{
		memset(A, 0, sizeof(A)), memset(B, 0, sizeof(B));
		for(int i = 0; i < n; ++ i)
			A[i] = complex(a[i], 0), B[i] = complex(b[i], 0);
		FFT(A, 1), FFT(B, 1);
		for(int i = 0; i < len; ++ i)
			A[i] = A[i] * B[i];
		FFT(A, -1);
		for(int i = 0; i < len; ++ i)
			res[i] = round(A[i].rl);
	}
}
int f[N + 1][2], _f[N + 1][2];
int ans;
inline void update()
{
	for(int i = 1; i <= n; i += 2)
		ans = (ans + f[i][1]) % q;
}
void work(int b)
{
    cout << b << ' ';
	if(b == 1)
	{
		memset(f, 0, sizeof(f));
		f[1][1] = 1;
		update();
		return;
	}
	work(b / 2);
	static int x[N + 1], y[N + 1];
	std::swap(f, _f);
	for(int i = 0; i <= n; ++ i)
		x[i] = (_f[i][0] + _f[i][1]) % q;
	for(int i = 0; i < 2; ++ i)
	{
		for(int j = 0; j <= n; ++ j)
			y[j] = _f[j][i ^ (b >> 1 & 1)];
		static long long res[N << 2];
		convolution::work(x, y, n, res);
		for(int j = 0; j <= n; ++ j)
			f[j][i] = (res[j] + _f[j][i] + _f[j][i ^ (b >> 1 & 1)]) % q;
	}
	if(b & 1)
	{
		std::swap(f, _f);
		for(int i = 0; i < 2; ++ i)
		{
			f[0][i] = _f[0][i];
			for(int j = 1; j <= n; ++ j)
				f[j][i] = (_f[j][i] + (i ^ (b & 1) ? 0 : (j == 1 ? 1 : _f[j - 1][0] + _f[j - 1][1]))) % q;
		}
	}
	update();
}
