long long GCD(long long a,long long b)            //求最大公因数
{
    if(b>a)
        swap(a,b);
    long long c;
    while(b>0)
    {
        c=a%b;  a=b;    b=c;
    }
    return a;
}
long long a[1000],b[1000],t[1000];
void A_741()
{
    int n,i,j;
    cin>>n;
    for(i=0;i<1000;i++)
    {
        a[i]=1;b[i]=1;t[i]=1;
    }
    for(i=0;i<n;i++)
    {
        cin>>a[i];
        b[i]=a[i];
        t[i]=0;
    }
    for(i=0;i<n;i++)
    {
        for(j=0;j<n;j++)
        {
            if(b[i]==i+1)
            {
                t[i]=1;
                break;
            }
            b[i]=b[b[i]-1];
            t[i]++;
            if(b[i]==i+1)
            {
                t[i]++;
                break;
            }
            if(t[i]==4 && b[i]!=i+1)
                t[i]=-1;
        }
        b[i]=a[i];
    }
    for(i=0;i<n;i++)
    {
        if(t[i]>0 && t[i]%2==0)
            t[i]=t[i]/2;
    }
    long long temp,ans;
    for(i=1;i<n;i++)
    {
        j=i-1;
        temp=t[i];
        while(j>=0 && t[j]>temp)
        {
            t[j+1]=t[j];
            j--;
        }
        t[j+1]=temp;
    }
    ans=t[0];
    if(ans!=-1)
    {
        for(i=n-1;i>0;i--)
        {
            if(t[i-1]==-1)
                break;
            if(t[i]!=-1)
            {
                ans=ans/GCD(ans,t[i-1])*t[i-1];       //最小公倍数与最大公因数的求法
            }
        }
    }
    cout<<ans<<endl;
}
int main()
{
    A_741();
    return 0;
}

