const int maxn = 1e8 + 1;

int n, b, top_divisor = 0;
ll ans = 1e18;
int freq[maxn];
int divisor[maxn];
int brr[maxn];

void find_divisors(int b) {
	int i = 2;
	while (b > 1) {
		if (b%i == 0) {
			int max = i;
			while (b%i == 0) {
				b /= i;
				divisor[++top_divisor] = max;
				freq[max]++;
			}
		}
		++i;
	}
}

int count_zero(int n, int div) {
	int ret = 0;
	while (n >= div) {
		n /= div;
		ret += n;
	}
	return ret;
}

int main() {

	ios::sync_with_stdio(false);

	//freopen("D:\in.txt", "r", stdin);

	cin >> n >> b;
	find_divisors(b);
	ite(i, 1, top_divisor) {
		int count = count_zero(n, divisor[i]) / freq[divisor[i]];
		if (ans > count)
			ans = count;
	}
	cout << ans << endl;

	return 0;
}

