#include <iostream>
using namespace std;
int main()
{
	int t, s, q, ans = 0;
	cin>>t>>s>>q;
	ans = 1;
	double loaded = s, everysec = double(q-1)/double(q), reached = 0;
	while (reached != t)
	{
		reached += 1;
		loaded += everysec;
		if (reached > loaded)
		{
			loaded -= everysec;
			reached -= 1;
			double diff = loaded - reached;
			double t = diff/(1-everysec);
			reached = 1-t;
			ans++;
		}
	}
	cout<<ans<<"\n";
}

