int minimum(int a,int b,int k1,int k2,int m){
    if(a*k1+b*k2==m) return a+b;
    else{
        int x,y,cnt;
        if(k1<k2){
            x=b*(k2-1);
            if(x>=m) return 0;
            y=m-x;
            x=y%(k1-1);
            y=y/(k1-1);
            if(y>a) x=(y-a)*(k1-1);
        }
        else{
            x=a*(k1-1);
            if(x>=m) return 0;
            y=m-x;
            x=y%(k2-1);
            y=y/(k2-1);
            if(y>b) x=(y-b)*(k2-1);
        }
        return x;
    }
}

int maximum(int a,int b,int k1,int k2,int m){
    int cnt,y,x;
    if(k1>k2) {cnt=b;x=b*k2;y=m-x;cnt+=y/k1;}
    else {cnt=a;x=a*k1;y=m-x;cnt+=y/k2;}
    return cnt;
}

