using namespace std;

const int maxN=200005;
const LL mod=1000000007;

int n, q;
LL a[maxN], w[maxN];

LL bit[maxN][2];

void update (int id, int p, LL v) {
	for (int i=p+1; i<maxN; i+=i&(-i))
		bit[i][id]=(bit[i][id]+v)%mod;
}

LL query (int id, int p) {
	LL res=0;
	for (int i=p+1; i; i-=i&(-i))
		res=(res+bit[i][id])%mod;
	return res;
}

int main (int argc, char ** argv) {
	scanf("%d %d", &n, &q);
	for (int i=0; i<n; i++) {
		scanf("%lld", &a[i]);
		a[i]-=i;
	}
	for (int i=0; i<n; i++) {
		scanf("%lld", &w[i]);
		update(0, i, w[i]);
		update(1, i, (w[i]*a[i])%mod);
	}
	LL x, y;
	while (q--) {
		scanf("%lld %lld", &x, &y);
		if (x<0) {
			x=-x-1;
			update(0, i, y-w[i]);
			update(1, i, ((y-w[i])*a[i])%mod);
		}
		else {
			x--; y--;
			LL sum=(query(0, y)-query(0, x-1))/2;
			int l=x, r=y, m;
			while (l<r) {
				m=(l+r)>>1;
				if (query(0, m)-query(0, x-1)<=sum)
					l=m;
				else
					r=m;
			}
			LL lsw=(((query(0, r-1)-query(0, x-1)+mod)%mod)*a[r])%mod, lsaw=(query(1, r-1)-query(1, x-1)+mod)%mod;
			LL rsw=(((query(0, y)-query(0, r)+mod)%mod)*a[r])%mod, rsaw=(query(1, y)-query(1, r)+mod)%mod;
			LL ans=(lsw-lsaw+rsaw-rsw)%mod;
			while (ans<0)
				ans=(ans+mod)%mod;
			printf("%lld\n", ans);
		}
	}
	return 0;
}

