int * can_do(int *solved, int on)
{
    int *res1 = new int[n];
    rep(i,n) res1[i] = 0;

    rep(i,n)
    {
        if (solved[i] == 1 || comp[i] != on) continue;
        bool f = true;
        for(int j=0;j<befor[i].size();j++)
            if (solved[befor[i][j]] == 0 && comp[befor[i][j]] != on) f = false;
        if (f) res1[i] = 1;
    }

    int *res2 = new int[n];
    rep(i,n) res2[i] = 0;
    rep(i,n)
    {
        if (res1[i] == 0) continue;
        bool f = true;
        for(int j=0;j<befor[i].size();j++)
            if ((solved[befor[i][j]] == 0 && comp[befor[i][j]] == on && res1[befor[i][j]] == 0)) f = false;
        if (f) res2[i] = 1;
    }

    return res2;
}

int do_best(int *solved, int on)
{
    int c = 0;
    rep(i,n) if (solved[i]==1) c++;
    if (c==n) return 0;

    int min_t = 32000;
    rep(i,3)
    {
        int *can = can_do(solved,i);
        c = 0;
        rep(j,n) if (can[j] == 1) c++;
        if (c==0) continue;

        int *n_solved = new int[n];
		rep(j,n) n_solved[j] = 0;
        rep(j,n) if (solved[j] == 1 || can[j] == 1) n_solved[j] = 1;
        int tt = do_best(n_solved,i) + t[on][i] + c;
        if (tt < min_t) min_t = tt;
        delete[] n_solved;
        delete[] can;
    }

    return min_t;
}
