        a[i].second = i;
        b[i].first.second = a[i].first.first;
        b[i].first.first = a[i].first.second;
        b[i].second = i;
    }
    sort(a+1 , a+n+1);
    sort(b+1 , b+n+1);
    int point = a[n-k].first.first;
    if(point + 2 <= n){
        for(int i=1 ; i<=point + 2 ; i++)
            sum += b[i].first.first;
        ans = sum;
    }
