const int MAXN = 3e2+5;
const int INF = 2e9;
const int MOD = 1e9+7;
int edge = 0, A[MAXN], B[MAXN];
vector<int> graph[MAXN], comp, path;
bool used[MAXN], suse[MAXN];
vector< pair< pair<int,int>,int > > RES;

void dfs(int v, int &addTo){
    addTo += A[v] - B[v];
    used[v] = true;

    for(int i=0;i<graph[v].size();i++){
        int to = graph[v][i];
        if(!used[to])
            dfs(to,addTo);
    }

    comp.push_back(v);
}

bool get_path(int v, int aim){
    if(v == aim){
        path.push_back(aim);
        return true;
    }

    for(int i=0;i<graph[v].size();i++){
        int to = graph[v][i];

        if(get_path(to,aim)){
            path.push_back(v);
            return true;
        }
    }

    return false;
}


void bring(int pos, int amount){
    if(pos + 1 == path.size()) return;

    while(amount){
        int curI = min(amount, edge - A[path[pos + 1]]);

        A[path[pos]] -= curI, A[path[pos + 1]] += curI, amount -= curI;
        RES.push_back( make_pair( make_pair(path[pos], path[pos + 1]), curI) );

        bring(pos + 1,curI);
    }

}

