                return printf("NO\n"),0;

            //printf("First stage successfully completed.\n");

            for(int ii=0;ii<comp.size();ii++)
                if(A[comp[ii]] != B[comp[ii]])
                    for(int jj=0;jj<comp.size();jj++){
                        if(ii == jj || A[comp[jj]] == B[comp[jj]]) continue;

