                        if(A[comp[ii]] < B[comp[ii]] && A[comp[jj]] > B[comp[jj]])
                            BEG = comp[jj], END = comp[ii], AMOUNT = min(B[comp[ii]] - A[comp[ii]], A[comp[jj]] - B[comp[jj]]);

