                            BEG = comp[ii], END = comp[jj], AMOUNT = min(A[comp[ii]] - B[comp[ii]], B[comp[jj]] - A[comp[jj]]);

                        if(BEG == 0 && END == 0) continue;
                        memset(suse,false,sizeof(suse));
