vector<ll> SieveOfEratosthenes(ll n) 
{ 
    vector <ll> res;
    bool prime[n+1]; 
    memset(prime, true, sizeof(prime)); 

    for (ll p=2; p*p<=n; p++) 
    { 
        if (prime[p] == true) 
        { 
            for (ll i=p*p; i<=n; i += p) 
                prime[i] = false; 
        } 
    } 

    for (ll p=2; p<=n; p++) 
       if (prime[p]) 
          res.pb(p);
    return res; 
} 
vector <ll> primeFactors(ll n)  
{  
    vector <ll> hash; 
    while (n % 2 == 0)  
    {  
        hash.pb(2); 
        n = n/2;  
    }  
    for (ll i = 3; i <= sqrt(n); i = i + 2)  
    {  
        while (n % i == 0)  
        {  
            hash.pb(i);
            n = n/i;  
        }  
    }  
    if (n > 2)  
        hash.pb(n);
    return hash;  
}  

unordered_map <ll, ll> myhash;
vector < vector <bool> > vis(5000001, vector <bool> (7,false));
void minpos( ll mask, ll idx, vector <ll> primes, ll &ans)
{
	ll t = mask;
	//cout<<t<<" mas "<<edl;

	bool full = true;
	if(idx >= 6)return;
	if(vis[mask][idx])return;
	ll m = primes.size();
	//cout<<m<<" m mmask "<<mask<<edl;
	vector <ll> dig(m, 0); ll cnt = 0;
	while(cnt < m)
	{
		if(t%10 == 0)full = false;
		dig[cnt] = t%10; cnt++;
		t = t/10;

		//cout<<"***";
	}
	//cout<<full<<" full "<<edl;
	if(full)
	{
		vector <ll> eachid(6,1);
		for(ll i =0; i < dig.size(); i++)
		{
			eachid[dig[i]] *= primes[i];
		}
		ll temp = 1;
		for(ll i = 1; i <= 5; i++)
		{
			//cout<<temp<<" temp "<<edl;
			//cout<<myhash[i]<<" "<<eachid[i]-1<<edl;
			temp *= pow(myhash[i], eachid[i]-1);
		}
		if(temp > 0)ans = min(ans, temp);
		vis[mask][idx] = true;
		return;
	}
	for(ll i = 0; i < primes.size(); i++)
	{
		if(dig[i] == 0)
		{
			ll newmask = mask;
			newmask += pow(10,i)*idx;
			minpos(newmask, idx, primes, ans);
			minpos(newmask, idx + 1, primes, ans);
		}
	}
	vis[mask][idx] = true;
	return;
}
void solve()
{
	ll n;
	cin>>n;
	myhash[1] = 2; myhash[2] = 3; myhash[3] = 5; myhash[4] = 7; myhash[5] = 11;
	ll ans = LLONG_MAX;
	vector <ll> primes = primeFactors(n);
	int add2 =0;
	while(primes.size() > 6)
	{
		primes.erase(primes.begin());
		add2++;
	}
	minpos(0,1, primes, ans);
	int cnt2 = 0, cnt3 = 0;
	ll temp = ans; 
	while(temp % 2 == 0)
	{
		temp = temp/2;
		cnt2++;
	}
	ans = (ll)pow(2, cnt2 + add2)*temp;
	while(temp % 3 == 0)
	{
		temp = temp/3;
		cnt3++;
	}
	if(add2 > 1)ans = min(ans, (ll)pow(2, cnt2 + add2 - 1)*temp*(ll)pow(3, cnt3 + 1));
	cout<<ans<<edl;
	return;
}

int main()
{
	solve();
	return 0;
}

