#include<bits/stdc++.h>
using namespace std;

const int N = 16 + 2;
int n, R, B, r[N], b[N], a[N];
int cnt[1 << N][2], dp[1 << N][N * N];

inline void readInput() {
	cin >> n;
	for (int i = 0; i < n; i++) {
		char c;
		cin >> c >> r[i] >> b[i];
		R += r[i], B += b[i];
		a[i] = (c == 'B');
	}
}

inline void solve() {
	memset(dp, -63, sizeof dp);
	dp[0][0] = 0;
	for (int i = 1; i < 1 << n; i++) {
		for (int j = 0; j < n * n; j++)
			for (int k = 0; k < n; k++)
				if (i >> k & 1) {
					int nxt = i ^ (1 << k);
					dp[i][j] = max(dp[i][j], dp[nxt][max(j - min(r[k], cnt[nxt][0]), 0)] + min(b[k], cnt[nxt][1]));
				}
		cnt[i][0] = cnt[i ^ i & -i][0];
		cnt[i][1] = cnt[i ^ i & -i][1];
		cnt[i][a[__builtin_ctz(i)]]++;
	}
}

inline void writeOutput() {
	int ans = 1e9, all = (1 << n) - 1;
	for (int i = 0; i < n * n; i++)
		if (dp[all][i] >= 0)
			ans = min(ans, max(R - i, B - dp[all][i]));
	cout << ans + n << endl;
}

int main() {
	ios:: sync_with_stdio(0), cin.tie(0), cout.tie(0);
	readInput(), solve(), writeOutput();
	return 0;
}

