#include <bits/stdc++.h>

using namespace std;

typedef long long LL;
vector<LL> factor;

LL GCD(LL a, LL b) {
  return b == 0 ? a : GCD(b, a % b);
}

LL sol(LL x, LL y, vector<LL>& f) {
  LL _ = GCD(x, y);
  x /= _;
  y /= _;
  if (x == 1) return y;
// cout << x << " " << y << endl;
  if (y == 0) return 0;
  if (y % x == 0) {
    return y / x;
  }
  LL min_d = numeric_limits<LL>::max();
  LL gcd;
  for (int i = 0; i < (int) f.size(); ++i) {
    if (f[i] > x) break;
    if (f[i] > y) break;
    if (x % f[i] != 0) continue;
    LL a = y / f[i];
    LL d = y - a * f[i];
    if (d >= 0 && d <= min_d) {
      min_d = d;
      gcd = f[i];
    }
  }
  if (min_d == numeric_limits<LL>::max()) {
    if (y > x) {
      return y - x + 1;
    } else {
      return y;
    }
  }
//  cout << min_d << endl;
  return min_d + 1 + sol(x, (y - min_d) - gcd, f);
}

int main() {
  LL x, y;
  cin >> x >> y;
  for (LL i = 2; i * i <= x; ++i) {
    if (x % i == 0) {
      factor.push_back(i);
      factor.push_back(x / i);
    }
  }
  sort(factor.begin(), factor.end());
  cout << sol(x, y, factor) << endl;
  return 0;
}

