using namespace std;

void Sort (int left, int right, int *mas) {
	int l = left, r = right, m = (left + right) / 2;
	while (l <= r) {
		while (mas[l] < mas[m])
			l++;
		while (mas[m] < mas[r])
			r--;
		if (l <= r) {
			int temp = mas[l];
			mas[l] = mas[r];
			mas[r] = temp;
		}
	}
	if (left < r)
		Sort (left, r, mas);
	if (l < right)
		Sort (l, right, mas);
}

