ll const lots=1000000009ll;
int n,h;

static int memo[1000][32][32][32][32];
ll plough[100];

int calc(int n,int a,int b,int c,int d){
  a=min(a,h); b=min(b,h); c=min(c,h); d=min(d,h);
  if (n<h and a==0) return plough[n];
  if (n==0) return 0;

  if (!memo[n][a][b][c][d]){
    ll res=0;
    if (a<h) res+=calc(n-1,0,b+1,c+1,d+1); else res+=calc(n-1,b+1,c+1,d+1,h);
    if (b<h) res+=calc(n-1,0,a+1,c+1,d+1); else res+=calc(n-1,a+1,c+1,d+1,h);
    if (c<h) res+=calc(n-1,0,a+1,b+1,d+1); else res+=calc(n-1,a+1,b+1,d+1,h);
    if (d<h) res+=calc(n-1,0,a+1,b+1,c+1); else res+=calc(n-1,a+1,b+1,c+1,h);
    memo[n][a][b][c][d]=(res%lots)+1;
  }
  return memo[n][a][b][c][d]-1;
}

void run(){
  cin>>n>>h;
  plough[0]=1; for (int i=0; i<50; i++) (plough[i+1]=plough[i]*4)%lots;
  cout<<(lots+calc(n,0,0,0,0))%lots<<endl;
}

