const int MAXM = 2e5 + 5;
const int MAXN = 2e5 + 5;

int Next[MAXM];
char T[MAXN];
char P[MAXM];
int id[MAXN];
int n, m, x;
void init() 
{
	Next[0] = -1; 
	int i = 0, j = -1;
	while (i < m)
	{
		if (j == -1 || P[i] == P[j])
		{
			Next[++i] = ++j;
		}
		else
		{
			j = Next[j];
		}
	}
}
void KMP()
{
	int i = 0, j = 0, ans = 0; 
	while (i < n && j < m)
	{
		if (j == -1 || T[i] == P[j])
		{
			i++;
			j++;
		}
		else
		{
			j = Next[j];
		}
		if (j == m)
		{
			id[x++] = i - j;
			//cout << i - j << " ";
			ans++;
			j = Next[j];
		}
	}
}

int main()
{
	scanf("%s", T);
	scanf("%s", P);
	n = strlen(T);
	m = strlen(P);
	init();
	KMP();
	int ans = 0;
	for (int i = 0; i < x; i++)
	{
		ans = max(ans, max(id[i], n - id[i] - m));
	}
