#include <iostream>
#include <cstdio>
#include <algorithm>

int get(int n,int pos,int l,int r)
{
	int left = l - 1, right = n - r;
	int ans = 0;
	if (left == 0 && right != 0)
	{
		ans = r - pos + 1;
	}
	else if (left != 0 && right == 0)
	{
		ans = pos - l + 1;
	}
	else
	{
		if (pos - l <= r - pos)
		{
			ans = pos - l + r - l + 2;
		}
		else
		{
			ans = r - pos + r - l + 2;
		}
	}
	return ans;
}

int main()
{
	int n, pos, l, r;
	scanf("%d%d%d%d", &n, &pos, &l, &r);
	int left = l - 1, right = n - r;
	int ans = 0;
	if (left == 0 && right == 0)
	{
		ans = 0;
	}
	else if (pos >= l && pos <= r)
	{
		ans = get(n, pos, l, r);
	}
	else if (pos < l)
	{
		while (1);
		ans = 1 + get(n, l, l, r);
	}
	else if (pos > r)
	{
		while (1);
		ans = 1 + get(n, r, l, r);
	}
	printf("%d\n", ans);
    return 0;
}

