using namespace std;

int n, pieces;

int bfs(int * state);
bool same_color(int * state);

int main() {
	while (cin >> n) {
		pieces = n / 2;
		int * s = new int[pieces];
		// vector<int> v;
		// v.assign(pieces, int());
		for (int i = 0; i < pieces; i++)
			cin >> s[i];
		int min_step = bfs(s);
		cout << min_step << endl;
	}
	return 0;
}

int bfs(int * state) {
	if (same_color(state))
		return 0;
	priority_queue<pair<int, int*>, vector<pair<int, int*>>, greater<pair<int, int*> >> pq;
	pq.push(make_pair(0, state));
	while (!pq.empty()) {
		pair<int, int*> p = pq.top();
		pq.pop();
		int* s = p.second;
		int steps = p.first;
		for (int i = 0; i < pieces; i++) {
			int * ns = new int[pieces];
			copy(s, s + pieces, ns);
			if (s[i] - 1 >= 1 && find(s, s + pieces, s[i] - 1) == s + pieces) {
				ns[i] = s[i] - 1;
				if (same_color(ns))
					return steps + 1;
				pq.push(make_pair(steps + 1, ns));
			}
			ns = new int[pieces];
			copy(s, s + pieces, ns);
			if (s[i] + 1 <= n && find(s, s + pieces, s[i] + 1) == s + pieces) {
				ns[i] = s[i] + 1;
				if (same_color(ns))
					return steps + 1;
				pq.push(make_pair(steps + 1, ns));
			}
		}
		delete(s);
	}
}

bool same_color(int * state) {
	for (int i = 1; i < pieces; i++) {
		if (state[i] % 2 != state[0] % 2)
			return false;
	}
	return true;
}

