mt19937 rng(time(NULL));

struct hasher {
	int MOD, p = 0;

	hasher(int _MOD) {
		MOD = _MOD;
		while (p < 1000) {
			p = rng() % MOD;
		}
	}

	int n;
	vector<int> deg, h;

	int mul(int a, int b) {
		return (1LL * a * b) % MOD;
	}

	void load(vector<int> v) {
		n = v.size();
		deg.resize(n + 1);
		h.resize(n + 1);
		deg[0] = 1;
		for (int i = 1; i <= n; ++i) {
			deg[i] = mul(deg[i - 1], p);
		}
		for (int i = n - 1; i >= 0; --i) {
			h[i] = (mul(h[i + 1], p) + v[i]) % MOD;
		}
	}

	int get_hash(int l, int r) {
		return (h[l] - mul(h[r + 1], deg[r - l + 1]) + MOD) % MOD;
	}
};

