	}
	last_0 = n;
	for (int i = n - 1; i >= 0; --i) {
		if (s[i] == 0) {
			last_0 = i;
		}
		r0[i] = last_0;
	}
	fill(zero_id, zero_id + n, -1);
	int cur_zero = 0;
	for (int i = 0; i < n; ++i) {
