constexpr int MOD = 1'000'000'007;

int mod_pow(int a, int b, int c) {
    long long x = 1, y = a;
    while (b > 0) {
        if (b % 2 == 1) {
            x = (x * y) % c;
        }
        y = (y * y) % c;
        b /= 2;
    }
    return x % c;
}
int mod_inv(int a) {
    return mod_pow(a, MOD - 2, MOD);
}
int choose(int n, int k, const vector<int> &fac) {
    if (k > n) return 0;
    return 1LL * fac[n] * mod_inv(1LL * fac[k] * fac[n - k] % MOD) % MOD;
}

