void mul(int n, int64 a[1 << MAXN][1 << MAXN], int64 b[1 << MAXN][1 << MAXN]) {
	static int64 res[1 << MAXN][1 << MAXN];
	memset(res, 0, sizeof res);
	forn(i, n) {
		forn(j, n) {
			forn(k, n) {
				res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD;
			}
		}
	}

	forn(i, n) {
		forn(j, n) {
			a[i][j] = res[i][j];
		}
	}
}

void binPow(int64 a[1 << MAXN][1 << MAXN], int n, int64 b) {
	static int64 res[1 << MAXN][1 << MAXN];
	memset(res, 0, sizeof res);
	forn(i, n) {
		res[i][i] = 1;
	}

	while (b > 0) {
		if (b % 2 == 0) {
			mul(n, a, a);
			b /= 2;
		} else {
			mul(n, res, a);
			b--;
		}
	}

	forn(i, n) {
		forn(j, n) {
			a[i][j] = res[i][j];
		}
	}
}

void calcMoves(int n, int64 a[1 << MAXN][1 << MAXN], bool first) {
	forn(deprLeft, 1 << n) {
		forn(realLeft, 1 << n) {
			if ((deprLeft & realLeft) != 0) {
				continue;
			}

			if (first && realLeft + 1 != 1 << n) {
				continue;
			}

			forn(mid, 1 << (n - 1)) {
				int realMid = 1 + (mid << 1) + (1 << n);
				int deprRight = 0;
				forn(i, n) {
					if (bit(realMid, i) && bit(realMid, i + 1) && bit(realLeft, i)) {
						deprRight += 1 << i;
					}
				}

				a[deprLeft][deprRight]++;
			}
		}
	}
}

int64 move(int h, int w, int start, int finish, int pos) {
	if (!used[pos]) {
		used[pos] = true;
		static int64 a[1 << MAXN][1 << MAXN];

		memset(a, 0, sizeof a);
		calcMoves(h, a, pos == 0);
		binPow(a, 1 << h, w);

		forn(i, 1 << h) {
			forn(j, 1 << h) {
				D[pos][i][j] = a[i][j];
			}
		}
	}

	return D[pos][start][finish];
}

int64 get(int v, int mask) {
	if (v == int(a.size())) return (mask == 0) ? 1 : 0;
	if (mask >= (1 << a[v].first)) return 0;

	int64 &ans = d[v][mask];
	if (ans != -1) return ans;

	ans = 0;
	int h = a[v].first, w = a[v].second;
	forn(nmask, 1 << h) {
		ans = (ans + move(h, w, mask, nmask, v) * get(v + 1, nmask)) % MOD;
	}

	return ans;
}


