			q[++r]=rt-i; chkmin(f[cur][i],f[pre][q[l]]+1);
		}
		for (int i=0,l=1,r=0;i<=n&&i<=rt;i++){
			if (l<=r&&q[l]<i-(rt-lt)) l++;
			while (l<=r&&f[pre][i]<=f[pre][q[r]]) r--;
			q[++r]=i; chkmin(f[cur][i],f[pre][q[l]]+2);
		}
	}
	if (f[cur][n]<n)
		printf("Full\n%d\n",f[cur][n]);
	else puts("Hungry");
	return 0;
}

