#include<bits/stdc++.h>

using namespace std;

#define N 200005

int n, l[N], r[N], cnt = 0;

map <int, int> used;

struct seg
{
	int l, r, coll, colr, cnt, tag;
}tr[N << 8];

struct SEG
{
	void build(int rt, int l, int r)
	{
		tr[rt].l = l, tr[rt].r = r;
		if(l == r)
		{
			return;
		}
		int mid = l + r >> 1;
		build(rt << 1, l, mid);
		build(rt << 1 | 1, mid + 1, r);
	}

	void Pushdown(int rt)
	{
		if(tr[rt].tag)
		{
			tr[rt << 1].tag = tr[rt << 1 | 1].tag = 1;
			tr[rt << 1].cnt = tr[rt << 1 | 1].cnt = 1;
			tr[rt << 1].coll = tr[rt << 1].colr = 1;
			tr[rt << 1 | 1].coll = tr[rt << 1 | 1].colr = 1;
		}
	}

	void Pushup(int rt)
	{
		tr[rt].cnt = tr[rt << 1].cnt + tr[rt << 1 | 1].cnt;
		tr[rt].coll = tr[rt << 1].coll, tr[rt].colr = tr[rt << 1 | 1].colr;
		if(tr[rt << 1].colr == 1 && tr[rt << 1 | 1].coll == 1) tr[rt].cnt--;
	}

	void update(int rt, int x, int y)
	{
		Pushdown(rt);
		int l = tr[rt].l, r = tr[rt].r, mid = l + r >> 1;
		// cout << l << ' ' << r << ' ' << x << ' ' << y << endl;
		if(l == x && r == y)
		{
			tr[rt].cnt = 1, tr[rt].tag = 1, tr[rt].coll = 1, tr[rt].colr = 1;
			return;
		}
		if(y <= mid) update(rt << 1, x, y);
		else if(x > mid) update(rt << 1 | 1, x, y);
		else update(rt << 1, x, mid), update(rt << 1 | 1, mid + 1, y);
		Pushup(rt);
	}
}tree;

int main()
{
	// freopen("color.in","r",stdin);
	// freopen("color.out","w",stdout);
	scanf("%d", &n);
	int maxn = 0;
	for(int i = 1; i <= n; i++)
	{
		scanf("%d%d", &l[i], &r[i]);
		r[i]--;
		maxn = max(maxn, r[i] + 1);
		if(used[l[i]] == 0)
		{
			used[l[i]] = ++cnt;
		}
		if(used[r[i]] == 0)
		{
			used[r[i]] = ++cnt;
		}
		if(used[r[i] + 1] == 0)
		{
			used[r[i] + 1] = ++cnt;
		}
	}

	tree.build(1, 1, maxn);
	for(int i = 1; i <= n; i++)
	{
		tree.update(1, l[i], r[i]);
		cout << tr[1].cnt << endl;
	}
	return 0;
}

