const int INF = 0x3f3f3f3f;

const int N = 20;
const int A = 3;
int pos[N * N];
std::vector<int> g[A][N * N];
int dist[A][N * N][N * N];
std::pair<int, int> dp[N * N][A];
int n;

inline int enc(int i, int j) 
{
	return i * n + j;
}

inline void add_edge(int ind, int i, int j, int k, int l) 
{
	g[ind][enc(i, j)].push_back(enc(k, l));
}

void bfs(int v, std::vector<int> *g, int *dist) 
{
	memset(dist, 0x3f, 4 * N * N);
	std::queue<int> q;
	dist[v] = 0;
	q.push(v);
	while (!q.empty()) {
		v = q.front();
		q.pop();
		for (int i = 0; i < (int)g[v].size(); ++i) if (dist[g[v][i]] == INF) {
			dist[g[v][i]] = dist[v] + 1;
			q.push(g[v][i]);
		}
	}
}

void prep() 
{
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < n; ++j) {
			for (int k = 0; k < n; ++k) for (int l = 0; l < n; ++l) if (i != k || j != l) {
				if (abs(k - i) == 2 && abs(l - j) == 1 || abs(k - i) == 1 && abs(l - j) == 2) add_edge(0, i, j, k, l);
				if (abs(k - i) == abs(l - j)) add_edge(1, i, j, k, l);
				if (i == k || l == j) add_edge(2, i, j, k, l);
			}
		}
	}
	for (int i = 0; i < A; ++i) for (int j = 0; j < n * n; ++j) bfs(j, g[i], dist[i][j]);
}

int main() 
{
	scanf("%d", &n);
	prep();
	for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) {
		int v;
		scanf("%d", &v);
		pos[v - 1] = enc(i, j);
	}
	for (int i = 1; i < n * n; ++i) {
		for (int j = 0; j < A; ++j) dp[i][j] = std::make_pair(INF, INF);
		for (int j = 0; j < A; ++j) {
			for (int k = 0; k < A; ++k) {
				dp[i][k] = min(dp[i][k], std::make_pair(dp[i - 1][j].first + dist[j][pos[i - 1]][pos[i]] + (k != j), dp[i - 1][j].second + (k != j)));
			}
		}
	}
	std::pair<int, int> ans = dp[n * n - 1][0];
	for (int i = 1; i < A; ++i) ans = min(ans, dp[n * n - 1][i]);
	assert(ans.first != INF && ans.second != INF && ans.first && ans.second);
	printf("%d %d\n", ans.first, ans.second);
	return 0;
}

