typedef long long ll;

const int N = 9;

int n;
ll a[N];

int ans;

int isp(ll x) {
	for(ll i=2;i*i<=x;i++) {
		if(x%i==0) return 0;
	}
	return 1;
}

int cal(ll x) {
	int cnt=0;
	for(ll i=2;i*i<=x;i++) {
		while(x%i==0) {
			cnt++;
			x/=i;
		}
	}
	return cnt+(x!=1);
}

int calc(ll a,ll x) {
	if(isp(a)) return 0;
	return cal(a/x);
}

int mark[N];

void dfs(int pos,int cost) {
	if(cost>=ans) return ;
	if(pos<0) {
		ans=cost;
		return ;
	}
	int up=1<<pos;
	for(int i=0;i<up;i++) {
		int ok=1;
		ll x=1;
		for(int j=0;j<pos;j++) if(i&(1<<j)) {
			x*=a[j];
			if(mark[j] || a[pos]%x) ok=0;
		}
		if(!ok) continue;
		for(int j=0;j<pos;j++) if(i&(1<<j)) {
			mark[j]=1;
		}
		dfs(pos-1, cost+1+calc(a[pos], x));
		for(int j=0;j<pos;j++) if(i&(1<<j)) {
			mark[j]=0;
		}
	}
}

int main()
{
	mem(mark,0);

	cin>>n;
	for(int i=0;i<n;i++) cin>>a[i];
	sort(a,a+n);
	ans=0x3f3f3f3f;
	dfs(n-1,1);

	ll x=1;
	int ok=1;
	for(int i=0;i<n-1;i++) {
		x*=a[i];
		if(a[n-1]%x) ok=0;
	}
	if(ok) {
		dfs(n-2,1+calc(a[n-1], x));
	}

	cout<<ans<<endl;

    return 0;
}

