using namespace std;
const int N = 1e5 + 10, mod = 998244353, M = 3e3 + 10;
int read()
{
	sl = 0; fh = 1;
	char ch = getchar();
	while(ch < '0' || '9' < ch) {if(ch == '-') fh = -1; ch = getchar();}
	while('0' <= ch && ch <= '9') sl = sl * 10 + ch-'0',ch = getchar();
	return sl * fh;
}
int ksm(int x, int y) {
    int ans = 1;
    while(y) {
        if( y & 1 ) ans = (LL) ans * x % mod;
        x = (LL) x * x % mod;
        y >>= 1;
    }
    return ans;
}
int n, m, a[N], w[N], f[M][M], g[M][M], inv[M << 1], sum[3];
///sum[0] : don't like ; sum[1]: like; sum[2]:all
int main() {
    n = read(); m =read();
    //cout << n << " " << m <<endl;
    rep(i, 1, n) a[i] = read();
    rep(i, 1, n) {
        w[i] = read();
        sum[a[i]] += w[i]; sum[2] += w[i];
    }
    rep(i, 0, 2 * m) inv[i] = ksm(sum[2] + i - m, mod - 2); ///预处理逆元
    dep(i, 0, m) {
        f[i][m - i] = g[i][m - i] = 1;
        dep(j, 0, m - i - 1) {
            f[i][j] = (1LL * (sum[1] + i + 1) * f[i + 1][j] + 1LL * (sum[0] - j) * f[i][j + 1]) % mod * inv[i - j + m] % mod;
			g[i][j] = (1LL * (sum[1] + i) * g[i + 1][j] + 1LL * (sum[0] - j - 1) * g[i][j + 1]) % mod * inv[i - j + m] % mod;
        }
    }
    rep(i, 1, n) printf("%I64d\n", 1LL * w[i] * (a[i] ? f[0][0] : g[0][0]) % mod);
    return 0;
}

