bool good(int A, int B, int x, int y, int v){
	if(v <= 1){
		return false;
	}

	int q = v - v/(x*y);
	int delX = v/x;
	int delY = v/y;

	int delXY = v/(x*y);

	int fa = v - delX;
	int fb = v - delY;

	int delXPlusDelY = delX + delY - delXY;

	int fab = v - delXPlusDelY;
	int fAPlusB = fa + fb - fab;

	/*
	cout << "fa = " << fa << endl;
	cout << "fb = " << fb << endl;
	cout << "fa * fb = " << fab << endl;
	cout << "fa + fb = " << fAPlusB << endl;
	 * */

	int onlyA = fa - fab;
	int onlyB = fb - fab;

	A-=onlyA;
	B-=onlyB;

	if(A < 0){
		A = 0;
	}

	if(B < 0){
		B = 0;
	}

	if(A+B <= fab){
		return true;
	}
	else{
		return false;
	}
}

int bsearch(int A, int B, int x, int y, int left, int right){
	if(right - left < 10){
		for(int i = left; i<=right; i++){
			int g = good(A, B, x, y, i);
			if(g){
				return i;
			}
		}
	}

	int middle = (left+right)/2;
	int g = good(A, B, x, y, middle);
	if(g){
		return bsearch(A, B, x, y, left, middle);
	}
	else{
		return bsearch(A, B, x, y, middle+1, right);
	}
}

