const int MAXK = 2007, MAXT = 101, MAXA = 104, MOD = 1000000007;

ll binpow(ll a, ll n){
	ll res = 1;
	while (n){
		if (n & 1) res *= a;
		a *= a;
		res %= MOD; a %= MOD;
		n >>= 1;
	}
	return res;
}

int main()
{
	ll a, b, k, t, cntS[2][MAXK*MAXT], S = 0, n, cntD[MAXA];
	ll ans = 0;
	scanf("%I64d%I64d%I64d%I64d", &a, &b, &k, &t);
	memset(cntS[0], 0, 8*MAXK*MAXT);
	memset(cntS[1], 0, 8*MAXK*MAXT);
	memset(cntD, 0, 8*MAXA);
	REP(i, k + 1) cntS[0][i] = 1;
	FOR(i, 1, t){
		memset(cntS[(t - 1) & 1], 0, 8*MAXK*MAXT);
		FOR(j, -k*i, k*i + 1){
			cntS[(t - 1) & 1][max(j - k, 0LL)] += cntS[t & 1][abs(j)];
			cntS[(t - 1) & 1][max(j - k, 0LL)] %= MOD;
			cntS[(t - 1) & 1][max(j + k + 1, 0LL)] += MOD - cntS[t & 1][abs(j)];
			cntS[(t - 1) & 1][max(j + k + 1, 0LL)] %= MOD;
		}
		FOR(j, 1, k*(i + 1) + 2){
			cntS[(t - 1) & 1][j] += MOD + cntS[(t - 1) & 1][j - 1];
			cntS[(t - 1) & 1][j] %= MOD;
		}
	}
	n = min((2*k + 1)*t, MAXA - 1LL);
	FOR(i, -k*t, k*t + 1){
		REP(diff, n + 1){
			cntD[diff] += (1LL*cntS[(t - 1) & 1][abs(i)]*cntS[(t - 1) & 1][abs(i + diff)]) % MOD;
			cntD[diff] %= MOD;
		}
	}
	ans = binpow(2*k + 1, 2*t);
	ans += MOD - cntD[0];
	ans %= MOD;
	ans *= binpow(2, MOD - 2);
	ans %= MOD;
	if (a <= b)
		FOR(i, 1, b - a + 1){
			ans += MOD - cntD[i];
			ans %= MOD;
	}
	else{
		for (int i = 0; i > b - a; --i){
			ans += cntD[abs(i)];
			ans %= MOD;
		}
	}
	printf("%I64d", ans);
	//cout << endl; system("pause");
	return 0;
}//don't forget about const

