#define rem(i, m, n) for (int i = m; i > n; --i)
const int MOD = 1000000007;

int solve() {
  int N, K;
  cin >> N >> K;
  string S; cin >> S;
  queue<string> Q;
  set<string> st;
  Q.push(S);
  while(!Q.empty() || (int)st.size() <= K) {
    string t = Q.front(); Q.pop();
    st.insert(t);
    if(t == "") break;
    rep(i, 0, (int)t.size()) {
      int n = (int)t.size() - i - 1;
      string T = t.substr(0, i) + t.substr(i+1, n);
      Q.push(T);
    }
  }
  if(K > (int)st.size()) return -1;
  priority_queue<int> PQ;
  for(auto p : st) PQ.push((int)p.size());
  int ans = 0;
  while(K-- && !PQ.empty()) {
    ans += N - PQ.top();
    PQ.pop();
  }
  return ans;
}

int main() {
  cout << solve() << endl;
  return 0;
}

