pll ext_gcd(ll x, ll y)
{
    if( !x || ! y ) return pll(x, y);
    pll res = ext_gcd(y, x%y);
    return pll(res.second, x/y*res.second + res.first);
}

inline ll divi(ll a, ll b){
    return b? a / b : 1e16;
}

bool solve(string &ans, ll x, ll y)
{
    ans = "";
    pll q = ext_gcd(x, y), p = pll(x, y);
    while( q.first < 0 ) q.first += y, q.second -= x;
    while( q.second < 0 ) q.first -= y, q.second += x;
    if( q.first < 0 || q.second < 0 ) return false;
    swap(q.first, q.second);
    char buf[100];
    bool f = true;
    while(true){
        if( q.first >= p.first && q.second >= p.second ){
            int t = min(divi(q.first, p.first), divi(q.second, p.second));
            q.first -= t*p.first, q.second -= t*p.second;
            if( f ) f = false, t--;
            if( t ) sprintf(buf, "%dA", t);
            reverse(buf, buf+strlen(buf));
            ans += buf;
        }
        else if( p.first >= q.first && p.second >= q.second){
            int t = min(divi(p.first, q.first), divi(p.second, q.second));
            p.first -= t*q.first, p.second -= t*q.second;
