vector<int> mali(int len, int sum){
    vector<int> ret;
    int s = 0;

    ret.insert(ret.begin(), len, 0);

    int brojac = len - 1;
    while(true){
       if(s == sum) break;
       if(ret[brojac] == 9) brojac--;
       ret[brojac]++;
       s++;
    }

    if(ret[0] == 0){
        for(int i = 1; i < len; i++){
              if(ret[i] != 0){
                  swap(ret[0], ret[i]);
                  break;
              }
        }
    }

    if(len == 1) return ret;

    int it = 0;
    for(int i = 0; i < len; i++){
        while(ret[i] > 1){
             ret[i]--;
             ret[len - it - 1]++;
             if(ret[len - it - 1] == 9) it--;
             if(ret[it] == i) break;
        }
    }


    return ret;
}

vector<int> velik(int len, int sum){
      vector<int> ret;
      int s = 0;

      ret.insert(ret.begin(), len, 0);

      int brojac = 0;

      while(true){
           if(s == sum) break;
           if(ret[brojac] == 9) brojac++;
           ret[brojac]++;
           s++;
      }
      return ret;
}

