int ispossible(vector<int>v,int s)
{
    int a=v.size();
    bool dp[s+1][a+1];
    for(int i=0;i<a+1;i++)
        dp[0][i]=true;
    for(int i=1;i<s+1;i++)
        dp[i][0]=false;
    for(int i=1;i<s+1;i++)
    {
        for(int j=1;j<a+1;j++)
        {
            if(v[j-1]<=i)
            {
                dp[i][j]=dp[i][j-1] or dp[i-v[j-1]][j-1];
            }
            else
                dp[i][j]=dp[i][j-1];
        }
    }
    int mi=999999;
    for(int i=0;i<s+1;i++)
    {
        bool p=dp[i][0];
        for(int j=1;j<a+1;j++)
        {
            p=p or dp[i][j];
        }
        if(p==true)
            mi=min(mi,abs(s-2*i));
    }
    return mi;
}

