void dfs(int pos,node now)
{
    if(pos==27)
    {
        m[now]=++cnt;
        return ;
    }
    if(maxn[pos]==0)dfs(pos+1,now);
    for(int i=0;i<maxn[pos];i++)
    {
        now.v[pos]=i;
        dfs(pos+1,now);
    }
}
void calc(int pos,node now)
{
    if(pos==27)
    {
        ans+=A.jz[1][m[now]];
        ans%=mod;
        return ;
    }
    if(maxn[pos]==0)calc(pos+1,now);
    for(int i=0;i<maxn[pos];i++)
    {
        bool flag=false;
        for(int j=0;j<G[pos].size();j++)
        if(i%G[pos][j]==0){
            flag=true;
            break;
        }
        if(flag)
        {
            now.v[pos]=i;
            calc(pos+1,now);
        }
    }
}
inline edge qkpow (edge x, LL y){
    edge ans;
    ans.r = ans.c = x.r;
    for (register int i = 1; i <= ans.r; i ++)
        for (register int j = 1; j <= ans.c; j ++)
            if (i != j)
                ans.jz[i][j] = 0;
            else
                ans.jz[i][j] = 1;
    while (y){
        if (y & 1)
            ans = ans * x;
        x = x * x;
        y >>= 1;
    }
    return ans;
}
