struct mv {
    int bits = 0;
    int v1, v2;
    void swap(int pos){ //with pos + 1
        int d1 = (bits >> pos) & 1;
        int d2 = (bits >> (pos + 1)) & 1;

        bits &= ~(3 << pos);

        bits |= d2 << pos;
        bits |= d1 << (pos + 1);

        if(v1 == pos || v1 == pos + 1){
            v1 = (pos) + (pos + 1) - v1;
        }

        if(v2 == pos || v2 == pos + 1){
            v2 = (pos) + (pos + 1) - v2;
        }
    }
};

const int MAXN = 19;

int dp[1 << MAXN][MAXN][MAXN];

int solve(mv src){
    //cout << endl;
    //cout << bitset<8>(src.bits) << " " << src.v1 << " " << src.v2 << endl;
    memset(dp, 0x3f, sizeof dp);
    dp[src.bits][src.v1][src.v2] = 0;
    queue<mv> q;
    q.push(src);

    while(!q.empty()){
        mv fr = q.front();
        //cout << bitset<8>(fr.bits) << " " << fr.v1 << " " << fr.v2 << endl;
        int cost = dp[fr.bits][fr.v1][fr.v2];
        q.pop();

        for(int a = 0; a < 19; a++){
            fr.swap(a);

            if(fr.bits & (1 << (N - 1))){
                //cant have front 0
            } else {
                if(cost + 1 < dp[fr.bits][fr.v1][fr.v2]){
                    dp[fr.bits][fr.v1][fr.v2] = cost + 1;
                    q.push(fr);
                }
            }

            fr.swap(a);
        }
    }
}

