long long bigmod(long long b,long long p,long long m) {
  if (m == 1LL) return 0LL;
  if (p == 0LL) return 1LL;
  if (p%2LL == 0) {
    long long n = bigmod(b,p/2LL,m);
    return (n*n) % m;
  }
  return ((b % m) * bigmod(b,p-1LL,m)) % m;
}

