#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef pair<int, int> pi;
typedef pair<ll, ll> pl;
const int N = 254;
const ll MOD = 1000000007LL;

ll dp[N][N];
ll C[N][N];
ll pow[N][N];

ll bigpow(ll a, ll b) {
  if (pow[a][b] != -1) return pow[a][b];
  if (b == 0) return 1;
  ll half = bigpow(a, b >> 1);
  ll res = half * half % MOD;
  if (b % 2 == 1) res = res * a % MOD;
  return pow[a][b] = res;
}

ll calc(ll r, ll c, ll k, ll n) {
  if (dp[r][c] != -1) return dp[r][c];
  if (r == 0) return dp[r][c] = 1;
  if (c == 0) {
    ll tmp = (bigpow(k, n) - bigpow(k-1, n) + MOD) % MOD;
    return dp[r][c] = bigpow(tmp, r);
  }
  if (r == 1) {
    return dp[r][c] = bigpow(k, n - c);
  }
  ll res = (bigpow(k, n - c) - bigpow(k - 1, n - c) + MOD) % MOD;
  res = res * bigpow(k - 1, c) % MOD;
  res = res * calc(r - 1, c, k, n) % MOD;
  for (ll c0 = 1; c0 <= c; c0++) {
    ll tmp = bigpow(k, n - c) * C[c][c0] % MOD * bigpow(k - 1, c - c0) % MOD * calc(r - 1, c - c0, k, n) % MOD;
    res = (res + tmp) % MOD;
  }
  return dp[r][c] = res;
}

int main(){
  ios_base::sync_with_stdio(0);  cin.tie(NULL);  cout.tie(NULL);
  for (int i = 0; i < N; i++) {
    C[i][0] = 1;
    for (int j = 1; j <= i; j++) {
      C[i][j] = (C[i-1][j] + C[i-1][j-1]) % MOD;
    }
  }
  ll n, k;
  while (cin >> n >> k) {
    memset(dp, -1, sizeof(dp));
    memset(pow, -1, sizeof(pow));
    cout << calc(n, n, k, n) << endl;
  }
  return 0;
}

