int tram(int p, int x2, int x1, int t1, int d, int s) {
    if(d == 1)  {
        if(p<=x1 && x1<x2)
            return t1*(x2-p);
        else if(p>=x1 && x1<x2)
            return t1*((s-p)+s+x2);
        else if(p>=x1 && x1>x2 || p<=x1 && x2<x1)
            return t1*((s-p)+(s-x2));
    }
    if(d == -1)  {
        if(p>=x1 && x1>x2)
            return t1*(p-x2);
        else if(p<=x1 && x1>x2)
            return t1*((p)+s+(s-x2));
        else if(p<=x1 && x1>x2 || p>x1 && x2>x1)
            return t1*((p)+(x2));
    }

}

