struct pt{
    long double cor[5];
    pt(){}
    pt(long double c1, long double c2, long double c3, long double c4, long double c5){
        cor[0] = c1;
        cor[1] = c2;
        cor[2] = c3;
        cor[3] = c4;
        cor[4] = c5;
    }
    pt(pt a, pt b){
        cor[0] = b.cor[0] - a.cor[0];
        cor[1] = b.cor[1] - a.cor[1];
        cor[2] = b.cor[2] - a.cor[2];
        cor[3] = b.cor[3] - a.cor[3];
        cor[4] = b.cor[4] - a.cor[4];
    }
};

long double dot_prod(pt a, pt b){
    long double res = 0;
    for (int i = 0; i < 5; i++)
        res += a.cor[i] * b.cor[i];
    return res;
}

long double len(pt a){
    return sqrt(dot_prod(a, a));
}

long double angle(pt a, pt o, pt b){
    pt x = pt(o, a), y = pt(o, b);
    long double res = (acos(dot_prod(x, y) / (len(x) * len(y))));
    return res;
}

