        void updrmq(int le, int ri, int indx, int ptr,ll ele){
            if(le==ri){rmq[ptr]=ele; return;}
            if(indx<=(le+ri)/2) updrmq(le,(le+ri)/2,indx,2*ptr+1,ele);
            else updrmq((le+ri)/2+1,ri,indx,2*ptr+2,ele);
            rmq[ptr]=min(rmq[2*ptr+1],rmq[2*ptr+2]);
        }
        ll queryrmq(int le, int ri, int ptr, int lw, int rw){
            if(lw>ri || rw<le) return LLONG_MAX;
            else if(lw<=le && ri<=rw) return rmq[ptr];
            return min(queryrmq(le,(le+ri)/2,ptr*2+1,lw,rw),queryrmq((le+ri)/2+1,ri,ptr*2+2,lw,rw));
        }
        void updallrmq(ll x[],int lens){
