const int MAXN = 7000;


bool a_in_b(int a, int b) {
	return ((a & b) == a);
}

int n;
int gr[MAXN][MAXN];
vector <int> deleted, used, order;

void top_sort(int u) {
	used[u] = 1;
	for (int v = 0; v < n; ++v) {
		if (gr[u][v] && !used[v] && !deleted[v]) {
			top_sort(v);
		}
	}
	order.push_back(u);
}

int get_sum(int u, vector <int>& b) {
	int sum = b[u];
	used[u] = 1;
	for (int v = 0; v < n; ++v) {
		if (gr[u][v] && !used[v] && !deleted[v]) {
			sum += get_sum(v, b);
		}
	}
	return sum;
}

main() {
	set_program();
	cin >> n;
	vector <int> a(n), b(n);
	for (int& i : a) {
		cin >> i;
	}
	for (int& i : b) {
		cin >> i;
	}
	vector <int> cnt_childs(n, 0);
	for (int i = 0; i < n; ++i) {
		for (int j = i + 1; j < n; ++j) {
			if (a_in_b(a[i], a[j])) {
				gr[i][j] = 1;
				++cnt_childs[i];
			}
			if (a_in_b(a[j], a[i])) {
				gr[j][i] = 1;
				++cnt_childs[j];
			}
		}
	}
	deque <int> q;
	for (int i = 0; i < n; ++i) {
		if (!cnt_childs[i]) {
			q.push_back(i);
		}
	}
	deleted.assign(n, 0);
	for (; q.size(); ) {
		int u = q.front();
		q.pop_front();
		deleted[u] = 1;
		for (int v = 0; v < n; ++v) {
			if (gr[v][u]) {
				if (!--cnt_childs[v]) {
					q.push_back(v);
				}
			}
		}
	}
	used.assign(n, 0);
	for (int u = 0; u < n; ++u) {
		if (!deleted[u] && !used[u]) {
			top_sort(u);
		}
	}
	reverse(all(order));
	used.assign(n, 0);
	int ans = 0;
	for (int u : order) {
		if (!used[u]) {
			ans = max(ans, get_sum(u, b));
		}
	}
	cout << ans << "\n";
	return 0;
}

