#include<bits/stdc++.h>
using namespace std;
const int N=10001;
const int mod=1e9+7;
long long int C[N][N];
void build()
{
	int i,j;
	for(i=0;i<N;++i)		C[i][0]=1;
	for(i=0;i<N;++i)		C[i][i]=1;
	for(j=1;j<N;++j)
		for(i=j+1;i<N;++i)
			C[i][j]=(C[i-1][j-1]+C[i-1][j])%mod;
}
int num(int r,int b,int k)
{
	if(b==0) 			return 1;
	int ans=0,u;
	for(u=1;u<=r+1&&(k==0||u<=(b-1)/k);++u)
	{
		ans+=1ll*C[r+1][u]*C[b-k*u-1][u-1]%mod;
		ans%=mod;
	}
	return ans;
}
long long int binpow(long long int x,long long int pow)
{
	if(pow==0)			return 1LL;
	if(pow==1)			return x;
	if(pow%2==0)		return binpow((x*x)%mod,pow/2)%mod;
	if(pow%2==1)
	{
		long long int k=x;
		return k%mod*binpow((x*x)%mod,pow/2)%mod;
	}
}
int main ()
{
	build();
	int f,w,h;
	scanf("%d %d %d",&f,&w,&h);
	int sn=num(f,w,h);
	int sd=C[f+w][w];
	printf("%I64d",1LL*sn*binpow(sd,mod-2)%mod);
	return 0;
}

