using namespace std;

long double pi = atan((long double)1)*4;

class Point
{
public:
	long double x;
	long double y;
	Point(long double xi, long double yi)
	{	
		x=xi;
		y=yi;
	};
	Point()
	{
	};
};

class Segment
{
public:
	Point p1;
	Point p2;
	Segment(Point p1i, Point p2i)
	{
		p1.x=p1i.x;
		p1.y=p1i.y;
		p2.x=p2i.x;
		p2.y=p2i.y;
	};
	long double length() 
	{ 
		return sqrt( (p1.x-p2.x)*(p1.x-p2.x) + (p1.y-p2.y)*(p1.y-p2.y) ); 
	}
};

void pos_circle(Point p, long double v, long double t, Point* final_p)
{
	long double R = sqrt((long double)(p.x*p.x+p.y*p.y));
	long double time_360 = 2*pi*R/v;
	long double ini_angle = atan2((long double)p.y,(long double)p.x) *180 /pi;
	long double final_angle = t*2*pi/time_360;

	final_p->x=cos(final_angle)*R;
	final_p->y=sin(final_angle)*R;
}

long double distance_to_segment (Point p, Segment seg)
{
	Segment a(seg.p1, p);
	Segment b(seg.p2, p);
	Segment* max;
	Segment* min;
	if(a.length() > b.length())
	{
		max = &a;
		min = &b;
	}
	else
	{
		max = &b;
		min = &a;
	}

	if(seg.length()==0 || min->length()==0)
		return min->length();

	if ((min->length() * min->length() + seg.length() * seg.length() - max->length() * max->length()) / (2*min->length()*seg.length()) < 0)
		return min->length();

	long double s = (a.length() + b.length() + seg.length())/2;
	return 2 * sqrt( s * ( s - a.length() ) * (s - b.length() ) * (s - seg.length() ) ) / seg.length();

}

void tangent_points_to_circle(Point center, long double R, Point p, Point* p1, Point* p2)
{
	Segment s(center, p);
	if( s.length() <= R)
		return;
	else
	{
		long double ini_angle = atan2(p.y - center.y , p.x - center.x);
		long double final_angle1 = ini_angle + acos(R/s.length()) ;
		long double final_angle2 = ini_angle - acos(R/s.length()) ;
		p1->x=cos(final_angle1)*R + center.x;
		p1->y=sin(final_angle1)*R + center.y;
		p2->x=cos(final_angle2)*R + center.x;
		p2->y=sin(final_angle2)*R + center.y;
	}
}


int main()
{
