	while(true)
	{
		pos_circle(ini_perse,vp,time,&perse);
		Segment s(perse, ship);
		long double distance = distance_to_segment(center, s);
		if(distance >= R)
			time_ship =  s.length()/V;
		else
		{
			Point ship_tang1, ship_tang2, perse_tang1, perse_tang2;
			tangent_points_to_circle(center, R, ship, &ship_tang1, &ship_tang2);
			tangent_points_to_circle(center, R, perse, &perse_tang1, &perse_tang2);
			Segment route1_ship(ship, ship_tang1);
			Segment route2_ship(ship, ship_tang2);
			Segment route1_perse(perse_tang2, perse);
			Segment route2_perse(perse_tang1, perse);

			long double distance1 = route1_ship.length() + abs(atan2(ship_tang1.y, ship_tang1.x) - atan2(perse_tang2.y, perse_tang2.x))*2*R + route1_perse.length();
			long double distance2 = route2_ship.length() + abs(atan2(ship_tang2.y, ship_tang2.x) - atan2(perse_tang1.y, perse_tang1.x))*2*R + route2_perse.length();
			time_ship = min(distance1, distance2)/V; 
		}
		if( time_ship < time )
			break;
		else
			time *= 2;
	} 

	range_max = time;
	range_min = 0 ; 


	while(true)
	{
		time = (range_max + range_min ) / 2;
		//time = 9.584544103;
		pos_circle(ini_perse,vp,time,&perse);
		Segment s(perse, ship);
		long double distance = distance_to_segment(center, s);
		if(distance >= R)
			time_ship =  s.length()/V;
		else
		{
			Point ship_tang1, ship_tang2, perse_tang1, perse_tang2;
			tangent_points_to_circle(center, R, ship, &ship_tang1, &ship_tang2);
			tangent_points_to_circle(center, R, perse, &perse_tang1, &perse_tang2);
			Segment route1_ship(ship, ship_tang1);
			Segment route2_ship(ship, ship_tang2);
			Segment route1_perse(perse_tang2, perse);
			Segment route2_perse(perse_tang1, perse);

			long double distance1 = route1_ship.length() + abs(atan2(ship_tang1.y, ship_tang1.x) - atan2(perse_tang2.y, perse_tang2.x))*R + route1_perse.length();
			long double distance2 = route2_ship.length() + abs(atan2(ship_tang2.y, ship_tang2.x) - atan2(perse_tang1.y, perse_tang1.x))*R + route2_perse.length();
			time_ship = min(distance1,distance2)/V; 
		}


		if(abs(time-time_ship)<0.0000000001)
			break;

		if(time_ship < time)
			range_max = time;
		else
			range_min = time;
	}
	cout << time;
	return 0;
}

