using namespace std;
#define START clock_t _clock = clock();
#define END cerr << endl << "time: " << (clock() - _clock) / LD(CLOCKS_PER_SEC) << endl;
typedef long double LD;
typedef long long LL;

const LD pi = acos(-1.0);
const LD eps = 1e-9;
LD xp, yp, vp, xs, ys, v, r;

LD sqr(LD x)
{
    return x * x;
}

LD mmax(LD x, LD y)
{
    return x > y ? x : y;
}

LD mmin(LD x, LD y)
{
    return x < y ? x : y;
}

LD distance(LD x1, LD y1, LD x2, LD y2)
{
    return sqrt( LD(sqr(x1 - x2) + sqr(y1 - y2)) );
}

LD cathetus(LD hyp, LD cath)
{
    return sqrt(sqr(hyp) - sqr(cath));
}

// в начале планета имеет угол atan(yp / xp)
// возвращает момент времени >= tm, когда планет будет иметь угол angle
LD ptime(LD angle, LD tm)
{
    // радиус обращения планеты
    LD R = distance(xp, yp, 0, 0);
    // начальный угол планеты
    LD pangle = atan2(yp, xp);
    if (pangle < 0)
        pangle += 2 * pi;
    // время достижения планетой угла angle
    LD res = ( angle + (angle < pangle ? 2 * pi : 0) - pangle) / vp * R;
    // время обращения планеты
    LD ptm = 2 * pi * R / vp;

    res += floor((res - ptm) / ptm) * ptm;
    while (res < tm)
        res += ptm;

    return res;
}

LD time(LD angle)
{
    // радиус обращения планеты
    LD R = distance(xp, yp, 0, 0);
    // место встречи планеты и корабля (D)
    LD xd = R * cos(angle);
    LD yd = R * sin(angle);

/*------------- придётся ли огибать звезду -----------------------------------*/
    bool intersect = false;

    // коэффициенты уравнения прямой
    LD A = ys - yd;
    LD B = xd - xs;
    LD C = xs * yd - xd * ys;
    // квадрат расстояния от центра окружности (0,0) до прямой SD
    LD sdist = sqr(C) / (sqr(A) + sqr(B));

    // если прямая и окружность пересекаются
    if (sdist <= sqr(r))
    {
        // коэффициенты квадратного уравнения персечения
        LD a = 1 + sqr(A / B);
        LD b = 2 * A * C / sqr(B);
        LD c = sqr(C / B) - sqr(r);
        LD discr = sqr(b) - 4 * a * c;
        // точки пересечения:
        LD x1 = (-b - sqrt(discr)) / (2 * a);
        LD x2 = (-b + sqrt(discr)) / (2 * a);
        // если отрезок и окружность пересекаются, то придётся огибать звезду
        if (min(xs, xd) <= x1 && x1 <= max(xs, xd) || min(xs, xd) <= x2 && x2 <= max(xs, xd))
            intersect = true;
    }
/*-----------------------------------------------------------------------------*/

    LD dist; // длина маршрута из точки S в точку D
    if (intersect)
    {
        LD a = distance(xs, ys, 0, 0);
        LD b = cathetus(a, r);  // расстояние до дуги

        LD c = distance(xd, yd, 0, 0);
        LD d = cathetus(c, r);  // расстояние после дуги

        LD e = distance(xs, ys, xd, yd);
        LD alpha = acos( (sqr(c) + sqr(a) - sqr(e)) / (2 * c * a) );
        LD alpha1 = atan2(d, r);
        LD alpha2 = atan2(b, r);

        LD phi = alpha - alpha1 - alpha2;
        LD arc = phi * r; // длина дуги


        // всё расстояние
        dist = b + arc + d;
    }
    else
        dist = distance(xs, ys, xd, yd);

    // время прибытия корабля в точку на орбите с углом angle:
    LD tm = dist / v;

    // время следующего прибытия планеты в эту же точку
    return ptime(angle, tm);
}

LD getminangle(LD left, LD right, LD step)
{
    LD  minangle = left,
        mintime = time(minangle);
    for (LD angle = left + step; angle < right; angle += step)
    {
        LD tm = time(angle);
        if (tm < mintime)
            mintime = tm,
            minangle = angle;
    }
    return minangle;
}

main()
{
    cin >> xp >> yp >> vp >> xs >> ys >> v >> r;

    const LD step = 0.00005;
    const LD u = 0.0008;
    const LD left = 0.0;
    const LD right = 2 * pi;

    // находим угол при котором значение функции time минимально на всём интервале углов
    LD a = getminangle(left, right, step);
    // находим минимальное время в окрестности угла a
    LD res = time(getminangle(mmax(left, a - u), mmin(right, a + u), eps));


    cout.setf(ios::fixed); cout.precision(8);

    cout << res << endl;
}
/*

Идея решения:

Возьмём произвольную точку на окружности (D), по которой обращается планета.
Определим расстояние от места старта корабля (S до этой точки.
Если на пути встетится окружность звезды, то придётся делать огибание,
в таком случае расстояние увеличится.

Теперь определим время (tm) прохождени корабля от S до D.

Результатом f(alpha) будет минимальное время, большее либо равное tm, при котором планета будет в точке D.

Ответом будет min(f(alpha)), которое можно найти тернарным поиском. alpha задаёт однозначное положение точки D.

*/

