typedef long long ll;

ll cuadrados(int s)
{
	if(s <= 0) return 1;
	return cuadrados(s-1) + 2*(s+1) + 2*(s-1);
}

ll triangulo(int l)
{
	if(l < 0) return 0;
	return max((ll)0 , (ll)l*l);
}
ll triangulo(int n, int i, int d)
{
	if(n < 0) return 0;
	i++; d++;
	d = min(d,n);
	i = min(i,n);
	return max((ll)0 , -(ll)n + (ll)n*(ll)d + (ll)n *(ll)i + ((ll)d + (ll)i - (ll)d*(ll)d - (ll)i*(ll)i)/(ll)2);
}


ll cuadrados(int &s, int &x, int &y, int &n)
{
	return cuadrados(s) - triangulo(s-abs(n-y)) - triangulo(s-y) - triangulo(s-x, y, n-y) - triangulo(s-abs(n-x),y,n-1);
}

