ll MOD = 1e9 + 7;

int n, x;
char s[555];
ll pf2[555];
ll dp[555][555][555];

// number of occurences of s[fr..to] within subsequences of F[k]
ll solve(int fr, int to, int k) {
	if(k==0) return fr == to && s[fr] == '0';
	if(k==1) return fr == to && s[fr] == '1';
	ll& r = dp[fr][to][k];
	if(r>=0) return r;
	r = 0;
	r = (r + ((fr==0 ? pf2[k-1] : 1ll) * solve(fr, to, k-2) % MOD)) % MOD;
	r = (r + (solve(fr, to, k-1) * (to == n-1 ? pf2[k-2] : 1ll) % MOD)) % MOD;
	for(int m=fr;m<to;m++) {
		r = (r + ( solve(fr, m, k-1) * solve(m+1, to, k-2) % MOD)) % MOD;
	}
	return r;
}

