using namespace std;

const int N=101;
int n,k;
int a[N];
int zl[N];
bool have[N];
int tot=0,ans=0;
int p[N],f;

void pd()  //虽然我们记录了从今天之后出现的书的情况 
{  //但是如果有书在之后都不会出现，我们选择扔ta肯定更优 
	int i;
	for (int i=1;i<=zl[0];i++)
	    if (p[zl[i]]==0) 
	    {
	    	f=zl[i];
	    	return;
		}
	return;
}

int main()
{
	memset(have,0,sizeof(have));
	scanf("%d%d",&n,&k);
	for (int i=1;i<=n;i++)
	{
		scanf("%d",&a[i]);
		p[a[i]]++;
		if (p[a[i]]==1) zl[0]++,zl[zl[0]]=a[i];  //不同的书的种类 
	}
	for (int i=1;i<=n;i++)  //从1到n扫一遍 
	{
		if (have[a[i]]==0&&tot<k)  //没有这本书，而且图书馆没满 
		{
			ans++; //直接买 
			tot++;
			have[a[i]]=1;
		}
		else if (have[a[i]])
		{
			continue;
		}
		else  //图书馆满了 
		{
			have[a[i]]=1;  //先把当前需要的书买进来 
			ans++;
			//扔掉哪本书呢???就是在最近用不到的书
			int r=i+1; 
			memset(p,0,sizeof(p));  //判断书在之后的几天会不会用到 
			while (p[0]<k&&r<=n)  //书店最多放k本书 
				if (p[a[r]]==0&&have[a[r]]) 
				{
					p[a[r]]=1;
					p[0]++;
					f=a[r];  //记录在今天之后一定范围内最后出现的书 
					r++;
				}
			pd(); 
			have[f]=0;
		}
	}
	printf("%d",ans);
	return 0;
}

