#include <iostream>

using namespace std;

const int limite=152;

typedef long long int lint;

lint modulo=1000000007;

lint cuantos[limite][limite][limite];
lint cuantosle[limite][limite][limite];
lint cuantosri[limite][limite][limite];
lint cuantosleri[limite][limite][limite];

lint suma[limite][limite][limite];
lint sumale[limite][limite][limite];
lint sumari[limite][limite][limite];
lint sumaleri[limite][limite][limite];

lint n,m;

lint total=0;

void computasuma(int i)
{
  lint (&s)[limite][limite]=suma[i];
  lint (&sl)[limite][limite]=sumale[i];
  lint (&sr)[limite][limite]=sumari[i];
  lint (&slr)[limite][limite]=sumaleri[i];
  for (int j=1;j<=m;j++) {
    for (int k=1;k<=m;k++) {
      s[j][k]=(cuantos[j][k]+s[j-1][k]+s[j][k-1]-s[j-1][k-1])%modulo;
      sl[j][k]=(cuantosle[j][k]+sl[j-1][k]+sl[j][k-1]-sl[j-1][k-1])%modulo;
      sr[j][k]=(cuantosri[j][k]+sr[j-1][k]+sr[j][k-1]-sr[j-1][k-1])%modulo;
      slr[j][k]=(cuantosleri[j][k]+slr[j-1][k]+slr[j][k-1]-slr[j-1][k-1])%modulo;
    }
  }
  total=(total+(s[m][m]+sl[m][m]+sr[m][m]+slr[m][m])*(n-i))%modulo;
}


int main()
{
  cin>>n>>m;
  for (int j=1;j<=m;j++)
    for (int k=j;k<=m;k++)
      cuantos[0][j][k]=1;
  computasuma(0);
  for (int i=1;i<n;i++) {
    lint (&s)[limite][limite]=suma[i-1];
    lint (&sl)[limite][limite]=sumale[i-1];
    lint (&sr)[limite][limite]=sumari[i-1];
    lint (&slr)[limite][limite]=sumaleri[i-1];
    for (int j=1;j<=m;j++) {
      for (int k=j;k<=m;k++) {
	cuantos[i][j][k]=(s[k][k]-s[j-1][k])%modulo;
	cuantosle[i][j][k]=(sl[j][k]-sl[j-1][k-1]+
			    s[j-1][k]-s[j-1][k-1])%modulo;
	cuantosri[i][j][k]=(sr[k][m]-sr[k-1][k-1]-sr[j-1][m]+sr[j-1][k-1]+
			    s[k][m]-s[k][k]-s[j-1][m]+s[j-1][k])%modulo;
	cuantosleri[i][j][k]=(slr[j][m]-slr[j][k-1]+
			      sl[j][m]-sl[j][k]+
			      sr[j-1][m]-sr[j-1][k-1]+
			      s[j-1][m]-s[j-1][k])%modulo;
      }
    }
    computasuma(i);
  }
  total=(total+modulo)%modulo;
  cout<<total<<endl;
}

