ll dp(int l, int r){
    if(r < l) return 0;
    if(l<10 && r>=10) return (10-l) + dp(10, r);
    if(l<10 && r<10) return r-l+1;
    ll t1, t2, ans;
    if(l == r){
        t1 = l%10;
        t2 = l;
        while(t2>=10){
            t2 = (t2-(t2%10))/10;
        }
        if(t1 == t2)
        return 1;
        else return 0;
    }
    t1 = l%10;
    t2 = l;
    while(t2>=10){
    t2 = (t2-(t2%10))/10; }
    if(t1 == t2) return 1+dp(l+1, r);
    else return dp(l+1, r);

}

