string s, t;
vector< pair<char, int> > a, b;
vector< pair<int, int> > bleach;
vector< pair<char, int> > ta, tb;
bool flag = false;

void add(vector< pair<char, int> > &tren, pair<char, int> s) {
    if (!tren.empty() && tren.back().first == s.first) tren.back().second += s.second;
    else tren.push_back(s);
}

inline void addchar(vector< pair<char, int> > &tren, char s) {
    add(tren, make_pair(s, 1));
}

int pop(vector< pair<char, int> > &tren, int kol) {
    int sol = 0;
    for (int i = 0; i < kol; i++) {
        sol += tren.back().second;
        tren.pop_back();
    }
    return sol;
}

void query(int acx, int acy) {
    //printf("query: %d %d\n", acx, acy);
    if (flag) swap(acx, acy);
    ta.clear(); tb.clear();
    for (int i = 0; i < acx; i++) ta.push_back(a[i]);
    for (int i = 0; i < acy; i++) tb.push_back(b[i]);
    int kolx = pop(a, acx);
    int koly = pop(b, acy);

    for (int i = 0; i < acx; i++) add(b, ta[ta.size() - 1 - i]);
    for (int i = 0; i < acy; i++) add(a, tb[tb.size() - 1 - i]);
    bleach.push_back(make_pair(kolx, koly));
}

