    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> s >> t;

    reverse(s.begin(), s.end());
    reverse(t.begin(), t.end());
    for (int i = 0; i < s.size(); i++) addchar(a, s[i]);
    for (int i = 0; i < t.size(); i++) addchar(b, t[i]);

    while (a.size() != 1 || b.size() != 1) {
        int la = a.size();
        int lb = b.size();

        if (la < lb) {
            swap(la, lb);
            flag = true;
        }
        const char kuraca = a.back().first;
        const char kuracb = b.back().first;

        //printf("%d %d -> %c %c\n", la, lb, kuraca, kuracb);
        if (kuraca != kuracb) {
            if (lb <= 2) {
                if (la <= 3) query(1, 1);
                else query(3, 1);
            } else query(1, 1);
        } else {
            if (lb == 1) {
                if (la <= 3) query(1, 0);
                else query(3, 0);
            } else if (lb == 2) {
                if (la == 2) query(1, 0);
                else query(2, 1);
            } else query(3, 2);
        }
        flag = false;
    }

    printf("%d\n", bleach.size());
    for (int i = 0; i < bleach.size(); i++)
        printf("%d %d\n", bleach[i].first, bleach[i].second);
    return 0;
