    char l=c;
    for(int i=sz(a)-1;i>=0;i--)
    {
        if(a[i]!=l)
        {
            l=a[i];
            q.pb(i+1);
        }
    }
    return q;
}

VPI solv(string a, string b)
{
    VI p =zmiany(a, 'a');
    VI q =zmiany(b, 'b');
    while(sz(p) < sz(q))
        p.pb(0);
    while(sz(q) < sz(p))
        q.pb(0);
    VPI res;
    for(int i=0;i<q.size();i++)
    {
        res.pb(pi(p[i], q[i]));
        swap(p, q);
    }
    return res;
}

