    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (i == 0 && j == 0)
                h[i][j] = g;
            else {
                g = (g * x + y) % z;
                h[i][j] = g;
            }
        }
    }
