i64 memo[50][50];

i64 f(int h,int n)
{
    if(h > n)
        return 0;
    if(h == 0 && n == 0)
        return 1;

    i64& ret = memo[h][n];
    if(ret != -1)
        return ret;
    ret = 0;
    FORE(i,1,n)
    {
        int ln = i-1, rn = n-i;
        FOR(hl,0,h-1)
            ret += f(hl,ln)*f(h-1,rn) + f(h-1,ln)*f(hl,rn);
        ret+= f(h-1,ln)*f(h-1,rn);
    }
    return ret;
}

