    vector<int> ans;
    int start = n/2;
    int sum_of_digits = fsum_of_digits(start) - 1;
    for(int i = start; i<=n; i++) {
        sum_of_digits++;
        if(i % 1000000000 == 0) {
            sum_of_digits -= 81;
        } else if(i % 100000000 == 0) {
            sum_of_digits -= 72;
        } else if(i % 10000000 == 0) {
            sum_of_digits -= 63;
        } else if(i % 1000000 == 0) {
            sum_of_digits -= 54;
        } else if(i % 100000 == 0) {
            sum_of_digits -= 45;
        } else if(i % 10000 == 0) {
            sum_of_digits -= 36;
        } else if(i % 1000 == 0) {
