bool tr(ull k) {
	ull s1 = 0, s2 = 0, t = n, l = (n - 1) / 2 + 1;
	while (t) {
		if (t < k) {
			s1 += t;
			t = 0;
		}
		else {
			t -= k;
			s1 += k;
		}
		s2 += t / 10;
		t -= t / 10;
		if (s1 >= l)
			return true;
		if (s2 > l)
			return false;
	}
}

