void solve() {

	for (int i = 0; i < MAXM; i++) {
		for (int j = 0; j < MAXM; j++) {
			dist[i][j] = MP(INF, INF);
		}
	}
	for (int i = 0; i < MAXM; i++) {
		dist[i][i] = MP(0, 0);
	}

	for (int x = 0; x < n; x++) {
		for (int y = 0; y < n; y++) {
			// ruch skoczkiem - 0
			for (int h = 0; h < 8; h++) {
				int wx = x + hx[h];
				int wy = y + hy[h];
				if (isInside(wx, wy)) {
					dist[getIndex(x, y, 0)][getIndex(wx, wy, 0)] = MP(1, 0);
				}
			}
			// ruch wieza - 1 
			for (int w = 0; w < n; w++) {
				if (w != x) { // pionowy
					dist[getIndex(x, y, 1)][getIndex(w, y, 1)] = MP(1, 0);
				}
				if (w != y) { // poziomy
					dist[getIndex(x, y, 1)][getIndex(x, w, 1)] = MP(1, 0);
				}
			}
			// ruch goncem - 2
			for (int g = -n + 1; g < n; g++) {
				if (g == 0) {
