				if (isInside(x + g, y + g)) {
					dist[getIndex(x, y, 2)][getIndex(x + g, y + g, 2)] = MP(1, 0);
				}
				if (isInside(x + g, y - g)) {
					dist[getIndex(x, y, 2)][getIndex(x + g, y - g, 2)] = MP(1, 0);
				}
			}
			// zmiana bierki
			for (int b1 = 0; b1 < 3; b1++) {
				for (int b2 = 0; b2 < 3; b2++) {
					if (b1 != b2) {
						dist[getIndex(x, y, b1)][getIndex(x, y, b2)] = MP(1, 1);
					}
				}
			}
		}
	}

	for (int k = 0; k < MAXM; k++) {
		for (int i = 0; i < MAXM; i++) {
			for (int j = 0; j < MAXM; j++) {
				dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
			}
		}
	}

	for (int i = 0; i < MAXN * MAXN; i++) {
		for (int b = 0; b < 3; b++) {
			dp[i][b] = MP(INF, INF);
		}
	}

	dp[0][0] = dp[0][1] = dp[0][2] = MP(0, 0);
	for (int i = 0; i < n * n - 1; i++) {
		for (int b1 = 0; b1 < 3; b1++) {
			for (int b2 = 0; b2 < 3; b2++) {
				dp[i + 1][b2] = min(dp[i + 1][b2], dp[i][b1]
					+ dist[getIndex(pos[i].F, pos[i].S, b1)][getIndex(pos[i + 1].F, pos[i + 1].S, b2)]);
				/* if (dp[i][b1] + dist[getIndex(pos[i].F, pos[i].S, b1)][getIndex(pos[i + 1].F, pos[i + 1].S, b2)] < dp[i+1][b2]) {
					dp[i + 1][b2] = dp[i][b1]
						+ dist[getIndex(pos[i].F, pos[i].S, b1)][getIndex(pos[i + 1].F, pos[i + 1].S, b2)];
					road[i+1][b2] = 



				}*/	
			}
		}
	}

	pii ans = MP(INF, INF);
	for (int b = 0; b < 3; b++) {
		ans = min(ans, dp[n * n - 1][b]);
	}
	cout << ans.F << " " << ans.S << "\n";

