int n, m;
string s, t;
int ans = 0;

bool nxt(int idx, int from) {
  if (idx == m) return true;
  bool f = 0;
  for (int i = from + 1; i < n; ++i) {
    if (s[i] == t[idx]) {
      if (nxt(idx + 1, i)) {
        ans = max(i - from - 1, ans);
        if (idx == m - 1) {
          ans = max(ans, n - i - 1);
          f = 1;
        }
        f = 1;
      }
      else break;
    }
  }
  if (f) return true;
  return false;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cin >> s >> t;
  n = s.size();
  m = t.size();
  for (int i = 0; i < n; ++i) {
    if (s[i] == t[0]) {
      if (nxt(1, i)) ans = max(ans, i);
      else break;
    }
  }
  cout << ans << endl;
}

