main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    int n;
    cin >> n;
    for (int i = 2; i < N; i++){
        if (p[i] == 0){
            for (int j = i; j < N; j++){
                p[j] = i;
            }
        }
    }
    for (int i = 0; i < n; i++) cin >> a[i];
    reverse(a, a + n);
    for (int i = 0; i < n; i++){
        if (taken[a[i]]){
            b[i] = a[i] - 1;
            int y = b[i];
            while(y != 1){
                int x = p[y];
                int k = 0;
                while(y % x == 0){
                    y /= x;
                    k++;
                }
                d[i].pb({x, k});
            }
            for (auto x: d[i]){
                taken[x.F] = 1;
            }
        } else{
            b[i] = a[i];
            taken[a[i]] = 1;
            d[i].pb({a[i], 1});
        }
    }
    int z = 0;
    for (int i = 0; i < n; i++){
        int ok = 0;
        for (auto x: d[i]){
            if (have[x.F] < x.S) ok = 1;
            have[x.F] = max(x.S, have[x.F]);
        }
        if (!ok) z = 1;
    }
    int res = 1;
    for (int i = 1; i < N; i++){
        for (int j = 0; j < have[i]; j++){
            res = res * i % mod;
        }
    }
    cout << (z + res) % mod;
}

