/*
    Approach:

    We are asked if we can turn a 2D vector A into a vector B using a
    vector C by using some combination of operations:

        1. rotate A by 90 degrees
        2. add C to A

    An equivalent way to view this problem, is to start with one of the four
    rotations of A, and then repeatedly trying to add on of the four rotations
    of C.  This simplifies matters because we can simply try to guess a rotation
    of A, subtract it from B, and then see if we can construct the resulting
    vector using C only.

    In other words, we want to see if (B - rot^i(A)) = x*C + y*rot(C) = D
    for i in (0,1,2,3) and x and y any integer.

    We can compute D, but we need to find x and y to see if they are integral.
    Since C and rot(C) are orthogonal, we can decompose D into components
    parellel to C and rot(C) using projection.

    For C and D, we have:

      C_x*D_x + C_y*D_y = |C| * |D| * cos(angle between C and D)  (dot product)

    |D|*cos(angle between C and D) is the length of D projected onto C.  We
    want to check if this length is divisible by |C|.  In other words, we want
    to check if the dot product is divisible by |C|^2, or:

      C_x*D_x + C_y*D_y = 0 (mod C_x*C_x + C_y*D_y)

    (The case for rot(C) and D is analogous.)

    An important special case is that where C is the zero-vector (in that case,
    we can't project anything, but we must still check if B is zero too).
*/

typedef long long LL;

typedef pair<int,int> PII;

PII read_vector() { PII v; cin >> v.first >> v.second; return v; }
PII rot(PII v) { return PII(-v.second, v.first); } 
PII operator-(PII a, PII b) { return PII(a.first - b.first, a.second - b.second); }
LL lensq(PII c) { return (LL)c.first*c.first + (LL)c.second*c.second; }

// Can we project D onto C such that the component of D parallel to C
// can be expressed as an integer product of C?
bool can_project(PII D, PII C)
{
    LL dot = (LL)B.first*C.first + (LL)B.second*C.second;
    return dot % lensq(C) == 0;
}

// Can D be expressed using integer coordinates in a coordinate system with
// axes C and rot(C)?
bool can_express(PII D, PII C)
{
    if (C == PII(0, 0)) return D == PII(0, 0);  // special case: C == (0,0)
    return can_project(B, C) && can_project(B, rot(C));
}

bool can(PII A, PII B, PII C)
{
    // Try the four rotations of A:
    REP(_, 4) {
        if (can_express(B - A, C)) return true;
        A = rot(A);
    }
    return false;
}

int main()
{
    PII A = read_vector();
    PII B = read_vector();
    PII C = read_vector();
    cout << (can(A, B, C) ? "YES" : "NO") << endl;
}

