const int MOD = 1e9 + 7;
int res[MN];
vector<int> ls[MN];

void resetAll() {
    memset(res, 0, sizeof res);
    REP(i,MN) ls[i].clear();
}

int add[MN], gt[MN], inv_gt[MN];

int power(int x, int k) {
    if (k == 0) return 1;
    if (k == 1) return x % MOD;

    int mid = power(x, k >> 1);
    mid = mid * mid % MOD;

    if (k & 1) return mid * x % MOD;
    return mid;
}
int inverse(int x) {
    return power(x, MOD - 2);
}

int C(int n, int k) {
    return gt[n] * inv_gt[k] % MOD * inv_gt[n-k] % MOD;
}

