ll solve(vector<ll> v) {

    if(v.size()==2) return v[1]-v[0];
    vector<ll> v1,v2;
    forn(i,v.size()) {
        if(i>=2) v1.pb(v[i]);
        if(i!=1 and i!=2) v2.pb(v[i]);
    }
    return min(solve(v1)+v[1]-v[0], solve(v2)+v[2]-v[1]);
}

void solve() {

    ll n;
    cin >> n;
    ll w[2*n],ans=INF;
    forn(i,2*n) cin >> w[i];
    sort(w,w+2*n);
    forn(i,2*n) {
        forsn(j,i+1,2*n) {
            vector<ll> v;
            forn(k,2*n) {
                if(k!=i and k!=j) v.pb(w[k]);
            } 
            ans = min(ans,solve(v));
        }
    }
    cout << ans << "\n";
}   

