long long tmp,n,k,len,L,kth,Res,Len; map<long long,long long> vis;
inline long long Read(){long long t=0,f=1; char c=getchar();
	for (;c>57||c<48;c=getchar()) if (c=='-') f=-1;
	for (;c>47&&c<58;c=getchar()) t=10ll*t+1ll*c-48ll; return t*f;
}
long long cal(long long now,long long len){
//	printf("%I64d %I64d\n",now,len);
	if (vis[now]) return vis[now];
	if (now==len) return 1; if (now==Len) return 0;
	return vis[now]=cal(now/2,len)+cal(now-now/2-1,len);
}
long long solve(long long l,long long r){
//	printf("solve:%I64d %I64d %I64d %I64d\n",l,r,kth,L);
	long long mid=l+r>>1;
	if (r-l+1ll==L) return l+(L+1)/2ll-1ll;
	vis.clear(); long long tmp=cal(mid-l,len);
//	printf("num::::%I64d %I64d\n",mid-l,tmp);
	if (tmp<kth){kth-=tmp; return solve(mid+1,r);}
	if (tmp>=kth) return solve(l,mid-1);
}
int main(){
	n=Read(),k=Read();
	if (k==1){printf("1\n"); return 0;}
	if (k==2){printf("%I64d\n",n); return 0;}
	if (n==k){printf("%I64d\n",n-1) return 0;}
	for (tmp=1,len=n-2,k-=2;;len=(len-1)/2){
		if (k<=tmp){//printf("%I64d\n",k);
			vis.clear(),Len=len+1; long long t=cal(n-2,len);
		//	printf("%I64d %I64d %I64d\n",n-2,len,t);
			if (k<=t) kth=k,L=len,Len=len+1,Res+=solve(2,n-1);
			else kth=k-t,L=len+1,Len=len,Res+=solve(2,n-1);
			printf("%I64d\n",Res); return 0;
		}
		k-=tmp,tmp*=2;
	}
}

