int gcd (short a, short b) { return b ? gcd (b, a % b) : a; }

int main() {
    short a,b,c,d; std::cin>>a>>b>>c>>d;

    /* числитель = высота экрана * ширину картинки
     * знаменатель = ширина экрана * высоту картинки
     * отношение показывает ЗАНЯТОЕ пространство картинки на мониторе */
    int numerator=b*c, denominator=a*d;

    /* если отношение задано неправильно (дробь неправильная), то
     * означает, что картинка первую заняла вертикаль (a/b > c/d)
     * и поэтому поменяем местами числитель со знаменателем */
    if (numerator > denominator) std::swap(numerator, denominator);

    // сокращаем дробь, найдя НОД при помощи алгоритма Евклида
    int divisor = gcd(numerator, denominator);
    if (divisor != 1) {
        numerator/=divisor; denominator/=divisor;
    }

    /* в числителе выводим разность знаменателя и числителя, чем будет
     * являться именно СВОБОДНОЕ пространство монитора, что требует
     * задача */
    std::cout<<denominator - numerator<<"/"<<denominator;
    return 0;
}

