using namespace std;

int main() {
	int n; cin >> n;
	int even = n / 2;
	int odd = n - even;

	vector<int> a(n);
	for (int& x : a) {
		cin >> x;
		if (x == 0) { continue; }
		if (x % 2 == 0) {
			--even;
		} else {
			--odd;
		}
	}
	int orig_complexity = 0;
	for (int i = 0; i < n-1; ++i) {
		if (a[i] == 0 || a[i+1] == 0) { continue; }
		if (a[i] % 2 != a[i+1] % 2) { orig_complexity += 1; }
	}
	// если концы одноимённые, то альтернативы - 0 или 2
	// если разноимённые, то всегда 1
	// если открытое начало или конец, то считать одноимёнными

	// выгоднее идти в порядке меньшие -> большие

	// vector<pair<int, int>> similar_p;
	// vector<pair<int, int>> dissim_p;
	int dissim_p_cnt = 0;
	vector<pair<int, int>> similar_s;
	{
		int i = 0;
		while (i < n) {
			if (a[i] == 0) {
				int left_idx = i-1;
				while (i < n-1 && a[++i] == 0) {}
				int right_idx = i;

				// left_idx = max(left_idx, 0);
				// right_idx = min(right_idx, n-1);
				// if (left_idx == 0) { left_idx = right_idx; }
				// if (right_idx == n-1) { right_idx = left_idx; }

				// (a[right_idx]%2 == a[left_idx]%2 ? similar_p : dissim_p).push_back({left_idx, right_idx});
				if (right_idx == n || left_idx == -1 || a[right_idx]%2 == a[left_idx]%2) {
					int seglen = right_idx - left_idx - 1;
					int parity = (left_idx != -1 ? a[left_idx]%2 : (right_idx != n ? a[right_idx]%2 : 1));
					similar_s.push_back({seglen, parity});
				} else {
					dissim_p_cnt += 1;
				}
			} else {
				++i;
			}
		}
	}

	// std::sort(similar_p.begin(), similar_p.end(), [](const auto& a, const auto& b) {
	// 	return a.second - a.first < b.second - b.first;
	// });

	std::sort(similar_s.begin(), similar_s.end());
	int similar_failed = 0;
	for (const auto& [len, parity] : similar_s) {
		int& capacity = (parity == 0 ? even : odd);
		if (capacity >= len) {
			capacity -= len;
		} else {
			similar_failed += 1;
		}
	}

	// dump for debug
	fprintf(stderr, "similar_s: ");
	for (const auto& x : similar_s) {
		fprintf(stderr, "(len=%i of %i), ", x.first, x.second);
	}
	fprintf(stderr, "\n");
	fprintf(stderr, "similar_failed = %i\n", similar_failed);
	fprintf(stderr, "%i\n", dissim_p_cnt);

	int total_complexity = orig_complexity + dissim_p_cnt * 1 + similar_failed * 2;
	std::cout << total_complexity;
}

#include<bits/stdc++.h>
using namespace std;

typedef long long s64;
const int D=1e9+7;
s64 mi(s64 x,int y=D-2)
{
	s64 ans=1;
	while(y)
	{
		if(y&1)ans=ans*x%D;
		x=x*x%D;y>>=1;
	}
	return ans;
}
s64 F,F2;
void solve(s64 n)
{
	s64 a0=0,a1=0,a2=0,a3=0;
	int my=0;
	while((s64)my*my<=n)++my;
	--my;
	s64 s2=0,s4=0,s6=0;
	for(int y=1;y<=my;++y)
	{
		int y_2=(s64)y*y%D;
		(s2+=y_2)%=D;
		(s4+=(s64)y_2*y_2)%=D;
		(s6+=(s64)y_2*y_2%D*y_2)%=D;
	}
	for(int x=0;(s64)x*x<=n;++x)
	{
		while((s64)x*x+(s64)my*my>n)
		{
			int y_2=(s64)my*my%D;
			(s2-=y_2)%=D;
			(s4-=(s64)y_2*y_2)%=D;
			(s6-=(s64)y_2*y_2%D*y_2)%=D;
			--my;
		}
		(a0+=my)%=D;
		int x_2=(s64)x*x%D;
		(a1+=(s64)x_2*my+s2)%=D;
		(a2+=(s64)x_2*x_2%D*my+2*x_2*s2+s4)%=D;
		(a3+=(s64)x_2*x_2%D*x_2%D*my+(s64)x_2*x_2%D*s2%D*3+x_2*s4%D*3+s6)%=D;
	}
	n%=D;
	a0=(4*a0+1)%D;a1=4*a1%D;a2=4*a2%D;a3=4*a3%D;
	F=(n*(n+1)%D*a0%D-a2+a1)%D*mi(2)%D;
	F2=( n*(n+1)%D*(2*n+1)%D*a0%D-2*a3+3*a2-a1)*mi(6)%D;
}

int main()
{
	//freopen("1.in","r",stdin);
	s64 n;
	cin>>n>>D;
	solve(n);
	cout<<(((n+1)%D*F-F2)%D+D)%D;
}

