	ios_base::sync_with_stdio(false); cin.tie(nullptr);
	cin >> m >> a >> b;
	vector<long long> x(a, -1);
	for (long long i = 0, X = 0; x[i % a] == -1;)
	{
		x[i % a] = X;
		i += a;
		if (i <= m)
		{
			X = max(X, i);
			while (i >= b)
			{
				long long f = i % a;
				if (x[f] == -1)
					x[f] = X;
				i -= b;
			}
		} else
			break;
	}
	for (long long i = 0; i < a; i++)
	{
		if (x[i] != -1)
		{
			long long n = (m - i) / a + 1;
			long long N = (m - x[i]) / a + 1;
			ans += n-N + N*(m - x[i] + 1) - a*(N - 1) * N / 2;
		}
	}
	cout << ans;
	return 0;
}

