bool cmp(int a,int b)
{
	return a>b;
}


int N;
int val[8];
int cPrimes[8];
int bestAns;

void dfs(int i,int cur,bool needExtraRoot)
{
	if(i==N)
	{
		bestAns = min(bestAns,cur+N+needExtraRoot);
		return;
	}
	//root
	if(i == 0)
	{
		dfs(i+1,cur,0);
	}
	//child of root
	if(i==0)
		dfs(i+1,cur+cPrimes[i],1);
	else
	{
		if(needExtraRoot)
			dfs(i+1,cur+cPrimes[i],1);
	}
	//child of other node
	for(int j=0;j<i;j++)
		if(!(val[j]%val[i]))
		{
			val[j] /= val[i];
			dfs(i+1,cur,needExtraRoot);
			val[j] *= val[i];
		}
}

int main()
{
	cin >> N;
	for(int i=0;i<N;i++)
	{
		cin >> val[i];
	}
	sort(val,val+N,cmp);
	for(int i=0;i<N;i++)
	{
		cPrimes[i] = 0;
		int temp = val[i];
		for(int j=2;j<=10e6;j++)
		{
			if((j*j) > temp)
				break;
			while(!(val[i]%j))
			{
				val[i] /= j;
				cPrimes[i]++;
			}
		}
		if(val[i] > 1)
			cPrimes[i]++;
		val[i] = temp;
	}
	bestAns = (1<<30);

	dfs(0,0,0);
	cout << bestAns << endl;
	return 0;
}

