#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

vector<pair<ll, pair<ll, ll> > > answer;

void add(ll x, ll y, ll z) {
    answer.push_back(make_pair(x, make_pair(y, z)));
}

void solve(ll n, ll a, ll b, ll c) {
    if ((c + a - b) % 2 != 0) return;
    ll x = (c + a - b) / 2;
    if (x < 1) return;
    ll y = (c + b - a) / 2;
    if (y < 1) return;
    ll z = (a + b - c) / 2;
    if (z < 1) return;

    if (x > y) swap(x, y);
    if (y > z) swap(y, z);
    if (x > y) swap(x, y);
    if ((x + y + z) * (x + y + z) * (x + y + z) - x * x * x - y * y * y - z * z * z == n * 3) {
        add(x, y, z);
    }
}

int calculate(pair<ll, pair<ll, ll> > a) {
    if (a.first == a.second.second) return 1;
    if (a.first == a.second.first || a.second.first == a.second.second) return 3;
    return 6;
}

int main() {
    ios_base::sync_with_stdio(false);
    ll n;
    cin >> n;
    if (n % 3 != 0) {
        cout << 0 << endl;
        return 0;
    }
    n /= 3;
    vector<ll> divisors;
    for (ll a = 1; a * a <= n; ++a) {
        if (n % a == 0) {
            divisors.push_back(a);
        }
    }
    for (int indA = 0; indA < divisors.size(); ++indA) {
        ll a = divisors[indA];
        if (n % a != 0) {
            continue;
        }
        ll d = n / a;
        for (int indB = indA; indB < divisors.size() && a * divisors[indB] * divisors[indB] <= n; ++indB) {
            ll b = divisors[indB];
            if (d % b != 0) continue;
            ll c = d / b;
            solve(n, a, b, c);
        }
    }
    ll ans = 0;
    sort(answer.begin(), answer.end());
    ans += calculate(answer[0]);
    for (int i = 1; i < answer.size(); ++i) {
        if (answer[i] == answer[i - 1]) continue; else ans += calculate(answer[i]);
    }
    cout << ans << endl;
    return 0;
}

