void zAlgorithm(int len, char s[], int *Z) {
	rep(n, len)
		Z[n] = 0;
	Z[0] = len;
	int l = 0, r = 0;
	for(int k = 1; k < len; k++) {
		if(!(k >= r)) {
			int p = k - l;
			if(Z[p] + k < r) {
				Z[k] = Z[p];
			} else {
				l = k;
				while(r < len && s[r] == s[r - k]) {
					r++;
				}
				Z[k] = r - k;
			}
		} else {
			int i = k, j = 0;
			while(i < len && s[i] == s[j]) {
				i++;
				j++;
			}
			l = k;
			r = i;
			Z[k] = j;

		}

	}
}
int findSmallestDivisor(int len, int *pre) {
	int k = 1;
	while(k <= len) {
		// printf("k: %d len: %d\n", k, len);
		bool isMultiple = true;
		for(int i = 0; i < len; i += k) {
			if(pre[i] < k) {
				// printf("i: %d k: %d pre[i]: %d\n", i, k, pre[i]);
				isMultiple = false;
				break;
			}
		}
		if(isMultiple)
			return k;
		k++;
	}
	return 0;
}
