lli numSubTree(int uu, vector<int> adjList[], int A[], int N) {
	stack<int> ss, s;
	ss.push(uu);
	while(ss.size()) {
		int u = ss.top();
		s.push(u);
		ss.pop();
		for(int i = 0; i < adjList[u].size(); i++) {
			int v = adjList[u][i];
			ss.push(v);
		}
	}
	lli dp[N + 1];
	rep(n, N + 1)
		dp[n] = 0;
	while(s.size()) {
		int u = s.top();
		s.pop();
		lli total = 1, prod = 1;
		bool isLeafNode = true;
		for(int i = 0; i < adjList[u].size(); i++) {
			isLeafNode = false;
			int v = adjList[u][i];
			if(A[uu] == A[v] && v >= uu) {
				// printf("Hehe\n");
				continue;
			}
			prod = (prod*(dp[v] + 1))%MOD;
		}

		// printf("u: %d prod: %lld isLeafNode: %d\n", u, prod, isLeafNode );
		dp[u] = prod;
	}
	return dp[uu];
}

vector<int> * getAdjListWithMin(int i, int D, int N, vector<int> adjList[], int A[]) {
	vector<int> *modifiedAdjList = new vector<int>[N];
	stack<int> s;
	lli minVal = A[i], maxVal = A[i] + D;
	bool visited[N];
	rep(n, N) {
		visited[n] = false;
	}
	s.push(i);
	while(s.size()) {
		int u = s.top();
		s.pop();
		visited[u] = true;
		for(int j = 0; j < adjList[u].size(); j++) {
			int v = adjList[u][j];
			if(!visited[v] && A[v] >= minVal && A[v] <= maxVal) {
				modifiedAdjList[u].push_back(v);
				// printf("%d->%d\n", u, v);
				s.push(v);
			}
		}
	}
	return modifiedAdjList;
}

void buildSparseTable(lli ((*fn)(lli , lli)), int N, lli A[], vector<lli> sparseTable[]) {
	rep(i, N) {
		// sparseTable[i].push_back(0);
		sparseTable[i].push_back(A[i]);
	}
	int j = 1;
	while((1<<j) <= N) {
		for(int i = 0; (i + (1<<j)) <= N; i++) {
			// printf("i1: %d i2: %d j: %d\n", i, i + (1<<(j - 1)), j - 1);
			sparseTable[i].push_back(fn(sparseTable[i][(j - 1)], sparseTable[i + (1<<(j - 1))][(j - 1)]));
		}
		j++;
	}
	// for(int i = 0; i < N; i++) {
