int sparseTableQuery(lli identity, lli ((*fn)(lli , lli)), int L, int R, int N, vector<lli> sparseTable[]) {
	int i = L;
	lli total = identity;
	while(i <= R) {
		int j = 0;
		while((i + (1<<(j + 1)) - 1) <= R) {
			j++;
		}
		total = fn(total, (sparseTable[i][j]));
		i = i + (1 << j);
	}
	return total;
}

void reflectOfX(double x, double y, double z, double vx, double vy, double vz, double Px, double *px, double *py, double *pz) {
	*py = ((Px - x)*vy)/vx + y;
	*pz = ((Px - x)*vz)/vx + z;
	*px = Px;
}

void reflectOfY(double x, double y, double z, double vx, double vy, double vz, double Py, double *px, double *py, double *pz) {
	*px = ((Py - y)*vx)/vy + x;
	*pz = ((Py - y)*vz)/vy + z;
	*py = Py;
}

void reflectOfZ(double x, double y, double z, double vx, double vy, double vz, double Pz, double *px, double *py, double *pz) {
	*px = ((Pz - z)*vx)/vz + x;
	*py = ((Pz - z)*vy)/vz + y;
	*pz = Pz;
}
bool isValid(double *x, double *y, double *z, double a, double b) {
	return (*x >= 0 && *x <= a && *z >= 0 && *z <= b && *y >= 0);
}
int main(int argc, char const *argv[]) {
	double a = 0, b = 0, m = 0;
	scanf("%lf %lf %lf", &a, &b, &m);
	double vx = 0.0, vy = 0.0, vz = 0.0;
	scanf("%lf %lf %lf", &vx, &vy, &vz);
	double *px = new double(), *py = new double(), *pz = new double();
	*px = ((double)a)/2.0, *py = (double)m, *pz = 0.0;
	bool atX = true;
	while(true) {
		double *tx = new double(), *ty = new double(), *tz = new double();
		// printf("%lf %lf %lf - %lf %lf %lf\n", *px, *py, *pz, vx, vy, vz);
		*tx = *px, *ty = *py, *tz = *pz;
		reflectOfY(*tx, *ty, *tz, vx, vy, vz, 0.0, tx, ty, tz);
		if(isValid(tx, ty, tz, a, b)) {
			px = tx, py = ty, pz = tz;
			break;
		}
		if(atX) {
			*tx = *px, *ty = *py, *tz = *pz;
			if(vz > 0) {
				reflectOfZ(*tx, *ty, *tz, vx, vy, vz, b, tx, ty, tz);
				if(isValid(tx, ty, tz, a, b)) {
					px = tx, py = ty, pz = tz;
					vz = -vz;
					atX = false;
					continue;
				}	
			} else if(vz < 0) {
				reflectOfZ(*tx, *ty, *tz, vx, vy, vz, 0.0, tx, ty, tz);
				if(isValid(tx, ty, tz, a, b)) {
					px = tx, py = ty, pz = tz;
					vz = -vz;
					atX = false;
					continue;
				}				
			}
			*tx = *px, *ty = *py, *tz = *pz;
			reflectOfX(*tx, *ty, *tz, vx, vy, vz, *tx == 0.0?a:0.0, tx, ty, tz);
			px = tx, py = ty, pz = tz;
			vx = -vx;
		} else {
			*tx = *px, *ty = *py, *tz = *pz;
			if(vx > 0) {
				reflectOfX(*tx, *ty, *tz, vx, vy, vz, a, tx, ty, tz);
				if(isValid(tx, ty, tz, a, b)) {
					px = tx, py = ty, pz = tz;
					atX = true;
					vx = -vx;
					continue;
				}	
			} else if(vx < 0) {
				reflectOfX(*tx, *ty, *tz, vx, vy, vz, 0.0, tx, ty, tz);
				if(isValid(tx, ty, tz, a, b)) {
					px = tx, py = ty, pz = tz;
					atX = true;
					vx = -vx;
					continue;
				}				
			}
			*tx = *px, *ty = *py, *tz = *pz;
			reflectOfZ(*tx, *ty, *tz, vx, vy, vz, *tz == 0.0?b:0.0, tx, ty, tz);
			px = tx, py = ty, pz = tz;
			vz = -vz;	
		}
	}
	printf("%lf %lf\n", *px, *pz);

 	return 0;
}

