int get(int s){
	ret = cn = 0;
	memset(mark, 0, sizeof(mark));
	for (; cn < n; s = (s + 1) % 3, ret++){
		for (int i = 0; i < comp[s].size(); i++){
			uu = comp[s][i];
			if (mark[uu])	continue;
			flag = 1;
			for (int j = 0; j < sadj[uu].size(); j++){
				vv = sadj[uu][j];
