	for(int i=2; i*i<=n; i++) {
		if(pi[i]!=pi[i-1]) {
			trace(lehmer_pi(n/i),n/i,i);
			ans+=lehmer_pi(n/i)-lehmer_pi(i);
		}
	}
	trace(ans);
	for(int i=2; i*i*i<=n; i++)
		ans++;
	cout<<ans<<endl;
}
