#include<bits/stdc++.h>
using namespace std;
typedef long long LL;
const LL MAXS = 20000000;
int K;//okolo (n/logn)**(2/3), ale wiecej niz sqrt(n)
int FEN;

vector<int> minPrimeDivisor;
vector<int> primes;

int fenwick[MAXS+3];
void fenAdd(int i, int v){ for(; i<FEN; i |= i+1) fenwick[i] += v; }
int fenSum(int i){ int s=0; while(i>=0) { s+=fenwick[i]; i=(i&(i+1))-1; } return s; }

void sieve(){
    minPrimeDivisor.resize(K+1);
    primes.reserve(K/20);
    for(int i=0;i<K;i++)
        minPrimeDivisor[i] = 1e9;
    for(LL i=2;i<K;i++){
        if(minPrimeDivisor[i] != 1e9)
            continue;
        primes.push_back(i);
        minPrimeDivisor[i] = i;
        for(LL j=i*(LL)i;j<K;j+=i)
            minPrimeDivisor[j] = min(minPrimeDivisor[j],(int)i);
    }
}

struct HASH{
  size_t operator()(const pair<LL,LL>&x)const{
    return hash<LL>()((x.first)^((x.second)<<29));
  }
};

unordered_map<pair<LL,LL>,LL,HASH> queries;

LL findGreaterPrimeThanSqtr(LL n){
    LL low = 0, high = primes.size(),mid,lg=-1;
    while(low <= high){
        mid = (low+high)/2;
        if(primes[mid]*(LL)primes[mid] > n){
            high = mid-1;
            lg = mid;
        }
        else
            low = mid+1;
    }
    return lg;
}

void memorize(LL n, LL p){
    if(p == 0 || queries.count({n,p}) > 0)
        return;
    if(n < (LL)primes[p-1]*(LL)primes[p-1]){
        LL p2 = findGreaterPrimeThanSqtr(n);
       if(p != p2){
            memorize(n,p2);
            return;
       }
    }
    if(n <= K){
        queries[{n,p}] = 0;
        return;
    }
    memorize(n,p-1);
    memorize(n/primes[p-1],p-1);
}

void calcForSmall(){
    vector<pair<LL,LL> > sortedInts(K), sortedQueries(queries.size());
    for(int i=0;i<K;i++)
        sortedInts[i] = {minPrimeDivisor[i],i};

    int ct = 0;
    for(auto a:queries)
        sortedQueries[ct++] = {a.first.second, a.first.first};

    sort(sortedInts.begin(),sortedInts.end());
    sort(sortedQueries.begin(),sortedQueries.end());

    int cur = K-2;
    for(int i=sortedQueries.size()-1; i>=0; i--){
        while(sortedInts[cur].first >= primes[sortedQueries[i].first]){
            fenAdd(sortedInts[cur].second,1);
            cur--;
        }
        queries[{sortedQueries[i].second,sortedQueries[i].first}] = fenSum(sortedQueries[i].second);
    }

}

LL solve(LL n,int p){
    if(p == 0)
        return n;
    if(n < (LL)primes[p-1]*(LL)primes[p-1]){
        LL p2 = findGreaterPrimeThanSqtr(n);
        if(p != p2){
            return solve(n,p2) + p2 - p;
        }
    }
    if(queries.count({n,p}) > 0)
        return queries[{n,p}];
    queries[{n,p}] =  solve(n,p-1) - solve(n/primes[p-1],p-1);
    return queries[{n,p}];
}

void memPi(LL n){
    LL spg = findGreaterPrimeThanSqtr(n);
    memorize(n,spg);
}

LL getPi(LL n){
    LL spg = findGreaterPrimeThanSqtr(n);
    return solve(n,spg) + spg - 1;
}

int32_t main(){
    ios::sync_with_stdio(false);

    LL Z;
    cin >> Z;

    K = MAXS;
    FEN = K+2;
    queries.max_load_factor(0.25);
    queries.reserve(MAXS);
    sieve();


    for(LL i=2;i*i<Z;i++){
        if(binary_search(primes.begin(),primes.end(),i)){
            memPi(Z/i);
        }
    }
    calcForSmall();
    LL res = 0;
    while(primes[res]*(LL)primes[res]*(LL)primes[res] <= Z)
        res++;
    int ct = 0;
    for(LL i=2;i*i<Z;i++){
        if(binary_search(primes.begin(),primes.end(),i)){
            res += getPi(Z/i);
            res -= ct+1;
            ct++;
        }
    }
    cout<<res<<endl;
}

