int inter(pi x,pi y){
	if(x.first > y.second || y.first > x.second) return 0;
	return min(x.second,y.second) - max(x.first,y.first) + 1;
}
bool cover(pi x,pi y){
	return x.first <= y.first && x.second >= y.second;
}
void refine(vector <pi> &f,int k){
	tmp.clear();
	for(pi ln : f){
		if(ln.first < mid[k] && ln.second > mid[k]){
			tmp.push_back(mp(ln.first,len[k - 1]));
			tmp.push_back(mp(1,ln.second - mid[k]));
		}else if(ln.second < mid[k]){
			tmp.push_back(ln);
		}else{
			tmp.push_back(mp(ln.first - mid[k],ln.second - mid[k]));
		}
	}
	f = tmp;
}
void show(){
	cout <<"F1 = ";
	for(pi x : f1){
		cout << "["<<x.first <<","<<x.second<<"]  ";
	}
	cout << endl;
	cout <<"F2 = ";
	for(pi x : f2){
		cout << "["<<x.first <<","<<x.second<<"]  ";
	}
	cout << endl;
}
void solve(int k){
	if(k == 1){
		if(f1.size() && f2.size()) res = max(res,1);
		return ;
	}
	for(pi line1 : f1)
	for(pi line2 : f2){
		res = max(res,inter(line1,line2));
	}
	// pruning
	tmp.clear();
	for(pi line1 : f1){
		if(line1.second == mid[k]) --line1.second;
		if(line1.first == mid[k]) ++line1.first;
		if(line1.second < line1.first) continue;
		tmp.push_back(line1);
	}
	f1 = tmp;

	tmp.clear();
	for(pi line2 : f2){
		if(line2.second == mid[k]) --line2.second;
		if(line2.first == mid[k]) ++line2.first;
		if(line2.second < line2.first) continue;
		tmp.push_back(line2);
	}
	f2 = tmp;

	tmp.clear(); tmp2.clear();
	for(pi x : f1){
		bool ok = 1;
		for(pi y : f2) if(cover(y,x)) ok = 0;
		if(ok) tmp.push_back(x);
	}
	for(pi y : f2){
		bool ok = 1;
		for(pi x : f1) if(cover(x,y)) ok = 0;
		if(ok) tmp2.push_back(y);
	}
	f1 = tmp;
	f2 = tmp2;

	refine(f1,k);
	refine(f2,k);

	solve(k - 1);
}
