#define pb push_back
#define mp make_pair
#define st first
#define nd second
#define ll long long
#define pii pair<int, int>

bool visited[401][401][9][6];
bool used[401][401];
int t[500];


int X[10], Y[10];
int n;

void init(){
	X[1] = 0;
	Y[1] = 1;
	X[2] = 1;
	Y[2] = 1;
	X[3] = 1;
	Y[3] = 0;
	X[4] = 1;
	Y[4] = -1;
	X[5] = 0;
	Y[5] = -1;
	X[6] = -1;
	Y[6] = -1;
	X[7] = -1;
	Y[7] = 0;
	X[8] = -1;
	Y[8] = 1;
}

int cnt = 0;
void bfs(){
	pair<pii, pii> init(mp(mp(400, 400), mp(1, t[0])));
	queue<pair<pii, pii> > mq[50];
	mq[0].push(init);
	visited[init.st.st][init.st.nd][init.nd.st][init.nd.nd] = true;
	for(int i = 0; i < n; i++){
		while(!mq[i].empty()){
			pair<pii, pii> u = mq[i].front();
			mq[i].pop();
			if(!used[u.st.st][u.st.nd]){
				used[u.st.st][u.st.nd] = true;
				cnt++;
			}
			if(u.nd.nd == 1 && i != n - 1){
				int dir1 = (u.nd.st - 1 - 1 + 8)%8 + 1, dir2 = (u.nd.st - 1 + 1 + 8)%8 + 1;
				if(!visited[u.st.st + X[dir1]][u.st.nd + Y[dir1]][dir1][t[i + 1]]) 
					mq[i + 1].push(mp(mp(u.st.st + X[dir1], u.st.nd + Y[dir1]), mp(dir1, t[i + 1])));
				if(!visited[u.st.st + X[dir2]][u.st.nd + Y[dir2]][dir2][t[i + 1]]) 
					mq[i + 1].push(mp(mp(u.st.st + X[dir2], u.st.nd + Y[dir2]), mp(dir2, t[i + 1])));
			}
			else if(u.nd.nd != 1){
				if(!visited[u.st.st + X[u.nd.st]][u.st.nd + Y[u.nd.st]][u.nd.st][u.nd.nd - 1])
					mq[i].push(mp(mp(u.st.st + X[u.nd.st], u.st.nd + Y[u.nd.st]), mp(u.nd.st, u.nd.nd - 1)));
			}
		}
	}
}


int main(){
	init();
	scanf("%d", &n);
	REP(i, n) scanf("%d", &t[i]);
	bfs();
	printf("%d\n", cnt);
}

