    while (y) {
        if (y&1) z=z*x%mo;
        y>>=1;
        x=x*x%mo;
    }
    return z;
}
LL Calc2(LL l,LL r) {
    l%=mo;
    r%=mo;
    return (l+r)*(r-l+1)%mo*inv2%mo;
}
LL getsum(LL x) {
    x%=mo;
    return x*(x+1)%mo*(x*2+1)%mo*inv6%mo;
}
LL Calc3(LL l,LL r) {
    return (getsum(r)-getsum(l-1))%mo;
}
LL SQRT(LL x) {
    LL l=0,r=N;
    while (l<r) {
        LL mid=(l+r+1)/2;
        if (mid*mid>x) r=mid-1;
        else l=mid;
    }
    return l;
}
LL getf(LL x) {
    LL l=SQRT(x);
    return (sum1[l]+l*((x-l*l+1)%mo))%mo;
}
LL getg(LL x) {
    LL l=SQRT(x);
    return (sum2[l]+l*Calc2(l*l,x))%mo;
}
LL geth(LL x) {
    LL l=SQRT(x);
    return (sum3[l]+l*Calc3(l*l,x))%mo;
}
void prework() {
    nx=n%mo;
    inv2=mul(2,mo-2);
    inv6=mul(6,mo-2);
    for (LL i=1;i*i<=n;i++) {
        LL l=(i-1)*(i-1),r=i*i-1;
        sum1[i]=(sum1[i-1]+(r-l+1)%mo*(i-1))%mo;
        sum2[i]=(sum2[i-1]+Calc2(l,r)*(i-1))%mo;
        sum3[i]=(sum3[i-1]+Calc3(l,r)*(i-1))%mo;
    }
    for (LL i=0;i*i<=n;i++) {
        f[i]=getf(n-i*i);
        g[i]=getg(n-i*i);
        h[i]=geth(n-i*i);
    }
}
void work() {
    LL ans1=0;
    for (LL i=0;i*i<=n;i++) {
        LL nowx=i*i%mo*f[i]+g[i];
        nowx%=mo;
        ans1=(ans1+nowx)%mo;
    }
    ans1=ans1*4%mo;
    LL nowx=(nx+1)*nx%mo*inv2%mo;
    ans1=(ans1+nowx)%mo;
    ans1=ans1*(nx+1)%mo;
    LL ans2=0;
    for (LL i=0;i*i<=n;i++) {
        LL nowp=i*i%mo;
        LL nowx=nowp*nowp%mo*f[i]+nowp*2*g[i]+h[i];
        nowx%=mo;
        ans2=(ans2+nowx)%mo;
    }
    ans2=ans2*4%mo;
    nowx=getsum(nx);
    ans2=(ans2+nowx)%mo;
    ans1=((ans1-ans2)%mo+mo)%mo;
    printf("%lld\n",ans1);
}
int main() {
    scanf("%lld",&n);
    prework();
    work();
    return 0;
}

