	if (n <= i) return v != w;

	if ((v[i] + w[i-1]) % 2 == 0) {
		w[i] = (v[i] + w[i-1]) / 2;
		return search(i + 1, n);
	}
	else {
		long long r(0);
		w[i] = (v[i] + w[i-1]) / 2;
		r += search(i + 1, n);
		w[i] = (v[i] + w[i-1]) / 2 + 1;
		r += search(i + 1, n);
