long long inv(long long x){ 

  long long y=M-2,res=1; 

  for (; y; y>>=1,x=x*x%M) if (y&1) res=res*x%M; 

  return res;  

} 

long long C(int n,int m){//求组合数
    long long ans = 1;
    for(long long i = 1; i <= m; i++){
        ans = (ans * (n-i+1) * inv(i)) % MOD;
    }
    return ans;
}


