int criba[MAXN];
vector<int> P;
void BuildS(){
    for(int p = 2; p*p < MAXN; p++)if(!criba[p])
        for(int i = p*p;  i < MAXN; i+=p)criba[i] = p;
    forr(i, 2, MAXN)if(!criba[i]) P.pb(i);
}

bool OFlow(ll a, ll b){
    ll res = a*b, nb = res/a;
    return b != nb;
}

ll ans;
vector<int> E;
void tryme(){
    ll act = 1;
    dforn(i, sz(E)){
        int p = P[i];
        forn(j, E[i]-1){
            if(OFlow(act, p))return;
            act *= p;
        }
    }
//    printf("%lld es un candidato\n", act);
    ans = min(ans, act);
}

void solve(int n, int lim){
    if(n == 1){ tryme(); return; }
    forr(d, 2, min(lim+1, n+1))if(n%d == 0){
        E.pb(d); solve(n/d, d); E.pop_back();
    }
}

