vector<vector<int>> pr(vector<vector<int>> a, vector<vector<int>> b)
{
    vector<vector<int>> r;
    r.resize(2);
    r[0].resize(2);
    r[1].resize(2);
    for(int i=0;i<2;++i)
    {
        for(int j=0;j<2;++j)
        {
            for(int k=0;k<2;++k)
            {
                r[i][j] = (r[i][j] + a[i][k]*1LL*b[k][j]%M)%M;
            }
        }
