inline int power(int x,int y)
{
	int s=1;
	for (int i=30;i>=0;i--)
	{
		s=1LL*s*s%p;
		if ((1<<i)&y)
			s=1LL*s*x%p;
	}
	return s;
}

inline void preC()
{
	fac[0]=1;
	for (i=1;i<=n;i++)
		fac[i]=1LL*i*fac[i-1]%p;
	inv[n]=power(fac[n],p-2);
	for (i=n-1;i>=0;i--)
		inv[i]=1LL*(i+1)*inv[i+1]%p;
	return;
}

inline int C(int x,int y)
{
	return 1LL*fac[x]*inv[y]%p*inv[x-y]%p;
}

const int q=33333;
const long double pi=acos(-1);

struct complex
{
	long double r,i;

	inline complex operator + (const complex t) const
	{
		return (complex) {r+t.r,i+t.i};
	}

	inline complex operator - (const complex t) const
	{
		return (complex) {r-t.r,i-t.i};
	}

	inline complex operator * (const complex t) const
	{
		return (complex) {r*t.r-i*t.i,r*t.i+i*t.r};
	}
};

complex W[80000][2],X[80000],Y[80000],Z[80000];
int R[80000],x[80000],y[80000],z[80000];
int x0[80000],x1[80000],y0[80000],y1[80000],z0[80000],z1[80000],z2[80000];
int w;

inline void preFFT()
{
	for (w=1;w<=n;w=w<<1);
	w=w<<1;
	for (int i=0;i<w;i++)
	{
		W[i][0]=(complex) {cos(2*pi*i/w),sin(2*pi*i/w)};
		W[i][1]=(complex) {cos(2*pi*i/w),-sin(2*pi*i/w)};
	}
	for (int i=0;i<w;i++)
		for (int j=i,k=1;k<w;j=j>>1,k=k<<1)
			R[i]=(R[i]<<1)|(j&1);
	return;
}

inline void FFT(complex *T,int t)
{
	for (int i=0;i<w;i++)
		if (i<R[i])
			swap(T[i],T[R[i]]);
	complex x,y;
	for (int i=1;i<w;i=i<<1)
		for (int j=0;j<w;j=j+(i<<1))
			for (int k=0;k<i;k++)
				x=T[j+k],y=W[w/(i<<1)*k][t]*T[i+j+k],T[j+k]=x+y,T[i+j+k]=x-y;
	if (t)
		for (int i=0;i<w;i++)
			T[i].r=T[i].r/w;
	return;
}

inline void turncomplex(complex *X,int *x)
{
	for (int i=0;i<w;i++)
		X[i].r=x[i],X[i].i=0;
	return;
}

inline void turnnum(int *x,complex *X)
{
	for (int i=0;i<w;i++)
		x[i]=(x[i]+((long long) (X[i].r+0.5))%p)%p;
	return;
}

inline void mainFFT(int *x,int *y,int *z)
{
	turncomplex(X,x);
	turncomplex(Y,y);
	FFT(X,0);FFT(Y,0);
	for (int i=0;i<w;i++)
		Z[i]=X[i]*Y[i];
	FFT(Z,1);
	turnnum(z,Z);
	return;
}

inline void solve(int m)
{
	if (b[m])
		return;
	t++,b[m]=t;
	for (int i=0;i<=n;i++)
		g[b[m]][i]=power(h[m],i);
	if (m==1)
	{
		for (int i=1;i<=n;i++)
			f[b[m]][i]=1;
		return;
	}
	int t1=m/2,t2=m-m/2;
	solve(t1),solve(t2);
	memset(x,0,sizeof(x));
	for (int i=0;i<=n;i++)
		x[i]=1LL*f[b[t1]][i]*g[b[t2]][i]%p*inv[i]%p;
	memset(x0,0,sizeof(x0));
	for (int i=0;i<=n;i++)
		x0[i]=x[i]%q;
	memset(x1,0,sizeof(x1));
	for (int i=0;i<=n;i++)
		x1[i]=x[i]/q;
	memset(y,0,sizeof(y));
	for (int i=0;i<=n;i++)
		y[i]=1LL*f[b[t2]][i]*inv[i]%p;
	memset(y0,0,sizeof(y0));
	for (int i=0;i<=n;i++)
		y0[i]=y[i]%q;
	memset(y1,0,sizeof(y1));
	for (int i=0;i<=n;i++)
		y1[i]=y[i]/q;
	memset(z0,0,sizeof(z0));
	mainFFT(x0,y0,z0);
	memset(z1,0,sizeof(z1));
	mainFFT(x1,y0,z1);
	mainFFT(x0,y1,z1);
	memset(z2,0,sizeof(z2));
	mainFFT(x1,y1,z2);
	memset(z,0,sizeof(z));
	for (int i=0;i<=n;i++)
		z[i]=(1LL*q*q*z2[i]+1LL*q*z1[i]+z0[i])%p;
	for (int i=0;i<=n;i++)
		f[b[m]][i]=1LL*z[i]*fac[i]%p;
	return;
}

int main()
{
	scanf("%I64d%d",&m,&n);
	if (m>n)
		return printf("0"),0;
	preC();
	preFFT();
	h[0]=1;
	for (i=1;i<=n;i++)
		h[i]=(h[i-1]+h[i-1])%p;
	solve(m);
	for (i=m;i<=n;i++)
		s=(s+1LL*f[b[m]][i]*C(n,i))%p;
	printf("%d",s);
	return 0;
}

