inline char nextchar()
{
	static char buf[100000],*p1=buf, *p2=buf;
	return (p1 == p2)&&(p2=(p1=buf)+fread(buf,1,100000,stdin),p1==p2)?EOF:*p1++;
}

inline long long read(char type)
{
	if(type=='f')
	{
		long long p=0;
		char ch=0;
		bool sign=false;
		while (!isdigit(ch))
		{
			sign|=(ch=='-');
			ch=nextchar();
		}
		while(isdigit(ch))
		{
			p=p*10+(ch^48);
			ch=nextchar();
		}
		p=sign?-p:p;
		return p;
	}
	else
	{
		int x=0,f=1;
		char ch=getchar();
		while(ch<'0'||ch>'9')
		{
			if(ch=='-')
			{
				f=-1;
			}
			ch=getchar();
		}
		while(ch>='0'&&ch<='9')
		{
			x=(x<<1)+(x<<3)+(ch^48);
			ch=getchar();
		}
		return x*f;
	}
}

inline void write(int x)
{
	static long long stk[100],top=0;
	if(x==0)
	{
		putchar('0'); return;
	}
	if(x<0)
	{
		x=-x;
		putchar('-');
	}
	while(x)
	{
		stk[++top]=x%10;
		x/=10;
	}
	while(top)
	{
		putchar(stk[top--]+'0');
	}
}

