int solve(int a, int b){

    queue < pair<pair<int, int>, int> > q; q.push({{a, b}, 0});
    while(q.size() > 0){
        pair<pair<int, int>, int> node = q.front(); q.pop();

        if(node.first.first == node.first.second)
            return node.second;
        int x = node.first.first;
        int y = node.first.second;

        if(x % 2 == 0)
            q.push({{x / 2, y}, node.second + 1});
        if(x % 3 == 0)
            q.push({{x / 3, y}, node.second + 1});
        if(x % 5 == 0)
            q.push({{x / 5, y}, node.second + 1});

        if(y % 2 == 0)
            q.push({{x, y / 2}, node.second + 1});
        if(y % 3 == 0)
            q.push({{x, y / 3}, node.second + 1});
        if(y % 5 == 0)
            q.push({{x, y / 5}, node.second + 1});

    }
    return -1;
}

