double calculateAngle(vector<int> x, vector<int> y) {

    double tu = x[0]*y[0] + x[1]*y[1] + x[2]*y[2] + x[3]*y[3] + x[4]*y[4];

    double ab_lenght = sqrt(x[0]*x[0] + x[1]*x[1] + x[2]*x[2] + x[3]*x[3] + x[4]*x[4]);
    double ac_lenght = sqrt(y[0]*y[0] + y[1]*y[1] + y[2]*y[2] + y[3]*y[3] + y[4]*y[4]);

    double result = (tu*1.0)/(ab_lenght*ac_lenght);

    double angle = acos(result) * 180.0 / PI;

    return angle;
}

