#define inv(a) power(a, mod - 2)
typedef long long ll;
const int mod = 1e9 + 7;
const int maxm = 100000 + 5;
const int maxp = 400;
int m, p;
int id[maxm], ver[maxp];
int mark[maxm], mu[maxm];
ll f[maxm], g[maxm][maxp];
vector<int> prime; 
vector<int> rec[maxm];
ll power(ll x, ll y) {
	ll re = 1;
	while(y) {
		if(y & 1) re = re * x % mod;
		x = x * x % mod;
		y >>= 1;
	}
	return re;
}
void init(int n) {
	mark[1] = 1, mu[1] = 1;
	for(int i = 2; i <= n; ++i) {
		if(!mark[i]) {
			prime.push_back(i);
			mu[i] = -1;
		}
		for(unsigned int j = 0; j < prime.size(); ++j) {
			int x = i * prime[j]; if(x > n) continue;
			mark[x] = 1;
			if(i % prime[j]) {
				mu[x] = 0;
				return;
			}
			mu[x] = -mu[x];
		}
	}
}
int main() {
	read(m);
	init(m);
	for(int i = 1; i <= m; ++i) rec[i].clear();
	for(int i = 1; i <= m; ++i) {
		for(int j = i; j <= m; j += i) {
			rec[j].push_back(i);
		}
	}
	for(int i = 1; i <= m; ++i) {
		if(!id[m / i]) id[m / i] = ++p, ver[p] = m / i;
	}
	for(int i = 1; i <= m; ++i) {
		for(unsigned int j = 0; j < rec[i].size(); ++j) {
			int x = rec[i][j];
			for(int k = 1; k <= p; ++k) {
				g[i][k] = (g[i][k] + mu[x] * (ver[k] / x)) % mod;
			}
		}
	} 
	ll r = inv(m);
	for(int i = 2; i <= m; ++i) {
		for(unsigned int j = 0; j < rec[i].size(); ++j) {
			int x = rec[i][j]; if(x == i) continue;
			f[i] = (f[i] + f[x] * g[i / x][id[m / x]] % mod) % mod; 
		}
		f[i] = (f[i] * r + 1) % mod * inv(1 - g[1][id[m / i]] * r % mod) % mod;
	}
	ll an = 0;
	for(int i = 1; i <= m; ++i) {
		an = (an + f[i]) % mod;
	}
	an = (an * r + 1) % mod;
	cout << (an + mod) % mod << endl;
	return 0;
}

