ll f, T, t0, a1, t1, p1, a2, t2, p2;

ll ok(ll &mid, ll &tempo, ll &falta){ return min(falta, mid*a2)*t2 + t0*max(0LL, falta-mid*a2) <= tempo;}

ll solve(ll &tempo, ll &falta){
	if(falta*t0 <= tempo) return 0;
	ll bot=0, top=falta, mid;
	while(top-bot>1){
		mid=(top+bot)>>1;
		if(ok(mid, tempo, falta)) top= mid;
		else bot= mid;
	}
	if(ok(bot, tempo, falta)) top=bot;
	if(!ok(top, tempo, falta)) return -1;
	return top*p2;
}

