const int NMAX = 100010, MOD = 1e9+7;
int m;
int f[NMAX];
vector<int> fact[NMAX];

int gcd(int x, int y){
	if(y) return gcd(y, x % y);
	return x;
}

int Power(int x, int y){
	int ret = 1;
	while(y){
		if(y & 1) ret = 1LL * ret * x % MOD;
		x = 1LL * x * x % MOD;
		y >>= 1;
	}
	return ret;
}

int inv(int x){
	return Power(x, MOD - 2);
}

int calc(int a, int b){//gcd(x, a) = b -- count the number of x in [1..m]
	int prime[10], cnt = 0;
	int tmpa = a / b;
	for(int i = 2; i <= tmpa; i++){
		if(tmpa % i == 0)
			prime[cnt++] = i;
		while(tmpa % i == 0)
			tmpa /= i;
	}
	int sum = 0;
	for(int i = 0; i < (1 << cnt); i++){
		int mult = 1, sign = 1;
		for(int j = 0; j < cnt; j++){
			if(i & (1 << j)){
				mult *= prime[j];
				sign *= -1;
			}
		}
		sum += (m / b) / mult * sign;
	}
	return sum;
}

int main(){
	scanf("%d", &m);
	for(int i = 1; i <= m; i++){
		for(int j = i * 2; j <= m; j++){
			fact[j].push_back(i);
		}
	}
	f[1] = 1;
	for(int i = 2; i <= m; i++){
		int sum = 0;
		for(int j : fact[i]){
			if(i % j == 0){
				sum = (sum + 1LL * f[j] * calc(i, j) % MOD * inv(m) % MOD) % MOD;
				//printf("gcd(x, %d) = %d cnt: %d\n", i, j, calc(i, j));
			}
		}
		//printf("gcd(x, %d) = %d cnt: %d\n", i, i, calc(i, i));
		f[i] = 1LL * (1 + sum) * (1LL * m * inv(m - calc(i, i)) % MOD) % MOD;
	}
	int sum = 0;
	for(int i = 1; i <= m; i++)
		sum = (sum + 1LL * f[i] * inv(m) % MOD) % MOD;
	printf("%d\n", sum);
	return 0;
}

