constexpr size_t S = 20;

int32_t solve(std::string const &A, std::string const &B) {
	std::array<std::bitset<S>, S> pair_original {};
	std::vector<size_t> L;

	for (size_t i = 0; i < size(A); ++i)
		if (A[i] != B[i]) {
			L.push_back(A[i] - 'a');
			L.push_back(B[i] - 'a');
			pair_original[A[i] - 'a'].set(B[i] - 'a');
		}

	uint32_t sol = S * S;
	sort(begin(L), end(L));
	L.erase(unique(begin(L), end(L)), end(L));

	debug(L);

	do {
		uint32_t cnt = 0;
		auto pair = pair_original;

		for (size_t i = 0; i+1 < size(L); ++i) {
			pair[L[i]].reset(L[i]);
			cnt += pair[L[i]].any();
			pair[L[i+1]] |= pair[L[i]];
		}

		pair[L.back()].reset(L.back());
		cnt += pair[L.back()].count();

		sol = std::min(sol, cnt);
	} while (next_permutation(begin(L), end(L)));

	return sol;
}

