inline void upd(int &x, int y) {
    x += y;
    if(x >= md) x -= md;
}

int anss = 0;
int dp[2][10][10][2][2][1 << 9][1 << 9];
int solve(int x, int y) {
    if(x == y) {
        int ans = 0;
        for(int i = s.size() - 1; i >= 0; i--) {
            ans = ans * 1ll * 10 % md;
            ans += s[i] - '0';
            ans %= md;
        }
        return ans;
    }
    int t = 0;
    int n = s.size();

    int tec_mask0 = 0;
    int tec_mask1 = 0;
    for(int z = 1; z <= 9; ++z) {
        int x1 = x * z;
        int y1 = y * z;
        if(x1 <= 9 && y1 <= 9) {
            tec_mask0 |= (1 << (x1 - 1));
            tec_mask1 |= (1 << (y1 - 1));
        }
    }

    int nm0 = 0, nm1 = 0;
    for(int i = 0; i <= 9; ++i)
        bit_num0[i] = bit_num1[i] = -1;

    for(int i = 0; i < 9; ++i) {
        if(tec_mask0 & (1 << i)) {
            bit_num0[i + 1] = nm0++;
        }
        if(tec_mask1 & (1 << i)) {
            bit_num1[i + 1] = nm1++;
        }
    }

    for(int i = 0; i < 2; ++i) {
        for(int j = 0; j < 10; ++j) {
            for(int k = 0; k < 10; ++k) {
                for(int g0 = 0; g0 < 2; ++ g0) {
                    for(int g1 = 0; g1 < 2; ++g1) {
                        for(int msk0 = 0; msk0 < (1 << nm0); ++msk0) {
                            for(int msk1 = 0; msk1 < (1 << nm1); ++msk1) {
                                dp[i][j][k][g0][g1][msk0][msk1] = 0;
                            }
                        }
                    }
                }
            }
        }
    }
    dp[0][0][0][0][0][0][0] = 1;
    for(int i = 0; i < n; ++i) {
        int a = s[i] - '0';
        for(int j = 0; j < 10; ++j) {
            for(int k = 0; k < 10; ++k) {
                for(int z = 0; z < 10; ++z) {
                    int c0 = (z * x + j);
                    int c1 = (z * y + k);
                    int d0 = c0 / 10;
                    int d1 = c1 / 10;
                    c0 %= 10;
                    c1 %= 10;

                    for(int g0 = 0; g0 < 2; ++g0) {
                        for(int g1 = 0; g1 < 2; ++g1) {
                            int b0 = g0;
                            int b1 = g1;
                            if(c0 < a) b0 = 0;
                            else if(c0 > a) b0 = 1;

                            if(c1 < a) b1 = 0;
                            else if(c1 > a) b1 = 1;

                            for(int mask0 = 0; mask0 < (1 << nm0); ++mask0) {
                                int to_mask0 = mask0;
                                if(bit_num0[c0] != -1) to_mask0 |= (1 << bit_num0[c0]);
                                for(int mask1 = 0; mask1 < (1 << nm1); ++mask1) {
                                    int to_mask1 = mask1;
                                    if(bit_num1[c1] != -1) to_mask1 |= (1 << bit_num1[c1]);

                                    upd(dp[t ^ 1][d0][d1][b0][b1][to_mask0][to_mask1],
                                        dp[t][j][k][g0][g1][mask0][mask1]);
                                }
                            }

                        }
                    }
                }
            }
        }
        for(int j = 0; j < 10; ++j) {
            for(int k = 0; k < 10; ++k) {
                for(int g0 = 0; g0 < 2; ++ g0) {
                    for(int g1 = 0; g1 < 2; ++g1) {
                        for(int msk0 = 0; msk0 < (1 << nm0); ++msk0) {
                            for(int msk1 = 0; msk1 < (1 << nm1); ++msk1) {
                                dp[t][j][k][g0][g1][msk0][msk1] = 0;
                            }
                        }
                    }
                }
            }
        }
        t ^= 1;
    }
    int ans = 0;
    for(int j = 0; j < (1 << nm0); ++j) {
        for(int k = 0; k < (1 << nm1); ++k) {
            bool f = false;
            for(int z = 1; z <= 9; ++z) {
                int x1 = x * z;
                int y1 = y * z;
                if(x1 <= 9 && y1 <= 9) {
                    if(bit_num0[x1] == -1) exit(-1);
                    if(bit_num1[y1] == -1) exit(-1);
                    if(j & (1 << bit_num0[x1])) {
                        if(k & (1 << bit_num1[y1])) {
                            f = true;
                        }
                    }
                }
            }
            if(f) {
                upd(ans, dp[t][0][0][0][0][j][k]);
            }
        }
    }

    return ans;
}

