    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++)
            for(int k=0;k<N;k++)
                for(int o=0;o<4;o++)
                    ways[i][j][k][0]=calcways(i,j,k,o);
    //printf("%i\n",calcways(1,1,1,4));
	scanf("%i %i",&n,&T);
