    }
    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++)
            for(int k=0;k<N*N;k++)
                for(int o=0;o<3;o++)
                    dp[i][j][k][o]=calc(i,j,k,o);
    int ans=0;
    for(int i=0;i<=(int)songs[0].size();i++)
    {
        for(int Ki=0;Ki<=T;Ki++)
        {
            int sol=dp[0][i][Ki][0];
            if(sol==0)
                continue;
            for(int j=0;j<=(int)songs[1].size();j++)
            {
                for(int k=0;k<=(int)songs[2].size();k++)
                {
                    int total=i+j+k;
                    int anss=calcways(i,j,k,3);
                    anss=mul(anss,mul(fact[i],mul(fact[j],fact[k])));
                    if(anss==0)
                        continue;
                    for(int Kj=0;Kj<=T-Ki;Kj++)
                    {
                        int sol2=dp[0][j][Kj][1];
                        if(sol2==0)
                            continue;
                        int Kk=T-Ki-Kj;
                        int sol3=dp[0][k][Kk][2];
                        int dodajem=mul(mul(mul(sol,sol2),sol3),anss);
                        ans=add(ans,dodajem);
                    }
                }
            }
        }
    }
    printf("%i\n",ans);
    return 0;
}

