int fact(int n) 
{ 
    int res = 1; 
    for (int i = 2; i <= n; i++) 
        res = res * i; 
    return res; 
} 
int nCr(int n) 
{ 
    return fact(n) / (fact(2) * fact(n - 2)); 
} 

