inline ll qpow(ll x,ll k){
	ll res=1;
	while(k){
		if(k&1)res=res*x%mod;
		x=x*x%mod;k>>=1;
	}return res;
}
inline mat mul(mat x,mat y){
	mat res;
	for(int i=0;i<=1;i++)
	for(int j=0;j<=1;j++)
	for(int k=0;k<=1;k++)
		res.a[i][j]=(res.a[i][j]+x.a[i][k]*y.a[k][j]%mod)%mod;
	return res;
}
inline void insert(int pos,int p1,int p2){
	side[++cnt].pos=pos;
	side[cnt].p1=p1,side[cnt].p2=p2;
	if(p1==0&&p2==0){
		int tmp=v[pos]-v[pos-1];
		if(tmp>0) side[cnt].val=(x[pos]-x[pos-1])*qpow(tmp,mod-2)%mod,side[cnt].t=(x[pos]-x[pos-1])*1.0/tmp;
		else side[cnt].val=INF,side[cnt].t=1e20;
	}
	if(p1==0&&p2==1) side[cnt].val=INF,side[cnt].t=1e20;
	if(p1==1&&p2==0) side[cnt].val=(x[pos]-x[pos-1])%mod*qpow((v[pos]+v[pos-1])%mod,mod-2)%mod,side[cnt].t=(x[pos]-x[pos-1])*1.0/(v[pos-1]+v[pos]);
	if(p1==1&&p2==1){
		int tmp=v[pos-1]-v[pos];
		if(tmp>0) side[cnt].val=(x[pos]-x[pos-1])*qpow(tmp,mod-2)%mod,side[cnt].t=(x[pos]-x[pos-1])*1.0/tmp;
		else side[cnt].val=INF,side[cnt].t=1e20;
	}
}
inline void push_up(int x){tree[x]=mul(tree[x<<1],tree[x<<1|1]);}
inline void build(int l,int r,int x){
	if(l==r){
		tree[x].a[0][0]=tree[x].a[1][0]=(1-p[l]+mod)%mod;
		tree[x].a[0][1]=tree[x].a[1][1]=p[l];
		return;
	}int mid=l+r>>1;
	build(l,mid,x<<1),build(mid+1,r,x<<1|1);
	push_up(x);return;
}
inline void update(int u,int p1,int p2,int l,int r,int x){
	if(l==r){tree[x].a[p1][p2]=0;return;}
	int mid=l+r>>1;
	if(u<=mid) update(u,p1,p2,l,mid,x<<1);
	else update(u,p1,p2,mid+1,r,x<<1|1);
	push_up(x);return;
}
inline mat query(int ql,int qr,int l,int r,int x){
	if(ql>qr){
		mat res;res.a[0][0]=res.a[1][1]=1;
		return res;
	}
	if(ql<=l&&qr>=r) return tree[x];
	int mid=l+r>>1;mat res;res.a[0][0]=res.a[1][1]=1;
	if(ql<=mid) res=mul(res,query(ql,qr,l,mid,x<<1));
	if(qr>mid) res=mul(res,query(ql,qr,mid+1,r,x<<1|1));
	return res;
}

