int inf = 1000000009;

int findB(int x, int y, int a){

    LL low = -inf;
    LL high = inf;
    LL val, mid;

    while(low < high){
        mid = (low + high)/2;

        val = x - y - 2*a*mid;
        if( val < 0){
            high = mid;
        }
        else low = mid+1;
    }

    return low;
}

int findA(int x, int y, int a){

    LL low = -inf;
    LL high = inf;
    LL val, mid;

    while(low < high){
        mid =  low + (high-low)/2;

        val = x + y - 2*a*mid;
        if( val < 0){
            high = mid;
        }
        else low = mid+1;
    }

    return low;
}
