		ll start = l;
		if(rem)start = (l/x+1)*x;
		for(ll j = start; j<=r; j+=x){
			if(j!=x){
				ll pos = j - l;
				if(isPrime[pos]){
					isPrime[pos]=0;
				}
			}
		}
	}

	rep(i,0,r-l+1){
		if(isPrime[i])primes.pb(l+i);
