class Treap{
private:
    Node *root,*l;
    void insert(Node *&r,Node *a){
        if(r==NULL){
            r=a;
            return;
        }
        // cout<<r->y<<' '<<a->y<<endl;
        if(a->y < r->y){
            split(r,a->x,a->l,a->r);
            r=a;
        }else{
            if(a->x < r->x) insert(r->l,a);
            else insert(r->r,a);
        }
    }
    void split(Node *a,int X,Node *&l,Node *&r){
        if(a==NULL){
            l=r=NULL;
            return;
        }
        if(a->x > X){
            split(a->l,X,l,a->l);
            r=a;
        }else{
            split(a->r,X,a->r,r);
            l=a;
        }

    }
    void built(Node *r,Node *t){
        while(r->y > t->y && r->p!=NULL){
            r=r->p;
        }
        if(r->p==NULL && t->y < r->y){
            r->p=t;
            t->l=r;
            root=t;
            root->p=NULL;
            l=t;
            return;
        }
        t->l=r->r;
        r->r=t;
        t->p=r;
        t->l->p=t;
        l=t;
    }

public:
    Treap(){
        root=NULL;
        l=NULL;
    }
    void built(pair<int,int> a){
        Node *n=new Node(a.first,a.second);
        if(root==NULL){
            root=n;
            l=n;
            return;
        }
        //cout<<root->y<<endl;
        if(l->y < n->y){
            l->r=n;
            n->p=l;
            l=n;
            return;
        }
        built(l,n);
    }

    void insert(pair<int,int> a){
        Node *node=new Node(a.first,a.second);
        insert(root,node);
    }
    Node* getRoot(){
        return root;
    }
};
