    if(v==t || flow<=0) return flow;
    for(long long &i=ptr[v];i<n;++i){
        if(d[i]==d[v]+1 && g[v][i]>f[v][i]){
            long long push=dfs(i,min(flow,g[v][i]-f[v][i]),t,n);
            if(push>0){
                f[v][i]+=push;
                f[i][v]-=push;
                return push;
            }

        }
    }
    return 0;
}

