#include <bits/stdc++.h>

using namespace std;
int n;
int len;
long long power[60];
int maxPow = 0;
string k;
long long dp[65][65];

long long solve(int ind,int po) {
    if(ind == -1)
        return 0;
    if(po >= maxPow)
        return 1E18;

    if(dp[ind][po] != -1)
        return dp[ind][po];
    string s = "";
    long long ans = 1E18+1;
    for(int i = ind;i>=0;i--) {
        s = k[i] + s;
        long long num;
        stringstream convert(s);
        convert>>num;
        if(s.length() > 1 && s[0] == '0')
            continue;
        if(num >= n || num * power[po] < 0 || LONG_LONG_MAX / power[i] < num) {
            break;
        } else {
            ans = min(ans,solve(i-1,po+1) + num * power[po]);
        }
    }
    return dp[ind][po] = ans;
}

int main()
{
    cin>>n>>k;
    len = k.length();
    power[0] = 1;
    memset(dp,-1,sizeof dp);
    for(int i = 1;i<n;i++) {
        power[i] = power[i-1] * n;
        if(power[i] < power[i-1])
            break;
        else
            maxPow = i;
    }
    cout<<solve(len-1,0);
    return 0;
}

