#include <bits/stdc++.h>
using namespace std;
#define ll long long
vector < ll >prime;
ll cnt1[200005] , cnt2[200005] , cntans[200005] , mod = 1e9 + 7;
bool _prime(ll x){
    ll p = sqrt(x);
    for(ll i = 2;i<=p;i++)
        if (x % i == 0)
            return false;
    return true;
}
void fact(ll x , ll num){
    for(ll i = 0;i<prime.size();i++){
        while( x % prime[i] == 0 ){
            x/=prime[i];
            if (num == 1)
                cnt1[ prime[i] ]++;
            else
                cnt2[ prime[i] ]++;
        }
        if (x == 1)
            break;
    }
}
ll binpow(ll base , ll step){
    if (step == 0)
        return 1;
    if (step % 2 == 0){
        ll t = ((binpow(base , step / 2)) % mod);
        return ((t * t) % mod);
    }
    else
        return (((binpow(base , step - 1) % mod) * base) % mod);
}
int main(){
    ll n , i , j;
    cin >> n;
    for(i = 2;i<=2*n;i++)
        if (_prime(i))
            prime.push_back(i);
    for(i = 2 * n - 1;i>=2 * n - n + 1;i--)
        fact(i , 1);
    for(i = 2;i<n;i++)
        fact(i , 2);
    for(i = 0;i<prime.size();i++)
        cntans[ prime[i] ] = cnt1[ prime[i] ] - cnt2[ prime[i] ];
    ll ans = 1;
    for(i = 2;i<=2*n;i++){
        if (cntans[ i ] > 0 ){
            ans*=binpow(i , cntans[ i ] );
        }
        ans%=mod;
    }
    cout << (2 * ans)%mod - n;
    return 0;
}

