long long c, h[2], w[2];
inline long long joy(long long x) {
	return x * h[0] + (c - x * w[0]) / w[1] * h[1];
}
void getAns(int l, int r) {
	long long s0 = l * w[0], h0 = l * h[0], ans = 0;
	for (int i = l; i <= r; ++i) {
		ans = max(ans, h0 + (c - s0) / w[1] * h[1]);
		s0 += w[0], h0 += h[0];
	}
	cout << ans << endl;
}
int main() {
	// freopen("in", "r", stdin);
	cin >> c >> h[0] >> h[1] >> w[0] >> w[1];
	if (w[0] < w[1]) {
		swap(w[0], w[1]);
		swap(h[0], h[1]);
	}
	long long m = c / w[0];
	if (m < 1000) {
		getAns(0, m);
	} else {
		long long l = 0, r = m;
		while (r - l > 1000) {
			// cout << l << " " << r << endl;
			long long mid1 = (l + r) / 2;
			long long mid2 = (mid1 + r) / 2;
			if (joy(mid1) < joy(mid2)) {
				l = mid1 + 1;
			} else {
				r = mid2 - 1;
			}
		}
		getAns(l, r);
	}
	return 0;
}

