#include <bits/stdc++.h>

typedef long long ll;

ll a, k1, lowerX, upperX, x, xstep;
ll b, k2, lowerY, upperY, y, ystep;
ll l, r, d, D;

ll egcd(ll a, ll b, ll &x0, ll &y0) {
  x0 = 1, y0 = 0;
  ll x1 = 0, y1 = 1, q;

  while (b) {
    q = a/b;
    a = a - q*b;
    std::swap(a, b);
    x0 = x0 - q*x1;
    std::swap(x0, x1);
    y0 = y0 - q*y1;
    std::swap(y0, y1);
  }

  return a;
}

int sgn(ll a) {
  return a < 0 ? -1 : a > 0 ? 1 : 0;
}

bool valid(ll x, ll y) {
  if (x < lowerX || x > upperX) return false;
  if (y < lowerY || y > upperY) return false;
  return true;
}

int main() {
  scanf("%lld%lld%lld%lld%lld%lld", &a, &k1, &b, &k2, &l, &r);
  if (k2 < k1) {
    std::swap(k2, k1);
    std::swap(a, b);
  }

  lowerX = std::max(0LL, ((l - k1) + (a - 1)) / a);
  upperX = (r - k1) < 0 ? - 1 : (r - k1) / a;

  lowerY = std::max(0LL, ((l - k2) + (b - 1)) / b);
  upperY = (r - k2) < 0 ? - 1 : (r - k2) / b;

  D = k2 - k1;
  d = egcd(a, -b, x, y);
  if (D%d) {printf("0\n"); return 0;}
  x *= D/d; y *= D/d;

  xstep = -b/d;
  ystep = a/d;

  if (x < lowerX) {
    ll up = (lowerX - x + std::abs(xstep) - 1) / std::abs(xstep);
    if (xstep > 0) x += xstep * up, y -= ystep * up;
    else x -= xstep * up, y += ystep * up;
  }

  if (x > lowerX) {
    ll drop = (x - std::abs(lowerX)) / std::abs(xstep);
    if (xstep > 0) x -= xstep * drop, y += ystep * drop;
    else x += xstep * drop, y -= ystep * drop;
  }

  if (y < lowerY) {
    ll up = (lowerY - y + std::abs(ystep) - 1) / std::abs(ystep);
    if (ystep < 0) x += xstep * up, y -= ystep * up;
    else x -= xstep * up, y += ystep * up;
  }

  ll up1 = (upperX - x) / std::abs(xstep);
  ll up2 = (upperY - y) / std::abs(ystep);
  assert(up1 == up2);

  printf("%lld\n", std::max(0LL, std::min(up1, up2)) + valid(x, y));
  return 0;
}

