};
int __gcd(int a, int b)
{
	if (a < b)swap(a, b);
	while (b != 0)
	{
		a %= b;
		swap(a, b);
	}
	return a;
}
class turn
{
private:
	ell* frs = NULL;
	ell* end = NULL;
	int sz = 0;
public:
	void push_front(int a)
	{
		if (sz == 0)
		{
			frs = new ell;
			end = frs;
		}
		else
		{
			ell* q = frs;
			frs = new ell;
			frs->next = q;
			q->previsious = frs;
		}
		frs->a = a;
		sz++;
	}
	void push_back(int a)
	{
		if (sz == 0)
		{
			frs = new ell;
			end = frs;
		}
		else
		{
			end->next = new ell;
			end->next->previsious = end;
			end = end->next;

		}
		end->a = a;
		sz++;
	}
	bool pop_front(int& a)
	{
		if (sz == 0)return false;
		a = frs->a;
		if (sz == 1)
		{
			delete frs;
			frs = NULL;
			end = NULL;
		}
		else
		{
			ell* q = frs->next;
			delete frs;
			frs = q;
		}
		sz--;
		return true;
	}
	bool pop_back(int& a)
	{
		if (sz == 0)return false;
		a = end->a;
		if (sz == 1)
		{
			delete frs;
			frs = NULL;
			end = NULL;
		}
		else
		{
			ell* q = end->previsious;
			delete end;
			end = q;
		}
		sz--;
		return true;
	}
	bool front(int& a)
	{
		if (sz == 0)return false;
		a = frs->a;
		return true;
	}
	bool back(int& a)
	{
		if (sz == 0)return false;
		a = end->a;
		return true;
	}
	int size()
	{
		return sz;
	}
	void clear()
	{
		while (sz > 0)
		{
			int q;
			this->pop_back(q);
		}
	}
};
