void make_set(int v, int snm[], int rank[])
{
	snm[v] = v;
	rank[v] = 0;
}
int find_set(int v, int snm[])
{
	if (snm[v] == v)return v;
	snm[v] = find_set(snm[v], snm);
	return snm[v];
}
void union_sets(int a, int b, int snm[], int rank[])
{
	a = find_set(a, snm);
	b = find_set(b, snm);
	if (a != b) {
		if (rank[a] < rank[b])
			swap(a, b);
		snm[b] = a;
		if (rank[a] == rank[b])
			++rank[a];
	}
}
vector<int> prefix_function(string s) {
	int n = (int)s.length();
	vector<int> pi(n);
	for (int i = 1; i < n; ++i) {
		int j = pi[i - 1];
		while (j > 0 && s[i] != s[j])
			j = pi[j - 1];
		if (s[i] == s[j])  ++j;
		pi[i] = j;
	}
	return pi;
}
