using namespace std;
struct node
{
    int x, y;
    friend node operator+(node a, node b)
    {
        return (node){a.x + b.x, a.y + b.y};
    }
    friend node operator-(node a, node b)
    {
        return (node){a.x - b.x, a.y - b.y};
    }
    friend ll operator*(node a, node b)
    {
        return 1ll * a.x * b.y - 1ll * a.y * b.x;
    }
    friend bool operator<(node a, node b)
    {
        return a * b < 0;
    }
} a[N], p[N], u[N];
bool cmp(node a, node b)
{
    if (a.y == b.y)
        return a.x < b.x;
    return a.y < b.y;
}
struct tree
{
    node t[N << 2];
    void update(int v)
    {
        if (t[v << 1] * t[v << 1 | 1] == 0)
            t[v] = t[v << 1];
        else
            t[v].x = 2000001, t[v].y = 0;
    }
    void build(int v, int l, int r)
    {
        if (l == r)
        {
            t[v] = u[N];
            return;
        }
        int mid = l + r >> 1;
        build(v << 1, l, mid);
        build(v << 1 | 1, mid + 1, r);
        update(v);
    }
    void mdf(int v, int l, int r, int x)
    {
        if (l == r)
        {
            t[v] = u[x];
            return;
        }
        int mid = l + 1 >> 1;
        if (x <= mid)
            mdf(v << 1, l, mid, x);
        else
            mdf(v << 1 | 1, mid + 1, r, x);
        update(v);
    }
} T;
int n, m, L, pos[N], ans;
pair<node, int> l[N * N >> 1];
bool pd()
{
    for (int i = 1; i <= m; i++)
        if (u[i].x != 0 || u[i].y != 0)
            return 1;
    return 0;
}
