const int N=(1<<20)+10;
const LL mod=998244353;
int rev[N]; 
struct NTT{
	int n;LL g;

	void init(int m){
		g=3;n=1;int k=0;
		while(n<m){n<<=1;++k;}
		for(int i=0;i<n;++i){
			int t=0;
			for(int j=0;j<k;++j) if(i&(1<<j)) t|=(1<<(k-j-1));
			rev[i]=t;
		}
	}

	void DFT(LL *a,int flag){
		for(int i=0;i<n;++i) if(rev[i]>i) swap(a[i],a[rev[i]]);
		for(int l=2;l<=n;l<<=1){
			int m=l>>1;
			LL wn=qpow(g,flag==1?(mod-1)/l:mod-1-(mod-1)/l,mod);
			for(LL *p=a;p!=a+n;p+=l){
				LL w=1;
				for(int k=0;k<m;++k){
					LL t=w*p[k+m]%mod;
					p[k+m]=(p[k]-t+mod)%mod;
					p[k]=(p[k]+t)%mod;
					w=w*wn%mod;
				}
			}
		}
		if(flag==-1){
			LL ppp=qpow(n,mod-2,mod);
			for(int i=0;i<n;++i) a[i]=a[i]*ppp%mod;
		}
	}

	void Cheng(LL *a,LL *b,int m){
        init(m);
        //for(int i=0;i<n;++i) cout<<(a[i]+mod)%mod<<" ";cout<<endl;
        //for(int i=0;i<n;++i) cout<<(b[i]+mod)%mod<<" ";cout<<endl;
        DFT(a,1);DFT(b,1);
        for(int i=0;i<n;++i) a[i]=a[i]*b[i]%mod;
        DFT(a,-1);

    }

}ntt;


