#define sqr(a) ((a) * (a))

struct circle {
    double x, y, r;
};

circle c(double _x, double _y, double _r) {
    circle ci;
    ci.x = _x;
    ci.y = _y;
    ci.r = _r;
    return ci;
}
vector<circle> v;

bool interact(circle a, circle b) {
    if (sqrt(sqr(a.x - b.x) + sqr(a.y - b.y)) + min(a.r, b.r) <= max(a.r, b.r)
            || sqrt(sqr(a.x - b.x) + sqr(a.y - b.y)) >= a.r + b.r) {
        return false;
    }
    return true;
}

bool isIn(circle a, circle b, circle c) {
    if (sqrt(sqr(a.x - b.x) + sqr(a.y - b.y)) <= min(b.r, c.r) && (a.r => min(b.r, c.r) && a.r <= max(b.r, c.r))) {
        return true;
    }
    return false;
}

