            v.push_back(c(x, y, r));
        }
    }
    int ans = 0;
    for (int i = 0; i < v.size(); i++) {
        bool flag = true;
        for (int j = 0; j < v.size(); j++) {
            if (i != j && (interact(v[i], v[j]))) {
                flag = false;
            }
        }
        if (isIn(v[i], v[i <= 1? 2 : 0], v[i <= 1? 3 : 1]))  {
            flag = false;
        }
        if (flag) {
            ans++;
        }
    }
    cout << ans;
    return 0;
}

