const int mod=(int)1e9+7;

mat operator*(const mat &a,const mat &b){
  mat res(a.size(),vi(b[0].size()));
  assert(a[0].size()==b.size());
  rep(i,res.size())rep(j,res[0].size())rep(k,a[0].size()){
    res[i][j]+=a[i][k]*(ll)b[k][j]%mod;
    res[i][j]%=mod;
  }
  return res;
}
mat pow(mat m,int n){
  mat res(m.size(),vi(m.size()));
  rep(i,m.size())res[i][i]=1;
  for(;n;n>>=1){
    if(n&1)res=res*m;
    m=m*m;
  }
  return res;
}
int solve(int n){
  mat M(25*2,vi(25*2));
  rep(i,5)rep(j,5){
    for(int k=1;k<5;k++){
      if(j==k||j==1&&k==4||j==4&&k==1||
      j==2&&k==3||j==3&&k==2||
      i==2&&j==1&&k==3||i==3&&j==1&&k==2)continue;
      M[k*5+j][j*5+i]=1;
    }
  }
  rep(i,25)M[i+25][i]=M[i+25][i+25]=1;
  M=pow(M,n+1);
  mat A(50,vi(25));
  rep(i,25)A[i][i]=1;
  mat B=M*A;
  mat C(25,vi(1));
  C[0][0]=1;
  mat D=B*C;
  ll res=0;
  rep(i,25)res+=D[i+25][0];
  return res%mod;
}
