const int mod = 998244353;

int modExp(int a, int b, int c) {
    if (a == 0) return 0;
    int ans = 1;
    a %= c;
    while (b > 0) {
        if (b & 1) ans = ((ll)ans * a) % c;
        a = ((ll)a * a) % c;
        b /= 2;
    }
    return ans;
}

int modInv(int a, int b) {
    return modExp(a, b - 2, b);
}

template<size_t N>
void multiply(int A[N][N], int B[N][N]) {
    int C[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            C[i][j] = 0;
            for (int k = 0; k < N; k++) C[i][j] += A[i][k] * B[k][j];
        }
    }
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) A[i][j] = C[i][j];
    }
}

template<size_t N>
void matrixExp(int A[N][N], int p) {
    int B[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) B[i][j] = A[i][j];
    }
    matrixExp<N>(A, p / 2);
    multiply<N>(A, A);
    if (p % 2) multiply<N>(A, B);
}

int fibo(int n) {
    int M[2][2] = { {1,1},{1,0} };
    matrixExp<2>(M, n - 1);
    return M[0][0];
}

int solve(int n) {
    int x = fibo(n);
    int y = modInv(modExp(2, n, mod), mod);
    return ((ll)x * y) % mod;
}

ll ceil(ll a, ll b) {
    if (a * b >= 0) return (a / b) + ((a % b) != 0);
    return a / b;
}

ll floor(ll a, ll b) {
    if (a * b >= 0) return a / b;
    return a / b - ((a % b) != 0);
}

