int findGCD(int a, int b){
	int temp;
	if (a < b){
		temp = a;
		a = b;
		b = temp;
	}
	while(true){
		a %= b;
		if (a == 0) break;
		temp = a;
		a = b;
		b = temp;
	}
	return b;
}

