struct point {
  double x,y;
  point(double x, double y):x(x),y(y) {}
};

struct line {
  double A,B,C;
  line(point a, point b) {
    A = a.y-b.y;
    B = b.x-a.x;
    C = -A*a.x-B*a.y;
  }
};

struct seg {
  point p,q;
  seg(point p,point q):p(p),q(q) {}
};

int intersects(line a, line b) {
  return abs(a.A*b.B-b.A*a.B)>eps;
}

double dist(line a, point p) {
  return (a.A*p.x + a.B*p.y + a.C) / hypot(a.A, a.B);
}
double dist(seg a, point p) {
  return dist(line(a.p, a.q), p);
}

point intersectLines(line a, line b) {
  double det = a.A*b.B-b.A*a.B;
  double x = -(a.C*b.B-a.B*b.C)/det;
  double y = -(a.A*b.C-a.C*b.A)/det;
  return point(x,y);
}

int intersect(seg a, seg b, int allowCollision=0) {
  line la = line(a.p, a.q);
  line lb = line(b.p, b.q);

  double x1 = min(a.p.x, a.q.x);
  double x2 = max(a.p.x, a.q.x);
  double y1 = min(a.p.y, a.q.y);
  double y2 = max(a.p.y, a.q.y);

  double x3 = min(b.p.x, b.q.x);
  double x4 = max(b.p.x, b.q.x);
  double y3 = min(b.p.y, b.q.y);
  double y4 = max(b.p.y, b.q.y);

  if (min(x2,x4)-max(x1,x3)<-eps) return 0;
  if (min(y2,y4)-max(y1,y3)<-eps) return 0;

  if (intersects(la,lb)) {
    point c = intersectLines(la,lb);
    if (x1-eps<c.x && c.x < x2+eps
        && y1-eps<c.y && c.y < y2+eps) return 1;
    return 0;
  } else {
    if (abs(dist(la,b.p))<eps) {
      return !allowCollision;
    }
    return 0;
  }
}

void solve() {
  double x1 = gd();
  double y1 = gd();

  double x2 = gd();
  double y2 = gd();

  double xw1 = gd();
  double yw1 = gd();
  double xw2 = gd();
  double yw2 = gd();

  double xm1 = gd();
  double ym1 = gd();
  double xm2 = gd();
  double ym2 = gd();

  seg wall(point(xw1,yw1), point(xw2,yw2));
  seg mirr(point(xm1,ym1), point(xm2,ym2));

  seg direct(point(x1,y1), point(x2,y2));

  // direct view:
  if (!intersect(direct,wall) && !intersect(direct,mirr,1)) {
    printf("YES\n");
    return;
  }

  // through the mirror:
  point A(x1,y1);
  point B(x2,y2);
  double d1 = dist(mirr,A);
  double d2 = dist(mirr,B);
  if (abs(d1)<eps || abs(d2)<eps) {
    // can't look through
  } else {
    if (d1<0.0 && d2>0.0 || d1>0.0 && d2<0.0) {
      // different sides
    } else {
      //cout << "here" << endl;
      line mirrL(mirr.p, mirr.q);
      double vx = mirrL.A;
      double vy = mirrL.B;
      vx/=hypot(mirrL.A, mirrL.B);
      vy/=hypot(mirrL.A, mirrL.B);

      double px = A.x-vx*d1;
      double py = A.y-vy*d1;

      double p2x = B.x-vx*d2;
      double p2y = B.y-vy*d2;

      double d = hypot(px-p2x, py-p2y);
      //printf("%.3lf\n", d);
      //printf("%.3lf %.3lf\n", px, py);

      double move = d1*d/(d1+d2);
      //printf("%.3lf\n", move);
      double ox = px+(p2x-px)*move/d;
      double oy = py+(p2y-py)*move/d;
      //printf("%.3lf %.3lf\n", ox, oy);

      seg t1(A,point(ox,oy));
      seg t2(B,point(ox,oy));
      if (intersect(mirr, t1) && intersect(mirr,t2)) {
        if (!intersect(wall,t1) && !intersect(wall,t2)) {
          printf("YES\n");
          return;
        }
      }
    }
  }
  printf("NO\n");
}

