		priority_queue<pci, vector<pci>, greater<pci>> pq;
		pq.push({ 0, s });

		while (!pq.empty())
		{
			C d; int u;
			tie(d, u) = pq.top();
			pq.pop();

			if (d != dist[u])
				continue;

			for (auto &e : adj[u])
				if (e.flow < e.cap
						&& dist[e.dst] > dist[u] + e.cost + pot[u] - pot[e.dst])
				{
					dist[e.dst] = dist[u] + e.cost + pot[u] - pot[e.dst];
					prev[e.dst] = &e;
					pq.push({ dist[e.dst], e.dst });
				}
		}

		return dist[t] < oo;
	}

	pair<T, C> max_flow(int s, int t)
	{
		T flow = 0;
		C cost = 0;

		pot.assign(n, 0);
		while (dijkstra(s, t))
		{
			for (int u = 0; u < n; ++u)
				if (dist[u] < oo)
					pot[u] += dist[u];

			T delta = numeric_limits<T>::max();
			for (edge *e = prev[t]; e != nullptr; e = prev[e->src])
				delta = min(delta, e->cap - e->flow);

			flow += delta;
			for (edge *e = prev[t]; e != nullptr; e = prev[e->src])
			{
				e->flow += delta;
				adj[e->dst][e->rev].flow -= delta;
				cost += delta * e->cost;
			}
		}

		return {flow, cost};
	}
};


