typedef long long ll;
const int N = 1005;
const int mod = 1e9 + 7;
int bin_pow(int a, int n){
    int res = 1;
    while(n){
        if(n & 1) res = (res * 1ll * a) % mod;
        n >>= 1;
        a = (a * 1ll * a) % mod;
    }
    return res;
}
int inv(int a){
    return bin_pow(a, mod - 2);
}
void add(int & a, int & b, int & c, int & d){
    int cur1 = (a * 1ll * d + b * 1ll * c) % mod;
    int cur2 = (b * 1ll * d) % mod;
    a = cur1;
    b = cur2;
}
queue<pair< pair<int, int >, pair <int, int> > > q;
int main(){
    int k, pa, pb;
    cin >> k >> pa >> pb;
    q.push({ {1, 0}, {1, 1} });
    int ans_a = k;
    int ans_b = 1;
    while(!q.empty()){
        auto tmp = q.front();
        q.pop();
        int cnt_a = tmp.first.first;
        int cnt_seq = tmp.first.second;
        int a = tmp.second.first;
        int b = tmp.second.second;
        if(cnt_a + cnt_seq >= k){
            int cur = cnt_a + cnt_seq - k;
            int aa = (pb * 1ll * cur + pa) % mod;
            int bb = pb;
            a = (a * 1ll * aa) % mod;
            b = (b * 1ll * bb) % mod;
            add(ans_a, ans_b, a, b);
        }
        else{
            q.push({{cnt_a + 1, cnt_seq}, {(a * 1ll * pa % mod), (b * 1ll * (pa + pb) % mod)}});
            q.push({{cnt_a, cnt_seq + cnt_a}, {(a * 1ll * pb % mod), (b * 1ll * (pa + pb) % mod)}});
        }
    }
    int ans = (ans_a * 1ll * inv(ans_b)) % mod;
    cout << ans << endl;
    return 0;
}

