// Arithmetic operations
template<class T>
inline T gcd(T a, T b) {
	return (!a) ? b : gcd(b % a, a);
}

template<class T>
inline T mod(T a, T p) {
	a %= p;
	return (a < 0) ? a + p : a;
}

template<class T>
inline int numbits(T n) {
	return (!n) ? 0 : 1 + numbits(n & (n - 1));
}

template<class T>
inline T inverse(T a, T m) {
	a = mod<T>(a,m);
	return (a==1) ? 1 : mod((1-m*inverse(m%a,a))/a,m);
}

template<class T>
inline bool isPrime(T a) {
	T lim = (T)sqrt((double)a);
	for (T i = 2; i < lim; i++)
		if(a % i == 0)
			return false;
	return true;
}

template<class T>
inline T power(T a, T p, T mod) {
	if(!p) return 1;
	T temp = power(a, p>>1, mod);
	temp = (temp * temp) % mod;
	if (p&1)
		temp = (temp * a) % mod;
	return temp;
}

void get_primes(int start, int end, vector<int> &vi) {
	int *p = new int[end + 1];
	initArray<int>(p, end+1, 0); p[1] = 1;

	for (int i = 2; i <= end; i++) {
		if (!p[i]) {
			if (i >= start)
				vi.push_back(i);

			for (int j = 2*i; j <= end; j += i)
				p[j] = 1;
		}
	}
}

// Graph operations
bool dfs(int current, int final, int total, int* visited, int **edges, bool flow) {
	if (current == final)
		return true;
	if (visited[current])
		return false;
	visited[current] = true;
	for (int i = 0; i < total; i++)
		if (edges[current][i] && dfs(i, final, total, visited, edges, flow)) {
			if (flow) {
				edges[current][i]--;
				edges[i][current]++;
			}
			return true;
		}
	return false;
}

int flow(int in, int out, int total, int **edges) {
	int result = 0;
	int *visited = new int[total];
	while (initArray<int>(visited, total, 0), dfs(in, out, total, visited, edges, true))
		result++;
	return result;
}

// Disjoint datasets
void create_set(int x, int *P, int *rank) {
	P[x] = x;
	rank[x] = 0;
}

int find_set(int x, int *P) {
	if (x != P[x])
		P[x] = find_set(P[x], P);
	return P[x];
}

bool merge_sets(int x, int y, int *P, int *rank) {
	int Px = find_set(x, P);
	int Py = find_set(y, P);
	if(Px == Py)
		return false;
	if (rank[Px] > rank[Py]) P[Py] = Px;
	else P[Px] = Py;
	if (rank[Px] == rank[Py])
		rank[Py]++;
	return true;
}

// Binary tree operations
int read_cum_freq(int index, int *tree) {
	int sum = 0;
	while (index) {
		sum += tree[index];
		index -= (index & -index);
	}
	return sum;
}

void upd_freq(int index, int mxIndex, int value, int *tree) {
	while (index <= mxIndex) {
		tree[index] += value;
		index += (index & -index);
	}
}

int read_freq(int index, int *tree) {
	return read_cum_freq(index, tree) - read_cum_freq(index-1, tree);
}

// String algos.
void build_failure_function(const string &str, int *temp_arr) {
    temp_arr[0] = temp_arr[1] = 0;
    for (int i = 2; i <= static_cast<int>(str.size()); i++) {
        temp_arr[i] = -1;
        for (int ind = temp_arr[i-1]; temp_arr[i] == -1; ind = temp_arr[ind]) {
            if (str[ind] == str[i-1]) {
                temp_arr[i] = ind + 1;
            } else if (ind == 0) {
                temp_arr[i] = 0;
            }
        }
    }
}

void KMP(const string &s1, const string &s2, int *res) {
    int *temp_arr = new int[s2.size() + 1];
    build_failure_function(s2, temp_arr);

    int i = 0;
    int ind = 0;
    while (i < static_cast<int>(s1.size())) {
        if (s1[i] == s2[ind]) {
            res[i] = ++ind;
            if (res[i] == s2.size()) {
                ind = temp_arr[ind - 1];
            }
            i++;
        } else if (ind == 0) {
            res[i++] = 0;
        } else {
            ind = temp_arr[ind];
        }
    }

    delete [] temp_arr;
}

