vector<int> parent,len;
int n,m,k;

int binomialCoeff(int n, int k)  
{  
    int res = 1;  

    // Since C(n, k) = C(n, n-k)  
    if ( k > n - k )  
        k = n - k;  

    // Calculate value of  
    // [n * (n-1) *---* (n-k+1)] / [k * (k-1) *----* 1]  
    for (int i = 0; i < k; ++i)  
    {  
        res *= (n - i);  
        res /= (i + 1);  
    }  

    return res;  
}

void init(){
    parent.resize(n+1);
    len.resize(n+1);
    for(int i=1;i<=n;i++){
        parent[i] = i;
        len[i] = 1;
    } 
}

int find(int n){
    if(parent[n] == n)
        return n;
    return parent[n] = find(parent[n]);
}

void un(int a, int b){
    int x = find(a);
    int y = find(b);

    if(x == y)
        return;
    if(len[x] < len[y])
        swap(x,y);
    parent[y] = x;
    len[x] += len[y];
} 

signed main()
{
    cin>>n>>m>>k;
    init();
    for(int i=1;i<=n-k+1;i++){
        int m = i,n=i+k-1;
        while(m<=n){
            un(m,n);
            m++;
            n--;
        }
    }

    int count=0;
    for(int i=1;i<=n;i++){
        if(parent[i] == i){
            count++;
        }
    }

    // cout<<n<<" "<<count<<endl;
    cout<<binomialCoeff(m,count);

    return 0;
}

