// Time Complexity : O(nloglogn) 
void sieve() 
{ 
    spf[1] = 1; 
    for (ll i=2; i<MAXN; i++) 
        spf[i] = i; 

    for (ll i=4; i<MAXN; i+=2) 
        spf[i] = 2; 

    for (ll i=3; i*i<MAXN; i++) 
    { 
        if (spf[i] == i) 
        {  
            for (ll j=i*i; j<MAXN; j+=i) 

                if (spf[j]==j) 
                    spf[j] = i; 
        } 
    } 
} 

// A O(log n) function returning primefactorization 
// by dividing by smallest prime factor at every step 
ll getFactorization(ll x) 
{ 
    ll temp =x;
    vector<ll> ret; 
    ll mini = INT_MAX;
    while (x != 1) 
    { 
        ret.push_back(spf[x]); 
        x = x / spf[x];
        mini=min(mini,spf[x]+temp/spf[x]);
    } 
    return mini; 
}
int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);cout.tie(NULL);
    ll n;
    cin>>n;
    if(n==0){
        cout<<0<<endl;
        exit(0);
    }
    if(n==1){
        cout<<2<<endl;
        exit(0);
    }
    if(n==2){
        cout<<3<<endl;
        exit(0);
    }
    sieve();
    cout<<min(getFactorization(n),min(getFactorization(n+1),getFactorization(n+2)))<<endl;
}

