void calc (int p, int v, int x, int pr = 100){
    if (x < 0) return;
    if (used[p][v] > x) return;
    used[p][v] = x;
    q.push({p, v});
    if (d[u].find(v) == d[u].end()) d[u][v] = K - x; else d[u][v] = min(d[u][v], K - x);
    if (p >= u.size()) return;
    for (int i = max(1, u[p] - x); i < u[p] + x; i++){
        int y = v;
        calc(p + 1, v / u[p] * i, x - abs(i - u[p]), i);
    }
}
void precalc (int p, int v, int x, int pr = 100){
    if (x < 0) return;
    if (d0.find(v) == d0.end()) d0[v] = K - x; else d0[v] = min(d0[v], K - x);
    if (p >= t.size()) return;
    for (int i = max(1, t[p] - x); i < t[p] + x && i <= pr; i++){
        int y = v;
        precalc(p + 1, v / t[p] * i, x - abs(i - t[p]), i);
    }
}
vector < int > tovec(int x){
    vector < int > res, z;
    while (x != 1){
        z.pb(p[x]);
        x /= p[x];
    }
    int pr = -1;
    int c = 0;
    sort(z.begin(), z.end());
    for (int i = 0; i < z.size(); i++) if (pr == z[i]) c++; else{
        if (c != 0) res.pb(c + 1);
        c = 1;
        pr = z[i];
    }
    res.pb(c + 1);
    sort(res.begin(), res.end());
    reverse(res.begin(), res.end());
    return res;
}
