		las1[i] = (t[i] == 'A') ? las1[i - 1] + 1 : 0;
		for (int j = 0 ; j < 3 ; ++j)
			sum1[i][j] = sum1[i - 1][j] + ((t[i] - 'A') == j);
	}
	scanf("%d",&q);
	for (int i = 1 ; i <= q ; ++i)
	{
		int l,r,l1,r1,b,c,z,z0,b1,c1;
		scanf("%d%d%d%d",&l,&r,&l1,&r1);
		b = sum[r][1]  - sum[l - 1][1];
		b1 = sum1[r1][1] - sum1[l1 - 1][1];
		c = sum[r][2] - sum[l - 1][2];
		c1 = sum1[r1][2] - sum1[l1 - 1][1];
		z = min(r - l + 1,las[r]),z0 = min(r1 - l1 + 1,las1[r1]);
		if (z < z0) { ans[i] = '0'; continue; }
		if ((b + c) > (b1 + c1)) { ans[i] = '0'; continue; }
		if ((b + c) % 2 != (b1 + c1) % 2) { ans[i] = '0'; continue; }
		if ((b + c) == 0 && (b1 + c1) > 0 && z == z0) { ans[i] = '0'; continue; }
		if (z % 3 == z0 % 3) { ans[i] = '1'; continue; }
		if ((b + c) < (b1 + c1)) { ans[i] = '1'; continue; }
		else ans[i] = '0';
	}
	printf("%s",ans + 1);
	return 0;
}

