#define mod 1000000007

LL pas[101][101];
LL pd[101][1001];
int n, k;
LL m;

LL func(int i) {

	LL ret =  m/n;
	if(i < m%n) ret++;
	return ret;
}

LL bigMod(LL x, LL n) {
	if(n == 0) return 1;
	if(n == 1) return x;
	LL res = bigMod(x, n/2);
	res = (res * res) %mod;
	if(n%2 == 1) res = (res * x) % mod;
	return res;
}

LL solve(int x, int k) {
	if(x == n) {
		if(k != 0) return 0;
		else return 1;
	}
	if(pd[x][k] != -1) return pd[x][k];

	LL ret = 0;
	LL res;
	for(int i = 0; i <= k; i++) {

		if(i != 0) {
			res = bigMod(pas[n][i], func(x));
			res = (res * solve(x+1, k-i)) % mod;
		} else res = solve(x+1, k-i)%mod;


		ret = (res + ret) % mod;
	}

	return pd[x][k] = ret;
}

