typedef long long ll;
struct matrix
{
	ll arr[25][25]; 
	matrix()
	{
		memset(arr, 0, sizeof(arr)); 
	}
	inline matrix operator *(const matrix &a) const
	{
		matrix res; 
		for (int i = 0; i < 17; i++)
		{
			for (int j = 0; j < 17; j++)
			{
				for (int k = 0; k < 17; k++)
					res.arr[i][j] = (res.arr[i][j] + arr[i][k] * a.arr[k][j]) % MOD; 
			}
		}
		return res; 
	}
}; 
inline matrix quick_pow(matrix a, int n)
{
	matrix res; 
	for (int i = 0; i < 17; i++)
		res.arr[i][i] = 1; 
	while (n)
	{
		if (n & 1)
			res = res * a; 
		a = a * a; 
		n >>= 1; 
	}
	return res; 
}
inline ll G(int n)
{
	if (!n)
		return 0; 
	matrix mat, res; 
	for (int i = 0; i < 16; i++)
	{
		int a = i >> 2, b = i & 3; 
		if ((a ^ b) <= 1)
			continue; 
		mat.arr[i][16]++; 
		for (int c = 0; c < 4; c++)
		{
			if ((b ^ c) <= 1 || (!b && (a ^ c) == 1))
				continue; 
			mat.arr[i][b << 2 | c]++; 
		}
	}
	mat.arr[16][16]++; 
	res = quick_pow(mat, n - 1); 
	int ans = 4; 
	for (int i = 0; i < 16; i++)
		ans = (ans + res.arr[i][16]) % MOD; 
	return ans;
}
inline ll F(int n)
{
	if (!n)
		return 0; 
	if (n == 1)
		return 4;
	return (G(n) + G(n + 1 >> 1)) % MOD; 
}
