double nCk(int n, int k) {
  if (dp[n][k] != 0) {
    return dp[n][k];
  }
  if (n == k || k == 0) {
    return dp[n][k] = prr;
  }
  return dp[n][k] = nCk(n-1, k-1)+nCk(n-1, k);
}

double prob(double j) {

  double pr = 1;
  for (double k = 0; k < j; k++) {
    pr *= (m-k)/(m*n-k);
  }
  double not_j = n*(m-1);
  for (double k = 0; k < m-j; k++) {
    pr *= (not_j-k)/(m*n-k-j);
  }
  return pr;
}

