#define N 1000010
#define M (2*8*N) // dobro do número de arestas

int vt, ve[M], re[M], ze[M], nextt[M];
int in[N], head[N], path[N], dis[N], qu[N], lim[N];

void init() {
  vt = 1;
  memset(head, 0, sizeof(head));
}

void add(int x, int y, int cap, int wei = 0) {
  // aresta x->y é armazenada em [vt+1] e [vt+2]
  ve[++vt] = y; re[vt] = cap; ze[vt] = wei;
  nextt[vt] = head[x]; head[x] = vt;
  ve[++vt] = x; re[vt] = 0; ze[vt] = -wei;
  nextt[vt] = head[y]; head[y] = vt;
}

int mfmc(int s, int t, int n, int &fcost) {
  int flow = fcost = 0;
  while (1) {
    int qt = 0, k = 0;
    qu[qt++] = s;
    for (int i = 0; i < n; i++)
      dis[i] = lim[i] = INF;
    dis[s] = 0;

    while (k != qt) {
      if (k == N) k = 0;
      int x = qu[k++];
      for (int i = head[x]; i; i = nextt[i]) // ve[i]: adjs de x
        if (re[i] && dis[x] + ze[i] < dis[ve[i]]){
          dis[ve[i]] = dis[x] + ze[i];
          path[ve[i]] = i;
          lim[ve[i]] = min(lim[x], re[i]);
          if (!in[ve[i]]) {
            if (qt == N) qt = 0;
            qu[qt++] = ve[i];
            in[ve[i]] = 1;
          }
        }
      in[x] = 0;
    }

    if (dis[t] == INF) break;
    int f = lim[t];
    for (int p = t; p != s; p = ve[path[p] ^ 1]) {
      re[path[p]] -= f; re[path[p] ^ 1] += f; // novo residual
    }
    fcost += f * dis[t];
    flow += f;
  }
  return flow;
}

/** Código abaixo apenas para Min Cut **/

/* mark[v] = true, se v esta no mesmo lado de u no corte */
bool mark[N];

void DFS(int u) {
  mark[u] = true;
  for (int i = head[u]; i; i = nextt[i]) {
    if (i % 2) continue;
    int v = ve[i];
    if (!mark[v] && re[i] > 0) {
      DFS(v);
    }
  }
 }

void mincut(int s, int t, int n) {
  memset(mark, 0, sizeof(mark));
  DFS(s);
  /* Arestas do corte */
  for (int i = 0; i < n; i++)
    for (int j = head[i]; j; j = nextt[j]) {
      if (j % 2) continue;
      int v = ve[j];
      if (mark[i] && !mark[v])
        printf("%d %d\n", i, v);
    }
}

