        int rem_zeroes = zeroes - (i-1), rem_ones = ones - 1;
        if(rem_ones < 0 || rem_zeroes < 0)  continue;

        int last = (i == n ? 1 : 0);
        int result = ((i-1)%2 == 0 ? last : 1-last);
        if(result == g) ans += C(n-i, rem_zeroes);
    }

    ans %= MOD;
    if(ans < 0) ans += MOD;
    cout<<ans;
    return 0;
}

