vector<bool> is_prime;
void sieve(int size = 1e5 + 2104)
{
    is_prime.assign(size, true);
    is_prime[0] = false;
    is_prime[1] = false;

    for (int i = 2; i * i <= size; i++)
    {
        if (is_prime[i])
        {
            for (int j = i * i; j <= size; j += i)
            {
                is_prime[j] = false;
            }
        }
    }
}

vector<int> get_primes(int limit)
{
    vector<int> primes;
    sieve(limit);
    for (int i = 2; i <= limit; i++)
    {
        if (is_prime[i])
        {
            primes.push_back(i);
        }
    }
    return primes;
}
vector<pair<int, int>> prime_fac(int n) // time :
{
    //depends on sieve(size) algo. for generating prime
    // first run sieve() algo for size>n.
    vector<int> prime = get_primes(n);
    int cnt = 0;
    vector<pair<int, int>> fact;
    for (int i = 0; prime[i] * prime[i] <= n; i++)
    {
        while (n % prime[i] == 0)
        {
            n /= prime[i];
            cnt++;
        }
        if (cnt > 0)
            fact.emplace_back(make_pair(prime[i], cnt));
        cnt = 0;
    }
    if (n > 1)
    {
        fact.emplace_back(make_pair(n, 1));
    }
    return fact;
}
