vector<string> rotate(vector<string> &g) {
	vector<string> rg(g.size(), string(g.size(), 'O'));
	for (int i = 0; i < g.size(); ++i)
		for (int j = 0; j < g[i].size(); ++j)
			rg[g[i].size() - 1 - j][i] = g[i][j];
	return rg;
}
vector<string> flipH(vector<string> &g) {
	vector<string> rg(g.size(), string(g.size(), 'O'));
	for (int i = 0; i < g.size(); ++i)
		for (int j = 0; j < g[i].size(); ++j)
			rg[g.size() - 1 - i][j] = g[i][j];
	return rg;
}
vector<string> flipV(vector<string> &g) {
	vector<string> rg(g.size(), string(g.size(), 'O'));
	for (int i = 0; i < g.size(); ++i)
		for (int j = 0; j < g[i].size(); ++j)
			rg[i][g[i].size() - 1 - j] = g[i][j];
	return rg;
}
