typedef long long ll;
typedef pair<ll,ll> pii;

map<pii,bool> cache;

bool gana(ll a,ll b){
  map<pii,bool>::iterator it;
  if((it=cache.find(pii(a,b)))!=cache.end()) return it->second;
  if(b<a) swap(a,b);
  if(a==0) return false;

  if(!gana(a,b%a)) { cache[pii(a,b)]=true; return true;}

  ll k=a;
  while(b-k>=0){
    if(!gana(a,b-k)){  cache[pii(a,b)]=true; return true;}
    k*=a;
  }

  cache[pii(a,b)]=false;
  return false;
}

