int n, sum;
int a[1005], b[1005];
bool cost[500005][1005];
struct NODE{
	int d, b;
}t[1005];
bool cmp(NODE x, NODE y){
	if(x.d == y.d) return x.b < y.b;
	return x.d < y.d;
}
bool check(int x){
	int now = x, cnt = 0, day = 0;
	for(int i = 1;i <= n;i++) b[i] = a[i];
	for(int i = x;i >= 1;i--){
		for(int j = 1;j <= n;j++){
			if(cost[i][j]){
				cnt += min(now, b[j]);
				if(now < b[j]) b[j] -= now, now = 0;
				else now -= b[j], b[j] = 0;
			}
		}
		if(now >= i) now--, day++;
	}
	if((sum - cnt) <= day / 2) return 1;
	return 0;
}
int main(){
	int m, ans = 0;
	scanf("%d %d", &n, &m);
	for(int i = 1;i <= n;i++){
		scanf("%d", &a[i]);
		sum += a[i];
	}
	memset(cost, 0, sizeof(cost));
	for(int i = 1;i <= m;i++){
		scanf("%d %d", &t[i].d, &t[i].b);
		cost[t[i].d][t[i].b] = 1;
	}
	sort(t + 1, t + 1 + m, cmp);
	if(sum == 0) ans = 0;
	else{
		int l = 1, r = sum * 2;
		while(l <= r){
			int mid = (l + r) / 2;
			if(check(mid)){
				ans = mid;
				r = mid - 1;
			}
			else l = mid + 1;
		}
	}
	printf("%d\n", ans);
	return 0;
}

