#include <bits/stdc++.h>
#define maxn 1010
#define mo 1000000007
#define ll long long
using namespace std;
ll dp[maxn][maxn][2][2],n,k;
ll c[maxn][maxn],ans[maxn],fac[maxn];
//dp[i][j][k][l]代表前i个位置有j个good position,i,i+1是否被使用 
int main()
{
	scanf("%d%d",&n,&k);
	for (int i=1;i<=n;++i)
	{
		c[i][0]=c[i][i]=1LL;
		for (int j=1;j<=i-1;++j)
		{c[i][j]=(c[i][j]+c[i-1][j]+c[i-1][j-1])%mo;}
	 } 
	 fac[0] = fac[1] = 1LL;
	 for (int i = 2; i <= 1001; ++i) fac[i] = (fac[i - 1] * i * 1LL) % mo;
	 dp[0][0][1][0]=1;	
	 for (int i=1;i<=n;++i)
	 {
	 	for (int j=0;j<=i-1;++j)
	 	for (int now=0;now<2;++now)
	 	for (int ne=0;ne<2;++ne)
	 	{
	 		dp[i][j][ne][0]=(dp[i][j][ne][0]+dp[i-1][j][now][ne])%mo;//如果取了别的数 
	 		if (!now) dp[i][j+1][ne][0]=(dp[i][j+1][ne][0]+dp[i-1][j][now][ne])%mo;
	 		if (i<n) dp[i][j+1][ne][1]=(dp[i][j+1][ne][1]+dp[i-1][j][now][ne])%mo;
	 		//除了i=n,其他都会存在一种情况是一个去了的i-1对状态有影响。
			 //只考虑下一位会不会有使用的问题，那么dp方程就显得比较简单了。但是，这一步是存在重复的。 
		 }
	 }
	 for (int i=0;i<=n;++i)
	 {
	 	for (int now=0;now<2;++now)
	 	for (int ne=0;ne<2;++ne)
	 	ans[i]=(ans[i]+dp[n][i][now][ne])%mo;
	 	ans[i] = ans[i] * fac[n - i] % mo;
	 //	for(int j=2;j<=n-i;++j) ans[i]=ans[i]*j%mo; 

//	 for (int i=1;i<=n;++i) printf("%lld ",ans[i]);
	 int flag=-1;

	 for (int i=k+1;i<=n;++i)
	 {
	 	ans[k]=(ans[k]+flag*c[i][k]*ans[i]+mo)%mo;
	 	//对于每一个ans[i],我们要容斥处理。 
	 	flag*=-1;
	 }
	 printf("%lld\n",ans[k]);
}

# 【CF285E】Positions in Permutations（动态规划，容斥）
## 题面
[CF](https://codeforces.com/problemset/problem/285/E)
[洛谷](https://www.luogu.org/problemnew/show/CF285E)
## 题解
首先发现恰好很不好算，所以转成至少，这样子只需要确定完一部分数之后剩下随意补。
然后套一个二项式反演进行容斥就可以得到答案了。
考虑怎么算至少$m$个的贡献，
设$f[i][j][S]$表示当前填到了位置$i$，一个有$j$个贡献，$i$和$i+1$的使用情况是$S$的方案数，每次枚举一下这个位置是填$i+1$还是$i-1$还是其他就可以进行转移了。
```cpp
#include<iostream>
#include<cstdio>
using namespace std;
#define MOD 1000000007
#define MAX 1010
void add(int &x,int y){x+=y;if(x>=MOD)x-=MOD;}
inline int read()
{
	int x=0;bool t=false;char ch=getchar();
	while((ch<'0'||ch>'9')&&ch!='-')ch=getchar();
	if(ch=='-')t=true,ch=getchar();
	while(ch<='9'&&ch>='0')x=x*10+ch-48,ch=getchar();
	return t?-x:x;
}
int n,m,jc[MAX],a[MAX],ans;
int f[MAX][MAX][4],C[MAX][MAX];
int main()
{
	n=read();m=read();
	jc[0]=1;for(int i=1;i<=n;++i)jc[i]=1ll*jc[i-1]*i%MOD;
	for(int i=0;i<=n;++i)C[i][0]=1;
	for(int i=1;i<=n;++i)
		for(int j=1;j<=i;++j)
			C[i][j]=(C[i-1][j]+C[i-1][j-1])%MOD;
	f[0][0][1]=1;
	for(int i=1;i<=n;++i)
		for(int j=0;j<i;++j)
			for(int S=0;S<4;++S)
			{
				if(!f[i-1][j][S])continue;
				add(f[i][j][S>>1],f[i-1][j][S]);
				if(!(S&1))add(f[i][j+1][S>>1],f[i-1][j][S]);
				if(i!=n)add(f[i][j+1][(S>>1)|2],f[i-1][j][S]);
			}
	for(int i=0;i<=n;++i)
		for(int S=0;S<4;++S)
			add(a[i],1ll*f[n][i][S]*jc[n-i]%MOD);
	for(int i=m,d=1;i<=n;++i,d=MOD-d)add(ans,1ll*d*C[i][m]%MOD*a[i]%MOD);
	printf("%d\n",ans);
	return 0;
}
