int X, K, N, Q, jmp[9];vector<vector<int> > oneStep;
struct Stone {
    int loc, val;
    bool operator < (const Stone& o) const {
        return loc < o.loc;
    }
} magic[25];

vector<int> &go(vector<int> &beginState, int stepCnt, vector<int> &res) {
    // cout<<"go: "<<stepCnt<<'\n';
    auto step = oneStep;
    Mat mat(step);
    Mat origin;origin.data.resize(1);swap(origin.data[0], beginState);
    // cout<<bitset<8>(beginState)<<' '<<origin.data[0][beginState]<<'\n';
    for(int i = 0; (stepCnt >> i); i++) {
        if((stepCnt>>i) & 1){
            origin *= mat;
            // cout<<origin<<'\n';
        }
        mat *= mat;
        // cout<<mat<<'\n';
    }
    // cout<<origin<<'\n';
    swap(res, origin.data[0]);
    return res;
}

vector<int> &dp(vector<int> &lastState, int stepCnt, int stoneAfter[201], int stoneEffect[26]) {
    // cout<<"dp: "<<stepCnt<<'\n';
    // cout<<"dp: ";for(int i = 0; i < lastState.size(); i++) cout<<lastState[i]<<' ';
    // cout<<'\n';
    vector<int> res(lastState.size());
    int dp[stepCnt+1][lastState.size()];
    memset(dp, 0x3f, sizeof dp);
    for(int i = 0; i < lastState.size(); i++) {
        dp[0][i] = lastState[i];
    }
    for(int step = 0; step < stepCnt; step++) {
        for(int cur = 1; cur < (1<<K); cur++){
            if(__builtin_popcount(cur) != X || dp[step][cur] == INF) continue;
            if(cur & 1){
                for(int nb = 0; nb < K; nb++) {
                    if(!((cur>>1) & (1<<nb))) {
                        // cout<<"HI\n";
                        int nxt = (cur>>1) | (1<<nb);
                        // cout<<nxt<<'\n';
                        dp[step+1][nxt] = min(dp[step+1][nxt], dp[step][cur] + jmp[nb+1] + stoneEffect[stoneAfter[nb + step+1]]);
                    }
                }
            }
            else{
                int nxt = cur>>1;
                dp[step+1][nxt] = min(dp[step+1][nxt], dp[step][cur]);
            }
        }
        // cout<<"dp: ";for(int i = 0; i < lastState.size(); i++) cout<<dp[step+1][i]<<'('<<bitset<8>(i)<<')'<<' ';
        // cout<<'\n';
    }
    for(int i = 0; i < lastState.size(); i++) {
        lastState[i] = dp[stepCnt][i];
    }
    return lastState;
}

int main () {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin>>X>>K>>N>>Q;
    for(int i = 1; i <= K; i++) {
        cin>>jmp[i];
    }

    for(int i = 0; i < Q; i++) {
        cin>>magic[i].loc>>magic[i].val;
    }
    sort(magic, magic + Q);
    oneStep.resize(1<<K, vector<int> (1<<K, INF));
    for(int cur = 1; cur < (1<<K); cur++) {
        if(__builtin_popcount(cur) == X && (cur & 1) == 1) {
            for(int nb = 0; nb < K; nb++) {
                if(!((cur>>1) & (1<<nb))) {
                    // cout<<"HI\n";
                    int nxt = (cur>>1) | (1<<nb);
                    // cout<<nxt<<'\n';
                    oneStep[cur][nxt] = min(oneStep[cur][nxt], jmp[nb+1]);
                }
            }
        }
        else if (__builtin_popcount(cur) == X && (cur & 1) != 1) {
            oneStep[cur][cur>>1] = 0;
        }
    }
    // Mat fp(oneStep);
    // cout<<fp<<'\n';
    vector<int> res;
    vector<int> lastState(1<<K, INF);lastState[(1<<X)-1] = 0;
    int stoneEffect[26] = {};
    for(int i = 0; i < Q; i++) {
        stoneEffect[i+1] = magic[i].val;
    }
    int curLoc = 0;
    for(int i = 0; i < Q;) {
        if(magic[i].loc-K-curLoc > 0){
            // cout<<magic[i].loc<<' '<<K<<' '<<curLoc<<'\n';
            res = go(lastState, magic[i].loc-K-curLoc, res);
            curLoc = magic[i].loc-K;
            // cout<<curLoc<<'\n';
            swap(lastState, res);
        }
        int stoneAfter[201] = {};

        stoneAfter[K] = ++i;
        int st_loc = magic[i-1].loc;
        // cout<<st_loc<<' '<< K <<' '<< magic[i].loc<<'\n';
        while(i < Q && st_loc + K >= magic[i].loc){
            st_loc = magic[i].loc;
            stoneAfter[st_loc - curLoc] = ++i;
            // cout<<"st_loc: "<<st_loc<<'\n';
        }
        lastState = dp(lastState, st_loc - curLoc, stoneAfter, stoneEffect);
        curLoc = st_loc;
        // for(int &i: lastState) {
        //     cout<<i<<' ';
        // }
        // cout<<'\n';
    }
    res = go(lastState, N - curLoc - K, res);
    // for(int &i: res) {
    //     cout<<i<<' ';
    // }
    // cout<<'\n';
    int ans = INF;
    for(int i = 0; i <= (K-X); i++){
        ans = min(ans, res[((1<<X)-1)<<(K-X-i)]);
        swap(lastState, res);
        res = go(lastState, 1, res);
    }
    cout<<ans<<'\n';
    return 0;
}

