	if (s[i]==t[1]) e1=1;
	//ignore ith char
	lli ans=-inf;
	string temp=s;
	ans=max(ans,solve(i+1,j,in+e0,temp,t,k,dp)+(e1?in:0));
	//convert to t[0]
	temp[i]=t[0];
	ans=max(ans,solve(i+1,j+1,in+1,temp,t,k,dp)+(e2?in:0));
	//convert to t[1]
	temp[i]=t[1];
	ans=max(ans,solve(i+1,j+1,in+e2,temp,t,k,dp)+in);
	dp[i][j][in]=ans;
	return dp[i][j][in];
}

