inline int rev(int x,int n){
    int ret=0;
    for(int i=1;i<n;i<<=1){
        ret=(ret<<1)+(x&1);
        x>>=1;
    }
    return ret;
}
inline void DFT(Complex *A,int n,int DFT){
    for(int i=0;i<n;++i)tmp[rev(i,n)]=A[i];
    for(int len=2;len<=n;len<<=1){
        Complex wn=Complex(cos(2.0*PI/len),sin(2.0*PI/len)*DFT);
        for(int i=0;i<n;i+=len){
            Complex w=Complex(1,0);
            for(int j=0;j<(len>>1);++j){
                Complex s=tmp[i+j],t=w*tmp[i+j+(len>>1)];
                tmp[i+j]=s+t,tmp[i+j+(len>>1)]=s-t;
                w*=wn;
            }
        }
    }
    if(DFT==-1)for(int i=0;i<n;++i)tmp[i].real()/=n;
    for(int i=0;i<n;++i)A[i]=tmp[i];
}

Complex tA[MAXN*4],tB[MAXN*4];
inline void FFT(int *A,int *B,int *C,int n){
    int len=1;
    while(len<(n<<1))len<<=1;
    for(int i=0;i<n;++i)tA[i]=A[i],tB[i]=B[i];
    for(int i=n;i<len;++i)tA[i]=tB[i]=0;
    DFT(tA,len,1),DFT(tB,len,1);
    for(int i=0;i<len;++i)tA[i]*=tB[i];
    DFT(tA,len,-1);
    for(int i=0;i<n;++i)C[i]=((LL)(tA[i].real()+0.5))%MOD;
}

