ll Solve(int n, const int *av, bool fl = false)
{
	static int dp[1000]; memset(dp,0,sizeof(dp));
	if (fl && av[0] <= 0) return 0;
	for (int i = 0; i < Maxl; i++)
		if (av[i] < 0) return 0;
	dp[n - fl] = 1;
	for (int i = 0; i < Maxl; i++)
		for (int j = 0; j <= n; j++)
			for (int k = 1; k <= j && k <= av[i] - (fl && i == 0); k++)
				dp[j - k] += dp[j] * C[j][k];
	return dp[0];
}

