using namespace std;

struct P {

	int ew;
	int v1;
	int v2;

};

vector <P> G;			//input vector of edge/vertex pairs
vector <P> iVert;		//vector of edges and vertices included in shortest set
set <int> Vonly;		//set of vertices only
P tempP;
bool srt(P p1, P p2) { return p1.ew < p2.ew; }


vector< vector <int> > tbl;

unsigned int n;

int main() {

	int maxx = INT32_MAX;
	int len = 0;

	vector <P>::iterator z;
	set <int>::iterator y;

	cin >> n;

	for (unsigned int i = 0; i < n; i++) {
		for (unsigned int j = i+1; j < n; j++) {
			tempP.ew = i ^ j;
			if (tempP.ew != 0) {
				tempP.v1 = i;
				tempP.v2 = j;
				G.push_back(tempP);
				swap(tempP.v1, tempP.v2);
				G.push_back(tempP);
			}
		}
	}

	sort(G.begin(), G.end(), srt);
	//for (int i = 0; i < G.size(); i++) cout << G[i].ew << ", " << G[i].v1 << ", " << G[i].v2 << endl;


	//put shortest edge on output stack , and vertices into vertex set.  Increment sum of edges
	//iVert.push_back(G[0]);
	Vonly.insert(G[0].v1);
	Vonly.insert(G[0].v2);
	len += G[0].ew;

	//as each element is added to output, or larger duplicate path encountered, remove from vector, until empty
	G.erase(G.begin());

	while (!G.empty()) {
		for (z = G.begin(); z < G.end(); z++) {
			if ((Vonly.find(z->v1) != Vonly.end()) && (Vonly.find(z->v2) != Vonly.end())) {  //if both vertices already in output, get rid of duplicate, larger edge
				G.erase(z);
				break;
			}
			else if ((Vonly.find(z->v1) == Vonly.end()) ^ (Vonly.find(z->v2) == Vonly.end())) {
				iVert.push_back(*z);		 //This is optional, since we're only counting the length, not(necessarily) tracking the vertices
				Vonly.insert(z->v1);
				Vonly.insert(z->v2);
				len += z->ew;
				G.erase(z);
				break;
			}
		}
	}

	cout << len << endl;

}

