#pragma region Erato Sieve
const int MAX_PRIME = 1e6;
int divisors[MAX_PRIME] = { 0 }, primes[MAX_PRIME] = { 0 }, nPrimes = 0;
void generatePrimes() {
	for (int i = 2; i < MAX_PRIME; i++) {
		if (divisors[i] == 0) divisors[i] = primes[nPrimes++] = i;
		for (int j = 0; j < nPrimes && i * primes[j] < MAX_PRIME; j++)
			divisors[i * primes[j]] = max(divisors[i], primes[j]);
	}
}

void generateDivsorsRec(map<lli, int>::iterator it, map<lli, int> &f, vli &res, lli tm) {
	if (it == f.end()) {
		res.push_back(tm);
		return;
	}
	lli cp = 1;
	for (int i = 0; i <= it->second; i++) {
		lli ntm = tm * cp;
		generateDivsorsRec(next(it), f, res, ntm);
		cp *= it->first;
	}
}

map<lli, int> factorizeLow(lli x) {
	map<lli, int> res;
	while (x != 1) {
		res[divisors[x]]++;
		x /= divisors[x];
	}
	return res;
}

map<lli, int> factorize(lli x) { // max prime should be greater than or equal to the square root of x
	if (x < MAX_PRIME) return factorizeLow(x);
	map<lli, int> res;
	for (int i = 0; 1ll * primes[i] * primes[i] <= x; i++) {
		if (x % primes[i] == 0) {
			int c = 0;
			while (x % primes[i] == 0) c++, x /= primes[i];
			res[primes[i]] = c;
		}
	}
	if (x != 1) res[x] = 1;
	return res;
}

vli generateDivisors(lli x) {
	auto f = factorize(x);
	vli res;
	generateDivsorsRec(f.begin(), f, res, 1);
	sort(all(res));
	return res;
}

lli phi(lli x) { // if known that x is prime return x - 1
	auto f = factorize(x);
	lli res = x;
	for (auto &p : f) res -= res / p.first;
	return res;
}
