#define TASKNAME ""

using namespace std;

const int INF = 1e9 + 7;
const int MAXN = 1e6 + 7;
const double EPS = 1e-8;

struct TNode {
    TNode *left, *right;
    int sz, x;
};

TNode *new_node(int x) {
    return new TNode({nullptr, nullptr, 1, x});
}

int safe_sz(TNode *root) {
    return (root ? root->sz : 0);
}

void relax(TNode *root) {
    if (!root) return;
    root->sz = safe_sz(root->left) + safe_sz(root->right) + 1;
}

TNode *merge(TNode *left, TNode *right) {
    if (!left) {
        return right;
    }
    if (!right) {
        return left;
    }
    TNode *node = new_node(-1);
    int sz1 = safe_sz(node->left), sz2 = safe_sz(node->right);
    if (rand() % (sz1 + sz2) < sz1) {
        node->left = merge(left, right->left);
        node->right = right->right;
        node->x = right->x;
    } else {
        node->right = merge(left->right, right);
        node->left = left->left;
        node->x = left->x;
    }
    relax(node);
    return node;
}

void split(TNode *root, int sz, TNode *&left, TNode *&right) {
    if (!root || !sz) {
        left = nullptr;
        right = root;
        return;
    }
    TNode *left1, *right1;
    if (safe_sz(root->left) >= sz) {
        split(root->left, sz, left1, right1);
        left = left1;
    }
    return;
}

