void calc(int x){
	res=0;
	memset(fff,0,sizeof(fff));
	if(x>1)fff[1][1][0]=2;else fff[1][1][1]=2;
	for(int i=2;i<=n;i++){
		for(int j=1;j<=n;j++)fff[2][j][1]=fff[2][j][0]=0;
		for(int j=1;j<=min(i-1,x);j++){
			fff[2][1][0]+=fff[1][j][0];
			fff[2][1][1]+=fff[1][j][1];
			if(fff[2][1][1]>mo)fff[2][1][1]-=mo;
			if(fff[2][1][0]>mo)fff[2][1][0]-=mo;
		}
		for(int j=2;j<=min(i,x);j++){
			if(j==x){
				fff[2][j][1]+=fff[1][j-1][0]+fff[1][j-1][1];
				if(fff[2][j][1]>mo)fff[2][j][1]-=mo;
			}
			else{
				fff[2][j][1]+=fff[1][j-1][1];
				fff[2][j][0]+=fff[1][j-1][0];
				if(fff[2][j][1]>mo)fff[2][j][1]-=mo;
				if(fff[2][j][0]>mo)fff[2][j][0]-=mo;
			}
		}
		for(int j=1;j<=n;j++)fff[1][j][1]=fff[2][j][1],fff[1][j][0]=fff[2][j][0];
	}
	for(int i=1;i<=x;i++){
		res=res+fff[1][i][1];
		if(res>mo)res-=mo;
	}
	f[x]=res;
}

