		for(LL i=2;i<=n;i++){
			for(LL j=1;j<=min(i-1,m);j++){
				dp[i][1]+=dp[i-1][j];
				if(dp[i][1]>mo)dp[i][1]-=mo;
			}
			for(int j=2;j<=min(i,m);j++){
				dp[i][j]=dp[i-1][j-1];
			}
		}
		res=0;
		for(int j=1;j<=min(m,n);j++){
			res=res+dp[n][j];
			if(res>mo)res-=mo;
		}
		ans+=res;
		ans%=mo;
	}
	printf("%lld\n",ans);
}

