ll Pow(ll x, ll e)
{
    if (e == 0) return 1LL;

    ll aux = Pow(x, e/2)%MOD;

    aux = (aux*aux)%MOD;

    if (e%2 == 0) return aux;
    return (x*aux)%MOD;
}

ll choose(ll x)
{
    ll k = (f[x]*f[n-x])%MOD;
    return (f[n]*Pow(k, MOD-2))%MOD;
}

