ll inter(pll X, pll Y) {
    if(X.first > Y.first)
        swap(X, Y);
    if(X.second < Y.first)
        return 0LL;
    if(X.second >= Y.second)
        return Y.second - Y.first + 1;
    return X.second - Y.first + 1;
}

ll cnt(ll x) {
    ll a_start = la + x * ta;
    ll b_start1 = lb + ((a_start - lb + 1) / tb) * tb;
    ll b_start2 = b_start1 + tb;
    ll b_start3 = b_start1 - tb;
    ll len1 = inter({b_start1, b_start1 + (rb - lb)}, {a_start, a_start + (ra - la)});
    ll len2 = inter({b_start2, b_start2 + (rb - lb)}, {a_start, a_start + (ra - la)});
    ll len3 = inter({b_start3, b_start3 + (rb - lb)}, {a_start, a_start + (ra - la)});
    if(b_start2 > a_start + (ra - la) + 1)
        len2 = 0;
    return max(len1, max(len2, len3));
}

ll ternary_search() {
    ll st = 0, en = cyclen / ta + 1, st_mid, en_mid;
    while(en - st > 5) {
        ll third = (en - st) / 3;
        st_mid = st + third;
        en_mid = st + 2 * third;
        ll st_mid_res = cnt(st_mid);
        ll en_mid_res = cnt(en_mid);
        if(st_mid_res == en_mid_res) {
            if(cnt(st) > cnt(en - 1))
                en = en_mid;
            else
                st = st_mid;
        }
        else if(st_mid_res > en_mid_res)
            en = en_mid;
        else
            st = st_mid;
    }
    vll res;
    for(ll i = st; i < en; i++)
        res.pb(cnt(i));
    ll mx = *max_element(all(res));
    forn(i, sz(res)) {
        if(res[i] == mx)
            return st + i;
    }
    assert(1 == 0);
}

