using namespace std;

struct point {
  double x, y;

  template<typename ...P>
  bool collinear(P const & ...points) {
    array<point, sizeof...(points)> ps {points...};

    //x
    int times = 0;
    for(auto p : ps)
      times += (x == p.x ? 1 : 0);

    if(times == ps.size())
      return true;

    //y
    times = 0;
    for(auto p : ps)
      times += (y == p.y ? 1 : 0);

    if(times == ps.size())
      return true;

    return false;
  }

  bool between(point const & a, point const & b) {
     /* 
      * 
      * a          b
      *      x
      * 
      */

      if(
          (a.x <= x && x <= b.x) ||
          (a.y <= y && y <= b.y) ||
          (a.x >= x && x >= b.x) ||
          (a.y >= y && y >= b.y)
        )
        return true;
  }

  friend istream& operator>>(istream& in, point & self) {
    in >> self.x >> self.y;
  }

};

int main(){
  point a, b, c;
  cin >> a >> b >> c;

  int ans;

  if(a.collinear(b, c))
    ans = 1;
  else if(
          (a.collinear(b) && c.between(a, b)) || 
          (a.collinear(c) && b.between(a, c)) || 
          (c.collinear(b) && a.between(c, b))
         )
     ans = 3;
  else if(
          ((a.x != b.x) && (a.x != c.x) && (b.x != c.x)) &&
          ((a.y != b.y) && (a.y != c.y) && (b.y != c.y))
         )
     ans = 3;
  else
     ans = 2;
  cout << ans << '\n';  
  return 0;
}

