const int mod = (int)1e9 + 7;

struct Rational {
    operator int() { return x; }

    Rational() {
        this->x = 0;
#ifdef DEBUG
        this->rawValue = 0;
#endif
    }
    Rational(int x) {
        this->x = (mod + x % mod) % mod;
#ifdef DEBUG
        this->rawValue = x;
#endif
    }

    Rational operator * (int rh) {
        Rational res((this->x * 1ll * ((mod + rh % mod) % mod)) % mod);
#ifdef DEBUG
        res.rawValue = this->rawValue * rh;
#endif
        return res;
    }

    Rational operator * (Rational rh) {
        Rational res((this->x * 1ll * rh.x) % mod);
#ifdef DEBUG
        res.rawValue = this->rawValue * rh.rawValue;
#endif
        return res;
    }

    Rational operator += (Rational rh) {
        this->x = (this->x + 0ll + rh.x) % mod;
#ifdef DEBUG
        this->rawValue += rh.rawValue;
#endif
        return *this;
    }

    Rational operator = (int x) {
        this->x = (mod + x % mod) % mod;
#ifdef DEBUG
        this->rawValue = x;
#endif
        return *this;
    }

    Rational operator / (int x) {
        Rational res(this->x * 1ll * reverse(x) % mod);
#ifdef DEBUG
        res.rawValue = this->rawValue / x;
#endif
        return res;
    }

#ifdef DEBUG
    double rawValue;
#endif
private:
    int x;

    int reverse(int x) {
        x = (mod + x % mod) % mod;
        return binPow(x, mod - 2);
    }

    int binPow(int x, int p) {
        if (!p) return 1;
        if (p & 1) return binPow(x, p - 1) * 1ll * x % mod;
        x = binPow(x, p >> 1);
        return x * 1ll * x % mod;
    }
};

template <class T>
struct Matrix {
    static Matrix<T> unit(int size) {
        Matrix<T> res(size, size);
        for (int i = 0; i < size; ++i)
            res[i][i] = 1;
        return res;
    }

    int rows, cols;
    vector < vector <T> > arr;

    Matrix <T>(int rows, int cols) {
        this->rows = rows;
        this->cols = cols;
        arr.clear();
        for (int i = 0; i < rows; ++i) {
            vector <T> tmp(cols);
            arr.push_back(tmp);
        }
    }

    Matrix <T> operator * (Matrix<T> rh) {
        Matrix <T> lh = *this;
        assert(lh.cols == rh.rows);
        int commonSize = lh.cols;


        Matrix <T> res(lh.rows, rh.cols);
        for (int i = 0; i < lh.rows; ++i)
            for (int j = 0; j < rh.cols; ++j)
                for (int k = 0; k < commonSize; ++k)
                    res[i][j] += lh[i][k] * rh[k][j];

        return res;
    }

    vector <T>& operator [] (int index) {
        return arr[index];
    }
};

template <class T>
Matrix<T> binPow(Matrix<T> m, int p) {
    assert(m.rows == m.cols);
    int size = m.rows;

    if (!p) return Matrix<T>::unit(size);
    if (p & 1) return binPow(m, p - 1) * m;
    m = binPow(m, p >> 1);
    return m * m;
}

