int dfs(int node)
{
	int cnt = 0;
	chk[node] = true;
	for(int i = 1;i <= n;++i) 
		if(!chk[i] && adj[node][i])
			cnt += dfs(i);
	vtx[node] = cnt+1;
	return vtx[node];
}

void go(int s, int r, int root, vector<PIII> ps, vector<bool> c)
{
	int min_y = INT_MAX, min_i = -1;
	for(int i = s;i <= r;++i) if(!c[i] && ps[i].F.S < min_y) {min_y = ps[i].F.S; min_i = i;}
	c[min_i] = true;
	res.push_back(MP(ps[min_i].S,root));
	for(int i = 1;i <= n;++i) if(adj[root][i]) {
		vector<PIII> nps(1);
		vector<bool> nchk;
		while(nps.size() < vtx[i]+1) {
			if(!c[s]) nps.push_back(ps[s]);
			++s;
		}
		adj[i][root] = false;
		nchk.resize(nps.size(),false);
		go(1,nps.size()-1,i,nps,nchk);
	}
}

