		points[i+1] = MP(MP(x,y),i+1);
	}

	dfs(1);

	sort(points.begin()+1,points.end());
	rep(i,n+1) chk[i] = false;

	go(1,n,1,points,chk);

	st(res);

	for(int i = 0;i < res.size();++i) cout << res[i].second << " ";

	return 0;
}

