#include <stdio.h>
#include <assert.h>

int output_year_figure[4];

void carry(void);
bool compare(void);

int main()
{
	int input_year = 0;
	int err = scanf("%d", &input_year);
	/*
	if(err != 1) {
		printf("Input year error!\n");
		assert(0);
	}
	*/
	/* Input year range: 1000 ~ 9000. */
	if(input_year < 1000 || input_year > 9000) {
		printf("Input year is out of range!\n");
		assert(0);
	}

	/* Get four numbers of the input year. */
	output_year_figure[3] = input_year / 1000;
	input_year -= (1000 * output_year_figure[3]);
	output_year_figure[2] = input_year / 100;
	input_year -= (100 * output_year_figure[2]);
	output_year_figure[1] = input_year / 10;
	input_year -= (10 * output_year_figure[1]);
	output_year_figure[0] = input_year;

	bool need_to_calc = true;
	while(need_to_calc) {
		if(output_year_figure[3] == output_year_figure[2]) {
			output_year_figure[2]++;
			carry();
			need_to_calc = !compare();
		}
		else if(output_year_figure[3] == output_year_figure[1] \
			|| output_year_figure[2] == output_year_figure[1]) {
				output_year_figure[1]++;
				carry();
				need_to_calc = !compare();
		}
		else {
			output_year_figure[0]++;
			carry();
			need_to_calc = !compare();
		}
	}

	int output_year = output_year_figure[3] * 1000 + output_year_figure[2] * 100 \
		+ output_year_figure[1] * 10 + output_year_figure[0];
	printf("%d\n", output_year);
}

void carry(void)
{
	if(output_year_figure[0] == 10) {
		output_year_figure[0] = 0;
		output_year_figure[1]++;
		if(output_year_figure[1] == 10) {
			output_year_figure[1] = 0;
			output_year_figure[2]++;
			if(output_year_figure[2] == 10) {
				output_year_figure[2] = 0;
				output_year_figure[3]++;
			}
		}
	}
	else if(output_year_figure[1] == 10) {
		output_year_figure[1] = 0;
		output_year_figure[2]++;
		if(output_year_figure[2] == 10) {
			output_year_figure[2] = 0;
			output_year_figure[3]++;
		}
	}
	else if(output_year_figure[2] == 10) {
		output_year_figure[2] = 0;
		output_year_figure[3]++;
	}
}

bool compare(void)
{
	if(output_year_figure[3] == output_year_figure[2])
		return false;
	if(output_year_figure[3] == output_year_figure[1])
		return false;
	if(output_year_figure[3] == output_year_figure[0])
		return false;
	if(output_year_figure[2] == output_year_figure[1])
		return false;
	if(output_year_figure[2] == output_year_figure[0])
		return false;
	if(output_year_figure[1] == output_year_figure[0])
		return false;
	return true;
}

