ll dp[maxn][maxn][maxn][2];
int a[maxn], b[maxn], c[maxn];
char s[maxn];

void upmin(int &a, int b)
{
    a = min(a, b);
}

int main()
{
    int n;
    scanf("%d%s", &n, s + 1);
    int cnt1 = 0, cnt2 = 0, cnt3 = 0;
    for(int i = 1; i <= n; ++i)
    {
        if(s[i] == 'V') a[++cnt1] = i;
        else if(s[i] == 'K') b[++cnt2] = i;
        else c[++cnt3] = i;
    }
    memset(dp, 0x3f, sizeof(dp));
    dp[0][0][0][0] = 0;
    for(int i = 1; i <= n; ++i)
    {
        for(int j = 0; j <= cnt1; ++j)
        {
            for(int k = 0; k <= cnt2; ++k)
            {
                for(int l = 0; l < 2; ++l)
                {
                    int m = i - j - k;
                    if(i - j - k <= cnt3)
                    {
                        int p = upper_bound(a + 1, a + j + 1, c[m]) - a - 1, q = upper_bound(b + 1, b + k + 1, c[m]) - b - 1;
                        upmin(dp[i][j][k][0], dp[i - 1][j][k][l] + abs(c[m] + j - p + k - q - i));
                    }
                    if(j < cnt1)
                    {
                        int p = upper_bound(b + 1, b + k + 1, a[j + 1]) - b - 1, q = upper_bound(c + 1, c + m, a[j + 1]) - c - 1;
                        upmin(dp[i][j + 1][k][1], dp[i - 1][j][k][l] + abs(a[j + 1] + k - p + m - 1 - q - i));
                    }
                    if(k < cnt2 && l != 1)
                    {
                        int p = upper_bound(c + 1, c + m, b[k + 1]) - c - 1, q = upper_bound(a + 1, a + j + 1, b[k + 1]) - a - 1;
                        upmin(dp[i][j][k + 1][0], dp[i - 1][j][k][l] + abs(b[k + 1] + m - 1 - p + j - q - i));
                    }
                }
            }
        }
    }
    printf("%I64d\n", min(dp[n][cnt1][cnt2][0], dp[n][cnt1][cnt2][1]));
    return 0;
}

