    for(ll i=0;i<n;i++){
        cin >> l[i] >> r[i];
        divi*= (r[i]-l[i]+1);
    }

    for(ll x=1;x<=10000;x++){
        for(ll mask=1;mask<(1LL<<n)-1;mask++){
            f[x][mask]= 0.0; g[0][mask]= 0.0;
            for(ll mask2=1;mask2<(1LL<<n);mask2++){
                if((mask|mask2)!=mask) continue;
                bool have= false; ll cost= 1LL;
                for(ll i=0;i<n;i++){
                    if((mask2&(1LL<<i))!=0){
                        if(l[i]>x || x>r[i]){
                            have= true; break;
                        }
                    }
                    else if((mask&(1LL<<i))!=0){
                        cost*= max(0LL, min(x,r[i]+1)-l[i]);
                    }
                }
                if(!have) f[x][mask]+= (long double)(x*cost);
            }
            g[x][mask]= g[x-1][mask]+f[x][mask];
        }
    }

    for(ll x=1;x<=10000;x++){
        for(ll mask=1;mask<(1LL<<n);mask++){
            ll cost= 1LL, cnt= 0; bool have= false;
            for(ll i=0;i<n;i++){
                if((mask&(1LL<<i))!=0){
                    if(l[i]>x || x>r[i]){
                        have= true; break;
                    }
                    cnt++;
                }
                else cost*= max(0LL,min(x,r[i]+1)-l[i]);
            }
            if(!have){
                if(cnt>=2) res= res+ (long double)(x*cost)/(long double)divi;
                else res= res+ g[x-1][(1<<n)-1-mask]/(long double)divi;
            }
        }
    }

    cout.precision(9);
    cout << fixed << res << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long double ld;
typedef unsigned long long ll;
const int N = 1e4 + 100;

ll n, l[N], r[N], dp[N];
ld sum, s;

int main() {
	ios::sync_with_stdio(false), cin.tie(0);
	cin >> n;
	s = 1;
	for (int i = 0; i < n; i++) {
		cin >> l[i] >> r[i];
		s *= r[i] - l[i] + 1;
	}
	for (int mask = 1; mask < (1 << n); mask++) {
		for (int big = 0; big < N; big++) {
			dp[big] = 1;
			for (int i = 0; i < n; i++)
				if((mask & (1 << i)) == 0) {
					if(l[i] > big)
						dp[big] = 0;
					else if(r[i] <= big)
						dp[big] *= r[i] - l[i] + 1;
					else
						dp[big] *= big - l[i] + 1;
				}
			ld X, S;
			ll L = 1, R = N;
			for (int i = 0; i < n; i++)
				if(mask & (1 << i))
					R = min(R, r[i]), L = max(L, l[i]);
			if(R < L || R <= big)
				X = 0, S = 0;
			else if(L <= big + 1) {
				X = R - big;
				S = (big + 1 + R) * X / 2;
			}
			else {
				X = R - L + 1;
				S = (L + R) * (R - L + 1) / 2;
			}
			if(__builtin_popcount(mask) == 1)
				sum += big * (dp[big] - (big? dp[big - 1]: 0)) * X;
			else
				sum += (dp[big] - (big? dp[big - 1]: 0)) * (S);
		}
	}
	cout << fixed << sum / s;
	return 0;
}

