typedef long long LL;

struct par { LL x, y; };

LL modu, period;

inline LL M (LL x, LL y) {
	LL r(0);
	y = (y % modu + modu) % modu;
	for (; y; y >>= 1, x = (x + x) % modu) if (y & 1) r = (r + x) % modu;
	return r;
}

par getFib (LL x) // (F[x], F[x + 1])
{
	if (x == 0) return (par){0, 1};
	par y;
	if (x & 1)
	{
		y = getFib(x - 1);
		return (par){y.y, (y.x + y.y) % modu};
	}
	else
	{
		y = getFib(x / 2);
		return (par){M(y.x, y.y * 2 - y.x), (M(y.x, y.x) + M(y.y, y.y)) % modu};
	}
}

