void mSwap(int*a,int*b)
{
    *a=*a^*b;
    *b=*a^*b;
    *a=*a^*b;
}

void mSort (int* a, int*b, int* c)
{
    if (*a<*b)
    {
        mSwap(a,b);
    }
    if (*c>*a)
    {
        mSwap(a,c);
        mSwap(b,c);
    }
    else if(*c>*b)
    {
        mSwap(b,c);
    }
}

int main()
{
    unsigned int a, b, c, sum=0;
    cin>>a>>b>>c;
    mSort(&a,&b,&c);
    while(b>0)
    {
        if(b==c)
        {
            sum+=b;
            cout<<sum<<endl;
            return 0;
        }
        --a;
        --b;
        ++c;
        ++sum;
        mSort(&a,&b,&c);
    }
    cout<<sum<<endl;
   return 0;
}

