#include <iostream>
#include <vector>

std::vector<int> digits(int x) {
	std::vector<int> answer;
	while(x) {
		answer.push_back(x % 10);
		x /= 10;
	}
	return answer;
}

int to_integer(std::vector<int> x_digits) {
	int answer = x_digits.back();
	for (int i = x_digits.size() - 2; i >= 0; i--) {
		answer *= 10;
		answer += x_digits[i];
	}
	return answer;
}

int main() {
	int x;
	std::cin >> x;
	std::vector<int> x_digits = digits(x);
	int first_digit = x_digits.back();
	bool is_max_sum = true;
	for (int i = 0; i < x_digits.size() - 1; i++) {
		if (x_digits[i] != 9) {
			is_max_sum = false;
		}
	}
	if (is_max_sum) {
		std::cout << x;
		return 0;
	}

	int answer = first_digit - 1;
	int curr_answer = answer;
	while (curr_answer <= x) {
		answer = curr_answer;
		curr_answer *= 10;
		curr_answer += 9;
	}

	std::vector<int> answer_digits = digits(answer);
	int max_answer = answer;
	for (int i = 0; i < answer_digits.size() - 1; i++) {
		std::vector<int> temp = answer_digits;
		temp[i]--;
		temp.back()++;
		int temp_int = to_integer(temp);
		if (temp_int <= x) {
			max_answer = temp_int;
			break;
		}
	}
	std::cout << max_answer;
}

