int main(){
	cin>>n;
	dp[0] = 1;
	for( int i = 1; i <= n; i++ ){
		memset(f,0,sizeof(f));
		for( int j = 0; j <= n; j++ )
			for( int k = 0; k+j <= n; k++ )
				f[j+k] = (f[j+k]+dp[j]*dp[k])%mod;
		memset(dp,0,sizeof(dp));
		for( int j = 0; j <= n; j++ )
			dp[j] = (f[j-1]+f[j+1]*(j+1)*j+f[j]*(2ll*j+1))%mod;
	}
