using namespace std;
vector<string>v;
void swap(char *x, char *y)
{
    char temp;
    temp = *x;
    *x = *y;
    *y = temp;
}
void permute(char *a, int l, int r)
{
   int i;
   if (l == r)
    {
        string s=a;
        v.push_back(s);
    }
   else
   {
       for (i = l; i <= r; i++)
       {
          swap((a+l), (a+i));
          permute(a, l+1, r);
          swap((a+l), (a+i)); //backtrack
       }
   }
}
int main()
{
   char a[101],b[101];
   cin>>a>>b;
   string str=b;
   long long x=atoi(str.c_str());
   int n=strlen(a);
