   long long ans=-1;
   for (int i=0;i<v.size();i++)
   {
       long long y=atoi(v[i].c_str());
       if (y<x)
       {
           if (y>ans)ans=y;
       }

   }
   cout<<ans<<endl;
    return 0;
}

