int n,m;
int tt[61][61][61];
int agg[61][61];
int inv[150];
const int mod = 1000000007;

void solve()
{
    for (int i = 1; i <= 140; i++) inv[i] = modInv(i, mod);

    re(n,m);

    for (int ops = 0; ops <= n; ops++) {
        int mc = ops;
        tt[ops][0][0] = 1;
        for (int cutl = 0; cutl < ops; cutl++) {
            int cut = cutl+1;

            for (int toto = cutl*2; toto <= ops-1; toto++) {
                long long poss = 0;
                for (int left = cutl; left <= toto-cutl; left++) {
                    if (!tt[left][cutl][left]) break;
                    int right = toto-left;
                    long long right_poss = (2ll * agg[right][cutl+1] + tt[right][cutl][right]) % mod;
                    long long bposs = (tt[left][cutl][left] * right_poss) % mod;
                    poss = (bposs+poss)%mod;
                }

                for (int po = ops-toto-1; po >= 0; po--) {
                    for (int pc = mc-cut; pc >= 0; pc--) {
                        int lim = min( (mc-pc)/cut, (ops-po)/(toto+1) );

                        int comb = (poss * 1ll * tt[ops][pc][po]) % mod;

                        for (int hm = 1; hm <= lim; hm++) {
                            int& dest = tt[ops][pc + cut*hm][po + (toto+1)*hm];
                            dest = (dest + comb) % mod;

                            comb = (comb * 1ll * (poss+hm)) % mod;
                            comb = (comb * 1ll * inv[hm+1]) % mod;
                        }
                    }
                }
            }
        }

        for (int cut = ops; cut >= 0; cut--) {
            agg[ops][cut] = (tt[ops][cut][ops] + agg[ops][cut+1]) % mod;
        }
    }

    ps(tt[n][m-1][n]);
}

