const int maxn = 100005;
int64 h;
int n, m, k;

int64 pos[maxn];
int treasure[maxn];
int flag[maxn];

int64 D[10005];

int64 allk[32];
int top;

struct Pt
{
	int64 t, p, id;
	int operator < (const Pt& o) const
	{
		if (t != o.t) return t < o.t;
		if (p != o.p) return p > o.p;
		return id < o.id;
	}
};

void fix(priority_queue<Pt>& pq)
{
	set<pair<int64, int> > st;

	for (int i = 0; i < k; ++i)
	if (D[i] != -1)
	st.insert({D[i], i});

	while (!st.empty())
	{
		auto where = st.begin();
		auto curr = *where;
		st.erase(where);
		if (D[curr.second] != curr.first) continue;
		for (int i = 0; i < top; ++i)
		{
			int64 val = curr.first
			for (int coe = 0; coe < 3; ++coe)
			{
				val += allk[i];
				if (val > h) continue;

				int next = val % k;

				if (next == curr.second)
				{
					continue;
				}

				if (D[next] == -1)
				{
					D[next] = val;
					st.insert({D[next], next});
				}
				else if (D[next] > val)
				{
					D[next] = val;
					st.insert({D[next], next});
				}
			}
		}
	}

	for (int i = 1; i <= n; ++i) if (flag[i] == 0)
	{
		const int bucket = pos[i] % k;
		if (D[bucket] != -1)
		{
			if (pos[i] >= D[bucket])
			{
				pq.push({treasure[i], pos[i], i});
				flag[i] = 1;
			}
		}
	}
}

int main()
{
	scanf("%I64d", &h);
	n = Rint(), m = Rint(), k = Rint();

	for (int i = 1; i <= n; ++i)
	scanf("%I64d %d", pos+i, treasure+i);

	memset(D, -1, sizeof D);
	D[1%k] = 1;

	priority_queue<Pt> pq;

	for (int i = 1; i <= n; ++i)
	{
		const int bucket = pos[i] % k;
		if (D[bucket] != -1)
		{
			if (pos[i] >= D[bucket])
			{
				pq.push({treasure[i], pos[i], i});
				flag[i] = 1;
			}
		}
	}

	for (int id = 0; id < m; ++id)
	{
		const int cmd = Rint();
		if (cmd == 3)
		{
			while (!pq.empty())
			{
				auto curr = pq.top();
				if (treasure[curr.id] != curr.t)
				{
					pq.pop();
				}
				else
				{
					break;
				}
			}
			int64 ans = 0;
			if (!pq.empty())
			{
				ans = pq.top().t;
				treasure[pq.top().id] = -1;
				flag[pq.top().id] = 2;
				//dbg(pq.top().id);
				//dbg(pq.top().p);
				pq.pop();
			}
			printf("%I64d\n", ans);
		}
		else if (cmd == 2)
		{
			const int x = Rint();
			const int c = Rint();
			treasure[x] -= c;
			if (c != 0 && flag[x])
			{
				//assert(flag[x] == 1);
				if (flag[x] == 1)
				{
					pq.push({treasure[x], pos[x], x});
				}
			}
		}
		else
		{
			int64 x; scanf("%I64d", &x);
			int ok = 1;
			//for (int i = 0; i < top; ++i)
			//if (x % allk[i] == 0) ok = 0;
			//if (x % k == 0) ok = 0;
			if (ok)
			{
				allk[top++] = x;
				fix(pq);
				#if 0
				for (int i = 1; i <= n; ++i)
				if (flag[i])
				cerr << pos[i] << " " << treasure[i] << endl;
				cerr << endl;

				for (int i = 0; i < k; ++i)
				cerr << i << " " << D[i] << endl;
				cerr << endl;
				#endif
			}
		}
	}

	return 0;
}

