ll int priority(char c)
{
	if(c>='0' && c<='9')
	return c-'0';
	return ((c-'A') +10);
}
void find_time(ll int r)
{
	ll int i,p=1;
	for(i=(lh-1);i>=0;i--)
	{
		mh+=p*priority(h[i]);
		p*=r;
		//~ cout<<mh<<endl;
	}
	p=1;
	for(i=(lm-1);i>=0;i--)
	{
		mm+=p*priority(m[i]);
		p*=r;
	}
}
int main()
{
	ios_base::sync_with_stdio(false);
