#include <bits/stdc++.h>
using namespace std;
#define maxn 2500
#define int long long
int n, P, L, R, ans, C[maxn][maxn]; 

int read()
{
	int x = 0, k = 1;
	char c; c = getchar();
	while(c < '0' || c > '9') { if(c == '-') k = -1; c = getchar(); }
	while(c >= '0' && c <= '9') x = x * 10 + c - '0', c = getchar();
	return x * k;
}

void Up(int &x, int y) { x = (x + y) % P; if(x < 0) x += P; }
void Pre()
{
	for(int i = 0; i < maxn; i ++) C[i][0] = 1;
	for(int i = 1; i < maxn; i ++)
		for(int j = 1; j < maxn; j ++)
			C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P;
}

signed main()
{
	n = read(), P = read(), L = read(), R = read();
	Pre();
	for(int i = 0; i <= n; i ++)
	{
		if(L > i || R < 0) continue;
		int l = max(L, 0), r = min(i, R);
		for(int k = l; k <= r; k ++)
			Up(ans, C[n][i] * C[n - i][i - k] % P),
			Up(ans, P - C[n][i] * C[n - i][i - k - 2] % P);
	}
	printf("%I64d\n", ans);
	return 0;
}

