int m,a,b,ans[310000];
bool vis[310000];
long long Sum,now;
queue <int> Q;
inline void BFS(int now)
{
	Q.push(now);
	while(!Q.empty())
	{
		int k = Q.front();Q.pop(),ans[now]++;
		if(k-b >= 0 && !vis[k-b]) vis[k-b] = 1,Q.push(k-b);
		if(k+a<=now && !vis[k+a]) vis[k+a] = 1,Q.push(k+a);
	}
}
int main()
{
	read(m),read(a),read(b),ans[0] = vis[0] = 1;
	for(int i = 0,t;i<a;++i)
	{
		t = 1ll*b*i%a;
		if(vis[t]) break;
		vis[t] = 1;
	}
	for(int i = 1;i<=2*a+b;++i)
		if(i-a >= 0 && vis[i-a]) vis[i] = 1,ans[i] = ans[i-1],BFS(i);
		else ans[i] = ans[i-1];
	for(int i = 0;i<=min(2*a+b,m);++i) Sum += ans[i];
	if(2*a + b >= m) {printf("%lld\n",Sum);return 0;}
	for(int i = 2*a+b+1,N,L,R;i<=a*3+b;++i) if(vis[i%a]) L = (i-i%a)/a,R = (m-i%a)/a,Sum += 1ll * a * (1+(R-L+1)) * (R-L+1) / 2;
	Sum += 1ll*ans[2*a+b] * (m - (2*a+b));
	printf("%lld\n",Sum);
	return 0;
}

