int rotate(int element)
{
	element=(element+R)%n;
	if (element==0) {
		element=n;
	}
	return element;
}
int main()
{
	si(n);si(m);si(q);
	for(int i=0;i<m;i++)
	{
		scanf("%d %d",U[t]+i,V[t]+i);
