const int limite=1000000;

void inserta(vector<int> &alcanza,int pos,int val,int primero)
{
  pos+=primero;
  asigna(alcanza[pos],val);
  while (pos>1) {
    pos/=2;
    asigna(alcanza[pos],max(alcanza[2*pos],alcanza[2*pos+1]));
  }
}

int alcanzaanterior(vector<int> &alcanza,int pos,int primero)
{
  pos+=primero;
  if (alcanza[pos]) return pos-primero;
  for (;;) {
    if (pos==1) return -1;
    if (pos%2==1 and alcanza[pos-1]) {
      pos--;
      while (pos<primero)
	if (alcanza[2*pos+1]) pos=2*pos+1;
	else pos=2*pos;
      return pos-primero;
    }
    pos/=2;
  }
  return -1;
}

