pair<int,int> minimo[1<<21];

void inserta(int pos,int val,int u)
{
  pos+=1<<20;
  minimo[pos]=pair<int,int> (val,u);
  while (pos>1) {
    pos/=2;
    minimo[pos]=min(minimo[2*pos],minimo[2*pos+1]);
  }
}

int minimoentre(int pos0,int pos1)
{
  if (pos0>pos1) swap(pos0,pos1);
  pos0+=1<<20;
  pos1+=1<<20;
  if (pos0==pos1) return minimo[pos0].second;
  pair<int,int> mini0=minimo[pos0];
  pair<int,int> mini1=minimo[pos1];
  while (pos0+1<pos1) {
    if (pos0%2==0) mini0=min(mini0,minimo[pos0+1]);
    pos0/=2;
    if (pos1%2==1) mini1=min(mini1,minimo[pos1-1]);
    pos1/=2;
  }
  return min(mini0,mini1).second;
}

