void eliminapadre(int u,int p,int prof)
{
  visto[u]=1;
  profundidad[u]=prof;
  posle[u]=nrecorrido;
  inserta(nrecorrido++,profundidad[u],u);
  vector<int> &ar=g[u];
  vector<int> nextar;
  numnodos[u]=1;
  for (int i=0;i<int(ar.size());i++) {
    int v=ar[i];
    if (v!=p) {
      eliminapadre(v,u,prof+1);
      numnodos[u]+=numnodos[v];
      nextar.push_back(v);
      inserta(nrecorrido++,profundidad[u],u);
    }
  }
  ar=nextar;
}

void genera(int u,int sr,int sp)
{
  vector<int> lista;
  lista.push_back(u);
  for (;;) {
    vector<int> &ar=g[u];
    int nextu=0;
    for (int i=0;i<int(ar.size());i++) {
      int v=ar[i];
      if (2*numnodos[v]>=numnodos[u]) nextu=v;
      else genera(v,sr,u);
    }
    if (nextu==0) break;
    u=nextu;
    lista.push_back(u);
  }
  u=lista[0];
  {
    int nn=int(lista.size())+3;
    primero[u]=1;
    while (nn>0) {
      nn/=2;
      primero[u]*=2;
    }
    tope[u]=2*primero[u];
  }
  alcanza[u]=vector<int> (tope[u],0);
  elemento[u]=vector<int> (tope[u],0);
  for (int i=0;i<int(lista.size());i++) {
    int v=lista[i];
    superposicion[v]=i+1;
    superidentificador[v]=u;
    superpadre[v]=sp;
    superraiz[v]=sr;
    elemento[u][superposicion[v]]=v;
  }
}

void eliminaanteriores(int u)
