  //cout<<"posant "<<posant<<" "<<alcanzaidu[primeroidu+posant]<<endl;
  if (posant==-1 or posant==0) return;
  inserta(alcanzaidu,posant,0,primeroidu);
  eliminaanteriores(u);
}

int cas=0;

void juntarancestro(int u,int w)
{
  //if (cas==11) cout<<"juntarancestro "<<u<<" "<<w<<endl;
  if (u==w) return;
  int idu=superidentificador[u];
  vector<int> &alcanzaidu=alcanza[idu];
  int primeroidu=primero[idu];
  if (superpadre[u]!=superpadre[w]) {
    if (alcanzaidu[primeroidu]<superposicion[u]) {
      int posant=alcanzaanterior(alcanzaidu,superposicion[u],primeroidu);
      if (posant==-1)
	inserta(alcanzaidu,0,superposicion[u],primeroidu);
      else {
	int nextpos=max(superposicion[u],alcanzaidu[primeroidu+posant]);
	eliminaanteriores(u);
	inserta(alcanzaidu,0,nextpos,primeroidu);
      }
    }
    juntarancestro(superpadre[u],w);
  } else {
    int posant=alcanzaanterior(alcanzaidu,superposicion[u],primeroidu);
    if (posant==-1) {
      inserta(alcanzaidu,superposicion[w],superposicion[u],primeroidu);
    } else if (posant<=superposicion[w]) {
      if (alcanzaidu[primeroidu+posant]<superposicion[w])
	inserta(alcanzaidu,superposicion[w],superposicion[u],primeroidu);
      else if (alcanzaidu[primeroidu+posant]<superposicion[u])
	inserta(alcanzaidu,posant,superposicion[u],primeroidu);
    } else if (alcanzaidu[primeroidu+posant]<=superposicion[u]) {
      inserta(alcanzaidu,posant,0,primeroidu);
      juntarancestro(u,w);
    } else {
      int nextpos=alcanzaidu[primeroidu+posant];
      inserta(alcanzaidu,posant,0,primeroidu);
      juntarancestro(elemento[idu][nextpos],w);
    }
  }
}

void juntar(int u,int v)
{
  //cout<<"juntar "<<u<<" "<<v<<endl;
  int w=ancestro(u,v);
  juntarancestro(u,w);
  juntarancestro(v,w);
}

int obtenerancestro(int u)
{
  int idu=superidentificador[u];
  vector<int> &alcanzaidu=alcanza[idu];
  int primeroidu=primero[idu];
  if (superposicion[u]<=alcanzaidu[primeroidu])
    return obtenerancestro(superpadre[u]);
  int posant=alcanzaanterior(alcanzaidu,superposicion[u],primeroidu);
  if (posant==-1 or alcanzaidu[primeroidu+posant]<superposicion[u])
    return u;
  return elemento[idu][posant];
}

int obteneridentificadorexterno(int u)
{
  int idu=obtenerancestro(u);
  //cout<<"obtenerancestro "<<u<<" "<<idu<<endl;
  idu=computaidentificador(idu);
