void calcula(int u,int p,int prof)
{
  //cout<<"calcula "<<u<<" "<<p<<" "<<prof<<endl;
  bool vistop=false;
  profundidad[u]=prof;
  veo[u]=prof;
  vector<pair<int,int> > &ar=gg[u];
  for (int i=0;i<int(ar.size());i++) {
    int v=ar[i].first;
    if (v==p and not vistop) {
      vistop=true;
    } else if (profundidad[v]) {
      veo[u]=min(veo[u],profundidad[v]);
    } else {
      calcula(v,u,prof+1);
      veo[u]=min(veo[u],veo[v]);
      if (profundidad[u]<veo[v]) {
	recogearistas(v,prof+1);
	numids++;
      } else if (profundidad[u]==veo[v]) {
	recogearistas(v,prof);
	numids++;
      }
    }
  }
}

