int main() {					      	
	ios_base::sync_with_stdio(0);
	ll n, m, k;
	cin >> n >> m >> k;
	ll wrong = n - m;
	ll each = n / k;
	if (wrong >= each) {
		cout << m;	
	} else {
		ll cnt = wrong * each;
		assert(cnt <= n);
		ll ans = cnt - wrong;
		ll left = n - cnt;
		ll total = 0;
		ll good = left / k;
		while(good) {
			total += k;
			total *= 2ll;
			total %= M;
			--good;
		}				
		ll t = left / k;
		total += left - t * k;
		total %= M;
		cout << (ans + total) % M;
	}	
	return 0;
}

