long long dp(long long sum,int tot,int l1,int l2){
	int lg=log2(sum);
	memset(f,0,sizeof(f));
	f[0][0][0]=1;
	for(int i=1;i<=lg;i++){
		long long d=(sum>>i)&1;
		int ed=i*2-2;
		for(int j=0;j<=ed;j++) for(int k=0;k<=1;k++) for(int p1=0;p1<=1;p1++) for(int p2=0;p2<=1;p2++){
			if((i<l1||p1==0)&&(i<l2||p2==0)&&(((p1+p2+k)&1)==d)){
				f[i][j+p1+p2][(k+p1+p2)/2]+=f[i-1][j][k];
			}
		}
	}
	return f[lg][tot][0];
}
