int go(int i, int h, int b, int msk){
	if (h > id[i]){
		i++;
		h = 0;
		b = 1;
		int wall = (1<<(id[i]+1)) - (1<<(id[i-1]+1));
//		cerr << "At i:" << i << ", wall:"; bprn(wall); cerr << endl;
		msk |= wall;
	}	

	if (i >= n) return 1;
	if (dp[i][h][b].count(msk)) return dp[i][h][b][msk];


	int top = (h == id[i]);
	int right = (i == n-1);
	int rem = 4 - b - top - right - (int)((bool)(msk & 1<<h));

	if (rem == 0) return dp[i][h][b][msk] = 0;

//	cerr << "Status for (" << i << "," << h << "," << b << "," << msk << "): " << endl;
//	cerr << "\tRem:" << rem << ", Top:" << top << ", Right:" << right << endl;

	int ans = go(i,h+1,0,msk & ~(1<<h));
	if (rem > 1 && !right) ans = (ans + go(i,h+1,0,msk | (1<<h)) ) % MOD;
	if (rem > 1 && !top) ans = (ans + go(i,h+1,1,msk & ~(1<<h))) % MOD;
	if (rem > 2 && !top && !right) ans = (ans + go(i,h+1,1,msk | (1<<h))) % MOD;

//	cerr << "dp[" << i << "][" << h << "][" << b << "][" << msk << "]: " << ans << endl;
	return dp[i][h][b][msk] = ans;
}

