#include<iostream>
#define mod 1000000007
#define maxn 1000006
using namespace std;

unsigned long long store[maxn];  //store[i]=i!% mod

unsigned long long power(int n,unsigned long long k ,int m=1000000007)  //return n^k % m
{
 if(k==0) return 1;
 if(k==1) return n;
 unsigned long long f=power(n,k/2,m);
 unsigned long long p=(f*f)%m;
 if(k%2!=0)
  p=(p*n)%m;

 return p;
}


unsigned long long invmod(int n,int m)
{
 return power(n,m-2,m);
}


unsigned long long smcomb(int n,int r,int m)      //evaluates comb for small numbers (n<mod,n<10^7) ,mod must be a prime no.
{
 if(n<r) return 0;
 if(n==r) return 1;
 if(r==0) return 1;
 unsigned long long ans=store[n],x=invmod(store[n-r],m),y=invmod(store[r],m);
 ans=(ans*x)%m;
 ans=(ans*y)%m;
 return ans;
}

void create_store(int m)
{

       store[0]=1;
    for(int i=1;i<maxn;i++)
    {
        store[i]=(store[i-1]*i)%m;
    }

}

long long od[maxn], ev[maxn];

int main()
{
    create_store(mod);

    int n,m,a,b;
    cin>>n>>m>>a>>b;

    if(n==2)
    {
        cout<<1;
        return 0;
    }

    od[0]  =1;
    long long e= 1;
    for(int i=1;i<=n;i++)
    {
        od[i] = od[i-1]*e;
        e+=2;
    }

    ev[0]  =1;
    e= 2;
    for(int i=1;i<=n;i++)
    {
        ev[i] = ev[i-1]*e;
        e+=2;
    }

    long long ans =0 ;
    for(int k1=2;k1<=n;k1++)
    {
        int k2 = n-k1;
        long long term = (smcomb(m-1,k1-2, mod) *smcomb(n-2, k1-2, mod))%mod;
        term = (term * store[k1-2])%mod;
        term = (term*power(m, k2))%mod;

        //cout<<k1<<" ::  "<<smcomb(m-1,k1-2,mod)<<" "<<smcomb(n-2,k1-2,mod)<<" "<<power(m,k2)<<" ";
        long long term2=0;
        if(k1%2==1)
        {
            int ind = (k1+1)/2;
            term2 = od[ind+k2-1]*invmod(od[ind-1],mod);
        }
        else
        {
            int ind = (k1)/2;
            term2 = ev[ind+k2-1]*invmod(ev[ind-1],mod);
        }

        term2  = power(n*k1,k2-1)*power(k2,k2-2);
        term2 = term2%mod*invmod(store[k2]);
        term = (term*(term2%mod))%mod;
        //cout<<term2%mod<<" "<<term<<"\n";
        ans= (ans+term)%mod;
    }
    cout<<ans;
    return 0;
}

