int pd(int x,int y,int z,int last){
	if(x == 0 && y == 0 && z == 0) return 1;
	if(x < 0 || y < 0 || z < 0) return 0;

	if(p[x][y][z][last] != -1) return p[x][y][z][last];

	if(last == 0) p[x][y][z][last] = pd(x,y,z-1,3) + pd(x,y-1,z,2) + pd(x-1,y,z,1);
	if(last == 1) p[x][y][z][last] = pd(x,y-1,z,2) + pd(x,y,z-1,3);
	if(last == 2) p[x][y][z][last] = pd(x-1,y,z,1) + pd(x,y,z-1,3);
	if(last == 3) p[x][y][z][last] = pd(x-1,y,z,1) + pd(x,y-1,z,2);

	p[x][y][z][last] %= mod;
	return p[x][y][z][last];
}

signed main(){
	f[0] = 1;
	memset(p,-1,sizeof p);

	cin >> n >> t;

	for(int i = 1;i <= n;i++){
		int x,y;
		cin >> x >> y;
		v[i] = {y,x};

		if(y == 1) q1 ++;
		else if(y == 2) q2 ++;
		else q3 ++;
	}

	int cnt = 0;

	for(int j1 = 0;j1 <= q1;j1++){
		for(int j2 = 0;j2 <= q2;j2++){
			for(int j3 = 0;j3 <= q3;j3++){
				cnt ++;
				r[j1][j2][j3] = cnt;
			}
		}
	}

	//cout << q1 << " " << q2 << " " << q3 << endl;
	//cout << cnt << endl;

	memo[r[0][0][0]][0] = 1;

	for(int i = 1;i <= n;i++){
		for(int j1 = 0;j1 <= q1;j1++){
			for(int j2 = 0;j2 <= q2;j2++){
				for(int j3 = 0;j3 <= q3;j3++){
					for(int k = 0;k <= t;k++){
						comp[r[j1][j2][j3]][k] = memo[r[j1][j2][j3]][k];
						if(k - v[i].second < 0) continue;

						if(v[i].first == 1 && j1 > 0) memo[r[j1][j2][j3]][k] += comp[r[j1 - 1][j2][j3]][k - v[i].second];
						else if(v[i].first == 2 && j2 > 0) memo[r[j1][j2][j3]][k] += comp[r[j1][j2-1][j3]][k - v[i].second];
						else if(v[i].first == 3 && j3 > 0)memo[r[j1][j2][j3]][k] += comp[r[j1][j2][j3-1]][k - v[i].second]; 
					}
				}
			}
		}
	}

	//cout << "// ola" << endl;

	for(int i = 1;i <= 50;i++) f[i] = (f[i-1]*i)%mod;

	int resp = 0;

	for(int j1 = 0;j1 <= q1;j1++){
		for(int j2 = 0;j2 <= q2;j2++){
			for(int j3 = 0;j3 <= q3;j3++){
				int h = ((((f[j1] % mod) * f[j2]) % mod) * f[j3])%mod;
				resp += (memo[r[j1][j2][j3]][t]*pd(j1,j2,j3,0))%mod * h;
				resp %= mod;
			}
		}
	}

	cout << resp << endl;

}

