#include <bits/stdc++.h>
using namespace std;

const int N = 24;
int a[N] , n , dp[N][1<<N];
vector < vector < int > > v;


int rec(int x , int mask)
{
	if(x==n)
	{
		return __builtin_popcount(mask);
	}

	if(dp[x][mask]!=-1) return dp[x][mask];

	int ret = 1e9;
	bool ok = false;
	for(int i=0;i<v[x].size();i++)
	{
		if( (v[x][i] & mask) == v[x][i])
		{
			ok = true;
			int tmp = mask;
			while(tmp)
			{
				int _ = (tmp & -tmp);
				tmp = tmp - (_);
				int tmpmask = mask;
				tmpmask = tmpmask - _;
				tmpmask = (tmpmask | (1<<x));
				ret = min(ret , rec(x+1 , tmpmask));
			}
		}
	}

	if(ok)
	{
		ret = min(ret , rec(x + 1 , (mask | (1<<x))));
		return dp[x][mask] = ret;
	}
	return dp[x][mask] = 1e9;
}

int main()
{
	cin >> n;
	v.resize(n+1);
	memset(dp,-1,sizeof(dp));
	for(int i=0;i<n;i++) scanf("%d",&a[i]);

	for(int i=1;i<n;i++)
	{
		for(int j=0;j<i;j++)
		{
			for(int k=0;k<i;k++)
			{
				if(a[j] + a[k] == a[i])
				{
					int mask = 0;
					mask = mask | (1<<j);
					mask = mask | (1<<k);
					v[i].push_back(mask);
