#include <iostream>
using namespace std;
#define ll long long
int minReplace(int arr[], int n){
    int idx[4] = {0};
    for(int i = 0; i < n; i++){
        idx[arr[i]]++;
    }
    int count = 0;
    for(int i = 1; i < 4; i++){
        if(count < idx[i]){
            count = idx[i];
        }
    }
    return n - count;
}
int main(){
