    cin>>n;
    int arr[n];
    for(int i = 0; i < n; i++){
        cin>>arr[i];
    }
    cout << minReplace(arr, n) << endl;
    return 0;
}

#include <bits/stdc++.h>

#define F first
#define S second

#define mp make_pair

using namespace std;

int memo[810][810];

pair<int, int> V[22], O;
int n, d;

bool check(pair<int, int> p) {
  return p.S * p.S + p.F * p.F <= d * d;
}

int solve(int x, int y) {
  int& ret = memo[x + 400][y + 400];
  if (~ret) return ret;
  ret = 0;
  for (int i = 0; i < n; ++i) {
    if (check(mp(x + V[i].F, y + V[i].S))) ret |= !solve(x + V[i].F, y + V[i].S);
    if (ret) break;
  }
  return ret;
}

