  for (int i = 0; i < n; ++i) scanf("%d %d", &V[i].F, &V[i].S);

  memset(memo, -1, sizeof memo);

  if (solve(O.F, O.S)) printf("Anton\n");
  else printf("Dasha\n");

  return 0;
}

