using namespace std;

typedef long long ll;

ll mul(ll x, ll y, ll mod) {
    ll s = 0;
    for (; y; y /= 2, x = (x + x) % mod)
        if (y & 1)
            s = (s + x) % mod;
    return s;
}

ll power(ll x, ll y, ll mo) {
    ll s = 1;
    for (; y; y /= 2, x = mul(x, x, mo))
        if (y & 1)
            s = mul(s, x, mo);
    return s;
}

ll power(ll x,ll y){
    return power(x,y,LONG_LONG_MAX);
}

ll gcd(ll x, ll y) {
    return y ? gcd(y, x % y) : x;
}

ll lcm(ll a, ll b) {
    return a / gcd(a, b) * b;
}


bool millerabin(ll x) {
    if (x == 2)
        return 1;
    for (int T = 10; T; T--) {
        ll a = rand() % (x - 2) + 2;
        if (power(a, x - 1, x) != 1)
            return 0;
        int p = x - 1;
        for (; p % 2 == 0;) {
            p /= 2;
            ll v = power(a, p, x);
            if (mul(v, v, x) == 1 && v != 1 && v != x - 1)
                return 0;
        }
    }
    return 1;
}

ll pollard(ll n, int c) {
    ll i = 0, k = 2, x = rand() % (n - 1) + 1, y = x;
    for (;;) {
        x = (mul(x, x, n) + c) % n;
        ll g = gcd((y - x + n) % n, n);
        if (g != 1 && g != n)
            return g;
        if (x == y)
            return n;
        if ((++i) == k)
            y = x, k <<= 1;
    }
}

//get all its factors
void getPrimes(ll n, vector<ll> &p) {
    if (n == 1)
        return;
    if (millerabin(n)) {
        p.push_back(n);
        return;
    }
    ll d = n;
    for (int i = 2; d == n; i++)
        d = pollard(n, i);
    getPrimes(d, p);
    getPrimes(n / d, p);
}

//get its sorted factor set
void defactor(ll a, vector<ll> &rs) {
    vector<ll> result;
    getPrimes(a, result);
    sort(result.begin(), result.end());
    if (result.size() > 0)
        rs.push_back(result[0]);
    for (int i = 1; i < result.size(); i++) {
        if (result[i] != result[i - 1])rs.push_back(result[i]);
    }
}

