void printvec(string s, vector<T> v) {
    cout << s << ":";
    for (int i = 0; i < v.size(); i++)
        cout << v[i] << " ";
    cout << endl;
}

ll cal(map<ll,int> &phi_facts, ll x, ll m) {
    if(x==99999999999999) {
        for (map<ll, int>::iterator it = phi_facts.begin(); it != phi_facts.end(); ++it) {
            printf("%I64d:%d,", it->first, it->second);
        }
        printf("x:%I64d,m:%I64d", x, m);
    }
    if(m==0)return 1;
    ll result=1;
    while (true) {
        bool shrinked = false;

        for(map<ll,int>::iterator it=phi_facts.begin();it!=phi_facts.end();++it){
            if(it->second>0){
                ll exp = 1;
                it->second--;
                for(map<ll,int>::iterator it2=phi_facts.begin();it2!=phi_facts.end();++it2){
                    exp *= pow(it2->first, it2->second);
                }
                if (power(x, exp, m) == 1) {
                    shrinked = true;
                    result*=it->first;
                    break;
                }else{
                    it->second++;
                }
            }
        }
        if (!shrinked)break;
    }
    return result;
}

void get_fact_count(vector<ll> &m_factors,vector<int> &m_factors_count,ll m){
    m_factors_count.resize(m_factors.size(),0);
    for(int i=0;i<m_factors.size();++i){
        while(m%m_factors[i]==0){
            m_factors_count[i]++;
            m/=m_factors[i];
        }
    }
}

void search(vector<ll> &m_factors, vector<int> &m_factors_count,vector<vector<ll>> &phi_factors,int deep,ll &result,ll x){
    static int count=0;
    if(deep==m_factors.size()){
        map<ll,int> map_facts;
        ll m=1;
        for(int i=0;i<m_factors.size();i++){
            m*=power(m_factors[i],m_factors_count[i]);
            if(m_factors_count[i]>0){
                for(int j=0;j<phi_factors[i].size();j++){
                    map_facts[phi_factors[i][j]]+=1;
                }
            }
            if(m_factors_count[i]>1){
                map_facts[m_factors[i]]+=m_factors_count[i]-1;
            }
        }
        result+=cal(map_facts,x,m);
        count++;
        if(x==99999999999999) {
            if (count % 7 == 0)
                cout << result << " " << endl;
            cout << result << " ";
        }
    }else {
        int tmp = m_factors_count[deep];
        while (m_factors_count[deep] >= 0) {
            search(m_factors, m_factors_count, phi_factors, deep + 1, result, x);
            m_factors_count[deep]--;
        }
        m_factors_count[deep] = tmp;
    }
}

int main() {
//    ifstream cin("input.txt");
    ll x, m;
    cin >> m >> x;
    vector<ll> m_factors;
    vector<int> m_factors_count;
    defactor(m, m_factors);
    get_fact_count(m_factors,m_factors_count,m);

    vector<vector<ll>> phi_factors(m_factors.size());
    for(int i=0;i<m_factors.size();++i){
        getPrimes(m_factors[i]-1,phi_factors[i]);
    }

    ll result=0;
//    log("1")
    search(m_factors,m_factors_count,phi_factors,0,result,x);
//    log("2")
    cout<<result;


    return 0;
}

