inline int bitCount(int x)
{
    int res = 0;
    while (x)
    {
        ++res;
        x &= (x - 1);
    }
    return res;
}

uint64 rec(int mask1, int mask2)
{
    if (mask1 == fmask) return 1LL;

    pii cur = pii(mask1, mask2);

    if (f.count(cur)) return f[cur];

    int p = bitCount(mask1);
    uint64 res = 0;
    for (int i = 0; i < n; ++i)
    {
        if (mask1 & (1 << i)) continue;
        int x = (i + p) % n;
        if (mask2 & (1 << x)) continue;
        int nmask1 = (mask1 | (1 << i));
        int nmask2 = (mask2 | (1 << x));
        res += rec(nmask1, nmask2);
    }

    f[cur] = res;
    return res;
}

