int n, m, i, j, k, u, v, w;
const int maxn = 51;
const int maxm = 100100;
const int inf = 1e9 + 7;
const int mod = 1e9 + 7;
struct node{
    bool flag;
    int a, b;
    node(){}
    node(bool flag, int a, int b) : flag(flag), a(a), b(b) {}
};
vector <int> fact[maxn];
ll comb[maxn][maxn];
pair<int, ll> dp[2][maxn][maxn];
bool used[2][maxn][maxn];
node que[maxn * maxn * 2];
int w1, w2;
void factorization(vector <int> &x, int a) {
    for (int i = 2; i * i <= a; ++i) {
        if (a % i == 0) {
            x.push_back(i);
            --i;
        }
    }
    if (a > 1) {
        x.push_back(a);
    }
}
int prime[maxn];
ll reck_comb(int n, int k) {
    int i, j;
    for (i = 2; i <= n; ++i) {
        for (j = 0; j < fact[i].size(); ++j) {
            ++prime[fact[i][j]];
        }
    }
    for (i = 2; i <= k; ++i) {
        for (j = 0; j < fact[i].size(); ++j) {
            --prime[fact[i][j]];
        }
    }
    for (i = 2; i <= n - k; ++i) {
        for (j = 0; j < fact[i].size(); ++j) {
            --prime[fact[i][j]];
        }
    }
    ll res = 1;
    for (i = 2; i <= n; ++i) {
        while(prime[i]) {
            --prime[i];
            res *= i;
            res %= mod;
        }
    }
    return res;
}
void din() {
    int a, b, i, j, a1, b1;
    ll res;
    bool flag;
    for (i = 0; i < maxn; ++i) {
        for (j = 0; j < maxn; ++j) {
            dp[0][i][j].first = dp[1][i][j].first = inf;
        }
    }
    dp[0][w1][w2].first = 0;
    dp[0][w1][w2].second = 1;
    que[0] = node(0, w1, w2);
    for (int q = 0, w = 1; q < w; ++q) {
        a = que[q].a;
        b = que[q].b;
        flag = que[q].flag;
        if (flag && a == 0 && b == 0) {
            return;
        }
        if (flag) {
            for (i = 0; i <= k && i <= w1 - a; ++i) {
                for (j = 0; j * 2 + i <= k && j <= w2 - b; ++j) {
                    if (j == 0 && i == 0) {
                        continue;
                    }
                    a1 = a + i;
                    b1 = b + j;
                    res = comb[w1 - a][i];
                    res *= comb[w2 - b][j];
                    res %= mod;
                    res *= dp[flag][a][b].second;
                    res %= mod;
                    if (dp[!flag][a1][b1].first == dp[flag][a][b].first + 1) {
                        dp[!flag][a1][b1].second += res;
                        dp[!flag][a1][b1].second %= mod;
                    }
                    if (dp[!flag][a1][b1].first > dp[flag][a][b].first + 1) {
                        dp[!flag][a1][b1].first = dp[flag][a][b].first + 1;
                        dp[!flag][a1][b1].second = res;
                        que[w] = node(!flag, a1, b1);
                        ++w;
                    }
                }
            }
        }
        else {
            for (i = 0; i <= k && i <= a; ++i) {
                for (j = 0; j * 2 + i <= k && j <= b; ++j) {
                    if (j == 0 && i == 0) {
                        continue;
                    }
                    a1 = a - i;
                    b1 = b - j;
                    res = comb[a][i];
                    res *= comb[b][j];
                    res %= mod;
                    res *= dp[flag][a][b].second;
                    res %= mod;
                    if (dp[!flag][a1][b1].first == dp[flag][a][b].first + 1) {
                        dp[!flag][a1][b1].second += res;
                        dp[!flag][a1][b1].second %= mod;
                    }
                    if (dp[!flag][a1][b1].first > dp[flag][a][b].first + 1) {
                        dp[!flag][a1][b1].first = dp[flag][a][b].first + 1;
                        dp[!flag][a1][b1].second = res;
                        que[w] = node(!flag, a1, b1);
                        ++w;
                    }
                }
            }
        }
    }
}
void init() {
    cin >> n >> k;
    int a;
    k /= 50;
    for (i = 0; i < n; ++i) {
        cin >> a;
        if (a == 50) {
            ++w1;
        }
        else {
            ++w2;
        }
    }
}
void solve() {
    fact[1].push_back(1);
    for (i = 2; i <= max(w1, w2); ++i) {
        factorization(fact[i], i);
    }
    comb[0][0] = 1;
    for (i = 1; i <= max(w1, w2); ++i) {
        comb[i][0] = 1;
        for (j = 1; j <= i; ++j) {
            comb[i][j] = reck_comb(i, j);
        }
    }
    din();
}
void out(){
    if (dp[1][0][0].first >= inf) {
        cout << -1;
    }
    else {
        cout << dp[1][0][0].first;
    }
    cout << endl << dp[1][0][0].second;
}
int main(){
 //   freopen("input.txt","r",stdin); freopen("output.txt","w",stdout);
//  freopen("tetris.in","r",stdin); freopen("tetris.out","w",stdout);
    init();
    solve();
    out();
    return 0;
}

