typedef long long ll;
const int mod = 1000000007;

ll pw2[99];

ll f_rlen[99][99];

inline void upda(ll &a, ll b) {
    a = (a + b) % mod;
}

inline void init_f_rlen() {
    pw2[0] = 1;
    for(int i = 1; i <= 91; ++i) pw2[i] = pw2[i - 1] * 2 % mod;
    f_rlen[0][0] = 1;
    for(int rlen = 1; rlen <= 90; ++rlen) for(int rlen1 = 0; rlen1 <= rlen; ++rlen1) {
            if(rlen1) f_rlen[rlen][rlen1] = f_rlen[rlen - 1][rlen1 - 1] * pw2[rlen - rlen1]) % mod;
            if(rlen1 < rlen) f_rlen[rlen][rlen1] = (f_rlen[rlen][rlen1] + f_rlen[rlen - 1][rlen1]) % mod;
        }
}

ll g_pf[44][44];

inline ll calc_prefix(int pf, int rlen) {
    ll ans = 0;
    for(int rlen1 = 0; rlen1 <= rlen; ++rlen1) {
        ll t1ans = 0;
        memset(g_pf, 0, sizeof(g_pf));
        g_pf[0][0] = 1;
        for(int pfmv = 0; (pf >> pfmv); ++pfmv) for(int pfmv1 = 0; pfmv1 <= pfmv; ++pfmv1) {
                if((pf >> pfmv) == 1) t1ans = (t1ans + g_pf[pfmv][pfmv1]) % mod;
                else {
                    upda(g_pf[pfmv + 1][pfmv1], g_pf[pfmv][pfmv1]);
                    if(pf >> pfmv & 1) upda(g_pf[pfmv + 1][pfmv1 + 1], g_pf[pfmv][pfmv1] * pw2[pfmv - pfmv1 + rlen - rlen1]);
                }
            }
        ans = (ans + t1ans * pw2[rlen - rlen1] % mod * f_rlen[rlen][rlen1]) % mod;
    }
    return ans;
}

inline ll calc_ans(int n) {
    if(n == 0) return 1;
    ll ans = 1; // max = 0;
    int len0;
    for(len0 = 0; (1 << (len0 + 1)) <= n; ++len0) ans = (ans + calc_prefix(1, len0)) % mod;
    int t_pf = 1;
    for(int i = len0 - 1; i >= 0; --i) {
        int a = n >> i & 1;
        if(!a) t_pf <<= 1;
        else {
            ans = (ans + calc_prefix(t_pf << 1, i)) % mod;
            t_pf = t_pf << 1 | 1;
        }
    }
    ans = (ans + calc_prefix(n, 0)) % mod;
    return ans;
}

int main() {
    init_f_rlen();
#ifdef TEST
    printf("[DEBUG] calc_ans(3) = %I64d (expected: 5)\n", calc_ans(3));
#else
    int k; scanf("%d", &k);
    printf("%I64d\n", calc_ans(k));
#endif
    return 0;
}

