unordered_map < long long, int > before;

void Backt(int &cur, long long &cur_cost, int &n, int &fin, vector < int > &cost, long long &best) {

  if (before[cur_cost] > cur) {
    return;
  }
  before[cur_cost] = cur;

  if (cur >= fin) {
    best = min(best, cur_cost);
    return;
  }

  for (int i = 1; i <= n; i ++) {

    cur += (1 << (i - 1));
    cur_cost += cost[i];
    Backt(cur, cur_cost, n, fin, cost, best);
    cur_cost -= cost[i];
    cur -= (1 << (i - 1));
  }
}

