struct SAT
{
	int n, m;
	vector<int> edge[3000];
	vector<int> redge[3000];
	int gi;
	int g[3000];
	int bgi;
	int bg[3000];
	vector<int> gmem[3000];
	int check[3000];
	vector<int> ord;
	int rord[3000];
	int ans[3000];

	int getnum(int x)
	{
		if(x > 0) return x-1;
		else
		{
			x*=-1;
			x--;
			return x+n;
		}
	}
	int not(int x)
	{
		if(x >= n) return x-n;
		else return x+n;
	}
	void input()
	{
		int i, j;
		for(i=0;i<m;i++)
		{
			int x, y;
			scanf("%d%d", &x, &y);
			x=getnum(x), y=getnum(y);
			edge[not(x)].push_back(y);
			edge[not(y)].push_back(x);
		}
		for(i=0;i<n*2;i++)
		{
			for(auto e : edge[i]) redge[e].push_back(i);
		}
	}
	void back(int now)
	{
		if(check[now]) return;
		check[now]=1;
		for(auto e : edge[now]) back(e);
		ord.push_back(now);
	}
	void assignfalse(int x)
	{
		if(ans[x] == 1) return;
		ans[x]=0;
		ans[not(x)]=1;
	}
	void rback(int now)
	{
		if(check[now]) return;
		assignfalse(now);
		check[now]=1;
		g[now]=gi;
		gmem[gi].push_back(now);
		for(auto e : redge[now])
		{
			rback(e);
		}
	}
	int scc()
	{
		int i, j;
		for(i=0;i<n*2;i++)
		{
			back(i);
		}
		fill(check, check+n*2, 0);
		reverse(all(ord));
		for(auto e : ord)
		{
			if(check[e]) continue;
			rback(e);
			gi++;
		}
		for(i=0;i<n;i++)
		{
			if(g[i] == g[not(i)]) return false;
		}
		return true;
	}
	void bback(int now)
	{
		if(check[now]) return;
		check[now]=1;
		bg[now]=bgi;
		for(auto e : edge[now]) bback(e);
		for(auto e : redge[now]) bback(e);
	}
	void markans(int x, int y)
	{
		int i, j;
		vector<pii> w;
		w.emplace_back(y, x);
		w.emplace_back(y^1, not(x));
		ans[x]=y;
		ans[not(x)]=y^1;
		for(j=0;j<w.size();j++)
		{
			int val=w[j].first;
			int now=w[j].second;
			if(val == 1)
			{
				for(auto e : edge[now])
				{
					if(ans[e] != -1) continue;
					ans[e]=1;
					w.emplace_back(1, e);
				}
			}
			else
			{
				for(auto e : redge[now])
				{
					if(ans[e] != -1) continue;
					ans[e]=0;
					w.emplace_back(0, e);
				}
			}
		}
	}
	void dodo()
	{
		int i, j, k;
		fill(check, check+n*2, 0);
		for(i=0;i<n*2;i++)
		{
			if(check[i]) continue;
			bback(i);
			bgi++;
		}
		fill(ans, ans+n*2, -1);
		for(i=0;i<n*2;i++) rord[ord[i]]=i;
		fill(check, check+n*2, 0);
		for(i=0;i<n;i++)
		{
			if(ans[i] != -1) continue;
			if(bg[i] == bg[not(i)]) // 확정
			{
				int u=i, v=not(i);
				if(rord[i] > rord[not(i)]) swap(u, v);
				markans(u, 0);
			}
		}
	}
	void rback2(int now)
	{
		if(check[now]) return;
		assignfalse(now);
		check[now]=1;
		for(auto e : redge[now])
		{
			rback2(e);
		}
	}
	void fillremain()
	{
		fill(check, check+n*2, 0);
		for(auto e : ord)
		{
			if(check[e]) continue;
			rback2(e);
		}
	}

	int tclo[2005][2005];
	map<int, int> mq;
	int tn;

	void maketclo()
	{
		int i, j, k;

		for(i=0;i<n*2;i++)
		{
			if(ans[i] == -1)
			{
				mq[i]=tn++;
			}
		}
		for(i=0;i<n*2;i++)
		{
			if(ans[i] != -1) continue;
			for(auto e : edge[i])
			{
				if(ans[e] != -1) continue;
				tclo[mq[i]][mq[e]]=1;
			}
		}
		for(i=0;i<tn;i++) tclo[i][i]=1;
		for(k=0;k<tn;k++) for(i=0;i<tn;i++) for(j=0;j<tn;j++) tclo[i][j]|=tclo[i][k]&tclo[k][j];
	}
} s1, s2;

