using namespace std;

const int N = 2000 + 10;

int n, m1, m2;

struct SAT
{
	int n, m;
	vector<int> adj[N];
	vector<int> new_adj[N];
	bitset<N> reach[N];
	int qin[N]; //0? 1:yes! -1:not!
	int have_sol;
	int flag, totc;
	int instack[N], stack[N], top;
	int low[N], dfn[N], color[N];
	int tarjan(int u) {
		instack[u] = true;
		stack[++ top] = u;
		dfn[u] = low[u] = flag ++;
		for(int e = 0; e < adj[u].size(); ++ e) {
			int v = adj[u][e];
			if (dfn[v] < 0) {
				low[u] = min(low[u], tarjan(v));
			} else if (instack[v]) {
				low[u] = min(low[u], dfn[v]);
			}
		}
		if (dfn[u] == low[u]) {
			int v;
			do {
				v = stack[top --];
				instack[v] = false;
				color[v] = totc;
			} while(v != u);
			totc ++;
		}
		return low[u];
	}
	void construct(int _n, vector<pair<int, int>> edges) {
		n = _n; m = edges.size();
		for(int i = 0; i < m; ++ i) {
			int u = edges[i].first, v = edges[i].second;
			if (u < n) u = -u + n;
			if (v < n) v = -v + n;
			--u, --v;
			adj[u < n ? u + n : u - n].push_back(v);
			adj[v < n ? v + n : v - n].push_back(u);
		}
		flag = totc = top = 0;
		fill(dfn, dfn + n + n, -1);
		fill(instack, instack + n + n, false);
		for(int i = 0; i < n + n; ++ i) {
			if (dfn[i] < 0) {
				tarjan(i);
			}
		}
		have_sol = true;
		for(int i = 0; i < n; ++ i) {
			if (color[i] == color[i + n]) {
				have_sol = false;
			}
		}
		if (! have_sol) return;
		for(int i = 0; i < n + n; ++ i) {
			for(int e = 0; e < (int)adj[i].size(); ++ e) {
				int j = adj[i][e];
				if (color[i] != color[j]) {
					new_adj[color[i]].push_back(color[j]);
				}
			}
		}
		for(int i = 0; i < totc; ++ i) {
			reach[i].reset();
			reach[i][i] = true;
			for(int e = 0; e < (int)new_adj[i].size(); ++ e) {
				int j = new_adj[i][e];
				reach[i] |= reach[j];
			}
		}
		for(int i = 0; i < n; ++ i) {
			int u = color[i], v = color[i + n];
			if (reach[u][v]) {
				qin[v] = 1;
				qin[u] = -1;
			}
			if (reach[v][u]) {
				qin[u] = 1;
				qin[v] = -1;
			}
		}
		for(int i = 0; i < totc; ++ i) {
			if (qin[i] > 0) {
				for(int j = 0; j < totc; ++ j) {
					if (reach[i][j]) qin[j] = 1;
				}
			}
			if (qin[i] < 0) {
				for(int j = 0; j < totc; ++ j) {
					if (reach[j][i]) qin[j] = -1;
				}
			}
		}
	}
	bool can_have_sol(int r1, int r2) {
		if (r1 < 0) r1 = -r1 + n;
		if (r2 < 0) r2 = -r2 + n;
		--r1, --r2;
		if (qin[color[r1]] < 0 || qin[color[r2]] < 0) return false;
		if (reach[color[r1]][color[r2 < n ? r2 + n : r2 - n]]) {
			return false;
		}
		if (reach[color[r2]][color[r1 < n ? r1 + n : r1 - n]]) {
			return false;
		}
		return true;
	}
	void output_sol() {
		for(int i = 0; i < n; ++ i) {
			if (color[i + n] < color[i]) {
				printf("0 ");
			} else {
				printf("1 ");
			}
		}
		printf("\n");
	}
} s1, s2;

void constuct_sol(vector<pair<int, int>> edges, int r1, int r2) {
	if (r1) {
		edges.push_back(make_pair(r1, r1));
		edges.push_back(make_pair(r2, r2));
	}
	SAT s;
	s.construct(n, edges);
	s.output_sol();
}

void solve()
{
	cin >> n >> m1 >> m2;
	vector<pair<int, int>> e1, e2;
	for(int i = 0; i < m1; ++ i) {
		int x, y;
		scanf("%d%d", &x, &y);
		e1.push_back(make_pair(x, y));
	}
	for(int i = 0; i < m2; ++ i) {
		int x, y;
		scanf("%d%d", &x, &y);
		e2.push_back(make_pair(x, y));
	}
	s1.construct(n, e1);
	s2.construct(n, e2);
	if (s1.have_sol != s2.have_sol) {
		if (s1.have_sol) {
			constuct_sol(e1, 0, 0);
			return;
		}
		if (s2.have_sol) {
			constuct_sol(e2, 0, 0);
			return;
		}
	}
	if (s1.have_sol == false) {
		puts("SIMILAR");
	}
	for(int i = 0; i < m2; ++ i) {
		if (s1.can_have_sol(-e2[i].first, -e2[i].second)) {
			constuct_sol(e1, -e2[i].first, -e2[i].second);
			return;
		}
	}
	for(int i = 0; i < m1; ++ i) {
		if (s2.can_have_sol(-e1[i].first, -e1[i].second)) {
			constuct_sol(e2, -e1[i].first, -e1[i].second);
			return;
		}
	}
	puts("SIMILAR");
}

int main()
{
	solve();
	return 0;
}

