using namespace std;

#define MAX_N 200000

int n;
int numbers[MAX_N];
int exists[MAX_N + 1];

struct Node {
    int l, r, sum;
    Node *left, *right;
    int first, last;
};

deque<Node> nodes;

Node *root;

Node* newNode() {
    nodes.emplace_back();
    return &nodes.back();
}

Node* fillNode(int first, int last) {
    if (first >= last) {
        return nullptr;
    }
    int mid = (first + (last - first) / 2);
    Node * result = newNode();
    result->first = first;
    result->last = last;
    result->l = first;
    result->r = last - 1;
    result->left = fillNode(l, mid);
    result->right = fillNode(mid + 1, r);
    result->sum = 0;
    if (!result->left && !result->right) {
        result->sum = l;
    } else {
        if (result->left) {
            result->sum += result->left->sum;
        }
        if (result->right) {
            result->sum += result->right->sum;
        }
    }
    return result;
}

void fixup(Node * node, Node * parent) {
    if (node->r < parent->l) {
        node->sum = (node->last - node->first) * parent->l;
        node->l = node->r = parent->l;
    }
}

int update(Node *node, int first, int last, int size, Node * parent) {
    if (first >= node->last || last <= node->first) return 0;
    if (parent)
        fixup(node, parent);
    if (node->l >= size) return 0;

    if (first <= node->first) {
        node->l = size;
    }
    if (node->last <= last) {
        node->r = max(node->r, size);
    }

    if (first <= node->first && node->last <= last && node->r <= size) {
        int new_sum = (node->last - node->first) * size;
        int result = new_sum - node->sum;
        node->sum = new_sum;
        return result;
    }

    int sum_from_child = 0;
    if (node->left) {
        sum_from_child += update(node->left, first, last, size, node);
    }
    if (node->right) {
        sum_from_child += update(node->right, first, last, size, node);
    }

    node->sum += sum_from_child;
    return sum_from_child;
}

int set_from(int first, int last) {
    if (first >= last) return 0;
    int barSize = last;
    int barIdx = first;
    return update(root, barIdx, n, barSize, nullptr);
}

int main() {
    std::ios_base::sync_with_stdio(false);
    cin >> n;
    root = fillNode(0, n);
    fill(begin(exists), end(exists), -1);
    for (int i = 0; i < n; ++i) {
        cin >> numbers[i];
        exists[numbers[i]] = i;
    }

    int64_t result = 0;
    for (int gcd = MAX_N; gcd >= 1; --gcd) {
        std::vector<int> idxs;
        for (int i = gcd; i <= MAX_N; i += gcd) {
            if (exists[i] >= 0)
                idxs.push_back(exists[i]);
        }
        if (idxs.size() < 2) continue;
        nth_element(begin(idxs), begin(idxs) + 2, end(idxs));
        int x1 = idxs[0];
        int x2 = idxs[1];
        nth_element(begin(idxs), begin(idxs) + idxs.size() - 2, end(idxs));
        int x3 = idxs[idxs.size() - 2];
        int x4 = idxs[idxs.size() - 1];

        result += gcd * set_from(0, x3);
        result += gcd * set_from(x2, idxs.size());
        result += gcd * set_from(x1 + 1, x4);
    }
}

