			numOfLessCoins[s[0]]++;
		}

		if (numOfLessCoins.find(s[2]) == numOfLessCoins.end()) {
			numOfLessCoins.insert(pair<char, int>(s[2], 0));
		}
	}

	else {

		if (numOfLessCoins.find(s[2]) != numOfLessCoins.end()) {
			numOfLessCoins[s[2]]++;
		}
		else {
			numOfLessCoins.insert(pair<char, int>(s[2], 0));
