using namespace std;

#define MAXN 200010
#define MOD 998244353
#define int long long

int mulmod(int a, int b){ // multiplicacao modular
    // multiplicar (a*b) equivale a sum(a * 2^i * b_i), onde (a*2^i) é representado
    // na linha do meio, b_i na ultima linha, e o passo de sum na primeira linha
    int ans = 0;
    a %= MOD;
    while(b > 0){
        if(b%2) ans = (ans + a) % MOD;
        a = (a * 2) % MOD;
        b >>= 1;
    }
    return ans % MOD;
}

int exp(int a, int b){ // recursivo
	if(b == 0) return 1;
	if(b == 1) return a;
    auto y = exp(mulmod(a, a), b/2);
	if(b&1) return mulmod(y, a);
	return y;
}

int inv(int x){
    return exp(x, MOD - 2);
}

int fat[MAXN];
int c(int p, int q){
    int num = fat[p];
    int den = mulmod(fat[p - q], fat[q]);
    return mulmod(num, inv(den)) % MOD;
}

int32_t main(){
    fat[0] = 1;
    for(int i = 1; i < MAXN; ++i){
        fat[i] = mulmod(i, fat[i - 1]);
    }

