        return 0;
    }

    int n, k; cin >> n >> k;
    // suponho que estou analsiando colunas e dps
    // multiplico por 2
    int numActive = n - k;
    // se eu fizer C(n, numActive) vou estar contando combinacoes
    // em que mais q numEmpty colunas podem estar vazias
    // ex: 1111111111
    // para isso, vai ser usado o principio de inclusao e exclusao
    // que vai contar coluna por coluna, compensando confs contadas
    // multiplas vezes
    // dentre as colunas que vao ser usadas, cada passo vai escolher
    // i colunas que nao serao mais utilizadas, a fim de evitar o problema
    // acima
    int sum = 0;
    for(int i = 0; i < numActive; ++i){
        cerr << sum << endl;
        // exatamente i colunas inativas
        int conb = c(numActive, i); // escolhe as colunas que serao inativas
        int confs = exp(numActive - i, n); // distribui n torres em nas colunas ocupadas

        int x = mulmod(conb, confs) % MOD;
        if(i%2) sum = ((sum - x) + MOD) % MOD;
        else sum = (sum + x) % MOD;
    }

    sum = mulmod(sum, c(n, numActive)); // as confs de escolher as exatas numActive colunas que serao ativas)

    int x = 2; if(k == 0) x = 1;
