struct tarr{
	long long T[300000];
	inline int lowbit(int k){return k&-k;}
	void modify(int k,long long v){
		while (k<=N){
			T[k]+=v;
			k+=lowbit(k);
		}
	}
	long long query(int k){
		long long ret=0;
		while (k){
			ret+=T[k];
			k-=lowbit(k);
		}
		return ret;
	}
}W,WA,iW;

long long calc(int l,int r){
	return iW.query(r)-iW.query(l-1)-l*(W.query(r)-W.query(l-1));
}
