	for (int i=1;i<=N;i++){
		W.modify(i,w[i]);
		WA.modify(i,w[i]*a[i]);
		iW.modify(i,i*w[i]);
	}
	for (int i=1;i<=Q;i++){
		scanf("%d%d",&X,&Y);
