			X=-X;
			W.modify(X,Y-w[X]);
			WA.modify(X,(Y-w[X])*a[X]);
			iW.modify(X,(Y-w[X])*X);
			w[X]=Y;
		}
		else{
			long long pre=W.query(X-1);
			long long sumW=W.query(Y)-pre;
			int l=X,r=Y,mdl;
			while (l<r){
				mdl=(l+r)>>1;
				long long sumpre=W.query(mdl)-pre;
				if ((sumpre<<1)<sumW) l=mdl+1;
				else r=mdl;
			}
			int L=a[l]-l+X;
			long long Ans=calc(X,l-1)-calc(l+1,Y)+L*(W.query(l-1)-W.query(X-1))-(L+l-X+1)*(W.query(Y)-W.query(l))-WA.query(l-1)+WA.query(X-1)+WA.query(Y)-WA.query(l);
			printf("%I64d\n",Ans%1000000007);
