const int maxn = 3005;
vector<ll> pr[maxn];
vector<int> w;
vector<ll> c;
int k;
ll ans = 0;

void apply(vector<ll>& d, int w, ll c) {
  for (int i = (int) d.size() - w - 1; i >= 0; --i) {
    d[i + w] = max(d[i + w], d[i] + c);
  }
}

void rec(int l, int r, vector<ll> d) {
  if (l + 1 == r) {
    for (int i = 0; i <= min(k, w[l]); ++i) {
      ans = max(ans, d[k - i] + pr[l][i]);
    }
    return;
  }
  int c = (l + r) / 2;
  vector<ll> d2 = d;
  for (int i = l; i < c; ++i) {
    apply(d2, w[i], ::c[i]);
  }
  rec(c, r, d2);
  d2 = d;
  for (int i = c; i < r; ++i) {
    apply(d2, w[i], ::c[i]);
  }
  rec(l, c, d2);
}

