int N,M;
ll mo=1000000007;

ll dp[2002][2002],dp2[2002][2002],dp3[2002][2002];

void solve() {
    int i,j,k,l,r,x,y; string s;

    cin>>N>>M;

    for(x=2;x<=2000;x++) dp[x][0]=dp2[x][0]=dp3[x][0]=1;
    for(y=1;y<=2000;y++) {
        ll tot=0;
        for(x=2;x<=2000;x++) {
            tot+=dp[x][y-1];
            dp[x][y]=(dp[x-1][y]+tot)%mo;
            dp2[x][y]=(dp[x][y]+mo-dp[x][y-1])%mo;
            dp3[x][y]=(dp3[x][y-1]+dp2[x][y])%mo;
        }
    }

    int y1,y2,w;
    ll ret=0;
    FOR(y1,N) for(y2=y1;y2<N;y2++) {
        for(w=2;w<=M;w++) ret+=dp3[w][y1]*dp3[w][N-1-y2]%mo(M+1-w)%mo;
        ret%=mo;
    }
    cout << ret << endl;
}


