using namespace std;
const int mod=1e9+7;
struct Node{
  Node* next[100];
};
int num,n,k,d;
int ans;
bool cd;
void trv(Node*root){
  if(root==0){
    return;
  }
   if(num==n&&cd) {
    ans++;
    ans%=mod;
    return;
  }
  for(int i=0;i<k;++i){
    num+=i+1;
    if(i+1>=d) cd=1;
    trv(root->next[i]);
    num-=i+1;
    if(i+1>=d) cd=0;
  }
}
void k_tree(int mx,Node*&root){
  if(mx>=n){
    for(int i=0;i<k;++i){
      root->next[i]=0;
    }
    return;
  }
  for(int i=0;i<k;++i){
    root->next[i]=new Node;
    k_tree(mx+i+1,root->next[i]);
  }
}
void dk_tree(Node*&root){
  if(root==0) return;
  for(int i=0;i<k;++i){
    dk_tree(root->next[i]);
  }
  delete root;
}
int main(){
  Node*root=new Node;
  cin>>n>>k>>d;
  k_tree(0,root);
  trv(root);
  dk_tree(root);
  cout<<ans;
  return 0;
}

