#include <bits/stdc++.h>
using namespace std;

#define si(n) scanf("%lld",&n)
#define ll long long
#define MAX 200005

const int mod=(int) 1e9+7;
ll fact[MAX],inv[MAX];


int mod_add(ll a,ll b) {
  a+=b;
  if(a>=mod) a-=mod;
  return a;
}

int mod_sub(ll a,ll b) {
  a-=b;
  if (a<0) a+=mod;
  return a;
}

int mod_mul(ll a, ll b) {
    a%=mod;
    b%=mod;
  return (a*b)%mod;
}

int bigmod(long long a,long long p)
{
    long long ret = 1;
    a%=mod;
    while(p) {
        if(p & 1) ret = mod_mul(ret,a);
        a = mod_mul(a,a);
        p >>= 1;
    }
    return ret;
}

int mod_div(ll a,ll b)
{
    return mod_mul(a,bigmod(b,mod-2));
}


int mod_power(int a,int b) {
  int res=1;
  while (b>0) {
    if (b&1) {
      res=mod_mul(res,a);
    }
    a=mod_mul(a,a);
    b>>=1;
  }
  return res;
}

void factorial()
{
    fact[0]=1;
    inv[0]=1;
    for(int i=1;i<50;i++){
        fact[i]=mod_mul(fact[i-1],i);
        inv[i]=mod_power(fact[i],mod-2);
    }
}

ll nCr(ll n,ll r)
{
    if(r>n)return 0;
    ll ret=1;
    for(ll i=n-r+1;i<=n;i++)ret=mod_mul(ret,i);
    ret=(ret*inv[r])%mod;
    return ret;
}



int main()
{
    //freopen("input.txt","r",stdin);
    factorial();
    ll n,s,f[25];
    int i,j;

    cin>>n>>s;
    for(i=0;i<n;i++){
        cin>>f[i];
    }

    ll ans=nCr(s+n-1,n-1);

    for(i=0;i<n;i++){
        ll now=s;
        int cnt=0;
        for(j=0;j<n;j++){
            if((i & (1<<j))){
                now-=(f[j]+1);
                cnt++;
            }
        }
        if(now<0 || !cnt)continue;
        if(cnt%2){
            ans=mod_sub(ans,nCr(now+n-1,n-1));
        }
        else ans=mod_add(ans,nCr(now+n-1,n-1));
    }

    cout<<ans<<endl;

    return 0;
}

