using namespace std;

int n;

const int MODULUS = 1000000007;

int f(int x, int y)
{
    int z = n;
    for (int i = 0; i < x; ++i)
    {
        z /= 2;
    }
    for (int i = 0; i < y; ++i)
    {
        z /= 3;
    }
    return z;
}

int answer[1000000 + 1][20][2];

int max_x;
int max_y;

int get_answer(int len, int x, int y)
{
    long long ans = 0;

    if (answer[len][x][y] != -1)
    {
        return answer[len][x][y];
    }

    long long p = f(x, y) - (len - 1);
    if (p > 0)
    {
        ans += p * get_answer(len - 1, x, y) % MODULUS;
        if (ans >= MODULUS)
            ans -= MODULUS;
    }
    if (x < max_x && f(x + 1, y) >= len - 1)
    {
        p = f(x, y) - f(x + 1, y);
        ans += p * get_answer(len - 1, x + 1, y) % MODULUS;
        if (ans >= MODULUS)
            ans -= MODULUS;
    }

    if (y == 0 && f(x, y + 1) >= len - 1)
    {
        p = f(x, y) - f(x, y + 1);
        ans += p * get_answer(len - 1, x, y + 1) % MODULUS;
        if (ans >= MODULUS)
            ans -= MODULUS;
    }
    return answer[len][x][y] = ans;
}

int solve()
{
    int z = n;
    while (z != 1)
    {
        z >>= 1;
        ++max_x;
    }
    answer[1][max_x][0] = 1;
    if ((1 << (max_x - 1)) * 3 <= n)
    {
        answer[1][max_x - 1][1] = 1;
        max_y = 1;
    }
    for (int i = 1; i < n; ++i)
    {
        for (int x = 0; x <= max_x; ++x)
        {
            for (int y = 0; y <= max_y; ++y)
            {
                int z = answer[i][x][y];
                if (z)
                {
                    answer[i + 1][x][y] += max(0, (f(x, y) - i)) * z % MODULUS;
                    if (answer[i + 1][x][y] >= MODULUS)
                        answer[i + 1][x][y] -= MODULUS;
                    if (x > 0)
                    {
                        answer[i + 1][x - 1][y] += (f(x - 1, y) - f(x, y)) * z % MODULUS;
                        if (answer[i + 1][x - 1][y] >= MODULUS)
                            answer[i + 1][x - 1][y] -= MODULUS;
                    }
                    if (y > 0)
                    {
                        answer[i + 1][x][y - 1] += (f(x, y - 1) - f(x, y)) * z % MODULUS;
                        if (answer[i + 1][x][y - 1] >= MODULUS)
                            answer[i + 1][x][y - 1] -= MODULUS;
                    }
                }
            }
        }
    }
    return answer[n][0][0];
}

int main()
{
    cin >> n;
    cout << solve() << endl;
    return 0;
}

