		for (int i=1;i<=26;i++)
			tmp=(tmp+1ll*f[i][n]*inv[k-i])%mo;
		ans=(ans+mo-1ll*tmp*fac[n]%mo*fac[k]%mo)%mo;
	}
	printf("%d",ans);
}

