const int INF = (int)1e9;

int n, m, s;

vector <vector <bool> > visited;
vector <int> compSize;

// L, R, U, D
int dx[4] = {0, 0, -1, 1};
int dy[4] = {-1, 1, 0, 0};

bool valid (int a, int b) {
	return a >= 0 and a < n and b >= 0 and b < m;
}

void dfs (int x, int y, int parx, int pary, int comp) {
	visited[x][y] = true;
	compSize[comp]++;
	int u, v;
	for (int i = 0; i < 4; i++) {
		u = x + (s * dx[i]);
		v = y + (s * dy[i]);
		if (!valid(u, v))
			continue;
		if (u == parx and v == pary)
			continue;
		if (!visited[u][v])
			dfs(u, v, x, y, comp);
	}
	return;
}

void solve () {
	int k = 0;
	visited.assign(n, vector<bool>(m, false));
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if (!visited[i][j]) {
				compSize.push_back(0);
				dfs(i, j, -INF, -INF, k);
				k++;
			}
		}
	}
	int dmax = -INF, pmax = 0;
	for (int i = 0; i < compSize.size(); i++) {
		dmax = max(dmax, compSize[i]);
	}
	for (int i = 0; i < compSize.size(); i++) {
		if (compSize[i] == dmax)
			pmax += compSize[i];
	}
	cout << pmax << "\n";
	return;
}


int main () {
	cin >> n >> m >> s;
	solve();
	return 0;
}

