void ins(vector<int> &A, int k)
{
	for(int i=2;i<=k;++i) A.push_back(i);
}

double Pr(int n, int m, int k)
{
	if (k>m || n-k>n*m-m) return 0;

	vector<int> A,B;
	ins(A,m);ins(A,n*m-m);ins(A,n);ins(A,n*m-n);
	ins(B,k);ins(B,m-k);ins(B,n-k);ins(B,n*m-m-n+k);ins(B,n*m);

	sort(A.begin(),A.end());
	sort(B.begin(),B.end());
	int i=0,j=0;
	while(i<A.size() && j<B.size())
	{
		if (A[i]==B[j]) {A.erase(A.begin()+i);B.erase(B.begin()+j);continue;}
		if (A[i]<B[j]) ++i; else ++j;
	}

    double ret=1.0;
	while (A.size()>0 && B.size()>0)
	{
		if (ret<1.0) {ret*=A.back();A.pop_back();} else
			{ret/=B.back();B.pop_back();}
	}

	for(int i=0;i<A.size();++i) ret*=A[i];
	for(int i=0;i<B.size();++i) ret/=B[i];

	return ret;
}

int main()
{
