map< pair< pair<int, ll>, pair<int, int> >, ll> cache;

ll comb[2005][2005];
ll calComb(int n, int k){
    if (n * k < 0) return 0;
    if (n == k || k == 0) return 1;
    if (n - k < k) return calComb(n, n - k);
    ll& ret = comb[n][k];
    if (ret) return ret;

    return ret = (calComb(n - 1, k) + calComb(n - 1, k - 1)) % mod;
}

ll dfs(int idx, ll sum, int searchMode, int kLeft) {
    if (kLeft < 0) return 0;
    if (sum > S) return 0;
    if (sum == S) return 1;
    if (idx >= nums.size()) return 0;
    ll& ret = cache[mp(mp(idx, sum), mp(searchMode, kLeft))];
    if (ret) return ret;

    int nextIdx = idx;
    while (nextIdx < nums.size()) {
        if (nums[nextIdx] != nums[idx]) break;
        nextIdx++;
    }

    if (searchMode == 1) {
        ll ret1 = 0;
        rep(i, 0, nextIdx - idx) {
            ll nextSum = sum + nums[idx] * (i + 1);
            ret1 += dfs(nextIdx, nextSum, 0, kLeft)  * calComb(nextIdx - idx, i + 1);
        }
        return ret = ret1;
    }
    else {
        ll ret1 = 0;
        if (idx < idxNoFactorial && kLeft) {
            rep(i, 0, nextIdx - idx) {
                ll nextSum = sum + factorial[nums[idx] - 1] * (i + 1);
                if (i == nextIdx - idx - 1)
                    ret1 += dfs(idx + (i + 1), nextSum, 0, kLeft - (i + 1));
                else {              
                    if (nextSum == S) {
                        ret1 += calComb(nextIdx - idx, i + 1); break;
                    }
                    else {
                        ret1 += dfs(idx + (i + 1), nextSum, 1, kLeft - (i + 1))  * calComb(nextIdx - idx, i + 1);
                        ret1 += dfs(nextIdx, nextSum, 0, kLeft - (i + 1))  * calComb(nextIdx - idx, i + 1);
                    }
                }
                if (kLeft - (i + 1) == 0) break;
            }
        }
        ret1 += dfs(idx, sum, 1, kLeft);
        ret1 += dfs(nextIdx, sum, 0, kLeft);
        return ret = ret1;
    }
}

