int inf = 1000000;

pair<int, int> grundy(int n){
  if(n == 1) return make_pair(0, 1);
  vector<int> nums;
  int ret = inf;
  for(int i = 2;i*(i+1)/2 <= n;i++){
    if( (n - i*(i+1)/2 ) % i != 0 ) continue;
    int xorval = 0;
    int base = (n - i*(i+1)/2) / i + 1;
    for(int j = 0; j < i;j++){
      pair<int, int> grundyval =  grundy(base + j);
      xorval ^= grundyval.first;
    }
    nums.push_back(xorval);
    if(xorval == 0){
      ret = min(ret, i);
    }      
  } 

  if(nums.empty()) return make_pair(0, n);
  sort(nums.begin(), nums.end());

  //  cout << n << endl;
  //  print(nums);

  if(nums[0] > 0) return make_pair(0, ret);
  for(int i = 1; i< nums.size();i++){
    if(nums[i] - nums[i-1] > 1){
      return make_pair(nums[i] + 1, ret);
    }
  }
  return make_pair(nums[nums.size() - 1] + 1, ret);
}

