            x=i;y=j;
            while(x<L.size() && y<L[x].size() && L[x][y]=='O')
            {
                L[x][y]='.';
                if(Solve()==false)
                {
                    for(a=i,b=j;a<=x;a++,b++){L[a][b]='O';}
                    Mem[L]=true;
                    return true;
                }
                x++;y++;
            }
            for(a=i,b=j;a<x;a++,b++){L[a][b]='O';}

            // move down left
            x=i;y=j;
            while(x<L.size() && y>=0 && L[x][y]=='O')
            {
                L[x][y]='.';
                if(Solve()==false)
                {
                    for(a=i,b=j;a<=x;a++,b--){L[a][b]='O';}
                    Mem[L]=true;
