void extend_gcd(LL a, LL b, LL &x, LL &y, LL d=1)
{
    if (b == 0)
    {
        d = a, x = 1, y = 0;
    }
    else
    {
        extend_gcd(b, a%b, y, x, d);
        y -= a/b*x;
    }
}

LL ni(LL x)
{
    LL p,q;
    extend_gcd(x,M,p,q);
    return p;
}

