        C = n + 1;  // C[n+1][1]
        if(n == 1) dp[1] = 2;
        else dp[1] = n;

        for(int i=2; i<=m; i++)
        {
            C = C * (n + i) % M;
            C = C * ni(i) % M;
            C %= M;

            dp[i] = (C - dp[i-1]) % M;
            dp[i] = (dp[i] + M) % M;
        }
        cout << dp[m] << endl;
    }
    return 0;
}

