const int modbase = 1000000007;
int n, a, b, k;
int sqmat[5001][5001], res[5001][5001], temp[5001][5001];

void mul(int A[5001][5001], int B[5001][5001]) {
	for (int i=1; i<=n; ++i)
		for (int j=1; j<=n; ++j) {
			temp[i][j] = 0;
			for (int k=1; k<=n; ++k)
				temp[i][j] = (temp[i][j] + (long long)A[i][k]*B[k][j])%modbase;
		}

	for (int i=1; i<=n; ++i)
		for (int j=1; j<=n; ++j)
			A[i][j] = temp[i][j];
}

int main() {
	cin >> n >> a >> b >> k;
	for (int i=1; i<=n; ++i) {
		for (int j=1; j<=n; ++j) {
			res[i][j] = 0;
			sqmat[i][j] = 0;
		}

		for (int j=max(1,2*i-b+1); j<b; ++j)
			sqmat[i][j] = 1;
		for (int j=b+1; j<=min(n,2*i-b-1); ++j)
			sqmat[i][j] = 1;
		sqmat[i][i] = 0;
		res[i][i] = 1;
	}

	for (int shift=0; (k>>shift)!=0; ++shift) {
		mul(sqmat,sqmat);
		if ((k>>shift)&1)
			mul(res,sqmat);
	}

	int sum = 0;
	for (int i=1; i<=n; ++i)
		sum = (sum+res[a][i])%modbase;
	cout << sum << endl;
	return 0;
}

