using namespace std;

vector<int> mem[5001];

vector<int> Fact(int x) {
    if (!mem[x].empty()) {
        return mem[x];
    }

    vector<int> res;
    for (int i = 2; i * i <= x; ++i) {
        while (x % i == 0) {
            res.push_back(i);
            x /= i;
        }
    }
    if (x > 1) {
        res.push_back(x);
    }

    return mem[x] = res;
}

vector<int> F(int x) {
    vector<int> res;
    for (int i = 2; i <= x; ++i) {
        auto f = Fact(i);
        res.insert(res.end(), f.begin(), f.end());
    }
    sort(res.begin(), res.end());
    reverse(res.begin(), res.end());

    return res;
}

