{	
	// cout<<"update_add\n";
	// cout<<in<<" "<<lt<<" "<<rt<<" "<<ql<<" "<<qr<<" "<<val<<"\n";
	if(qr<lt || rt<ql)
		return;

	if(ql<=lt && rt<=qr && lt==rt)
	{	seg[in]+=val;
		return;
	}

	ll mid = (lt+rt)/2;
	add(in*2,lt,mid,ql,qr,val);
	add(in*2+1,mid+1,rt,ql,qr,val);
	seg[in] = min(seg[in*2],seg[in*2+1]);

	return;
}

