int cnt_last_zeros(int x) {
    if (x == 0) return 8;
    int res = 0;
    while (~x & 1) {
        x >>= 1;
        res++;
    }
    return res;
}

map<int, int> aa;
const int mask8 = (1 << 8) - 1;

int nleadc, nlead, xx;
void mul2(int leadcnt, int lead, int x) {
    xx = (x << 1) & mask8;
    int c = (x >> 7) & 1;
    if (lead == c) {
        nlead = lead, nleadc = leadcnt + 1;
    } else {
        nlead = c, nleadc = 1;
    }
}

int add1(int leadcnt, int lead, int x) {
    x = x + 1;
    xx = x & mask8;
    int c = (x >> 8) & 1;
    if (lead == c) {
        nlead = lead, nleadc = leadcnt + 1;
    } else {
        nlead = c, nleadc = 1;
    }
}

long double cache[222][222][2][1 << 8];
long double solve(int rest, int leadcnt, int lead, int x) {
    long double & res = cache[rest][leadcnt][lead][x];
    if (res > -0.5) return res;
    if (rest == 0) {
        int k = cnt_last_zeros(x);
        if (k == 8) {
            if (lead == 0) k += leadcnt;
        }
        res = k;
        return k;
    }
    res = 0;
    mul2(leadcnt, lead, x);
    res += solve(rest - 1, nleadc, nlead, xx) * prob;
    add1(leadcnt, lead, x);
    res += solve(rest - 1, nleadc, nlead, xx) * cprob;
    return res;
}

