				while(h <= d && (q[h] < j - r + l))
					h++;
				dp[cur][j] = min(dp[pre][j], dp[pre][q[h]] + 2);
			}

			h = 1, d = 0;
			for(j = r; j >= 0; j--)
			{
				if(r - j <= n){
					while(h <= d && dp[pre][r - j] <= dp[pre][q[d]]) d--;
					q[++d] = r - j;
				}

				while(h <= d && (q[h] < l - j)) 
					h++;
				dp[cur][j] = min(dp[cur][j], dp[pre][q[h]] + 1);
			}

		}
		if(dp[cur][n] >= INF)
			puts("Hungry");
		else printf("Full\n%d\n", dp[cur][n]);
	}
	return 0;

}

