#include <bits/stdc++.h>
using namespace std;
const int maxn = 52, mod = 1000000007;
typedef long long LL;
int N, M, F[maxn][maxn], G[maxn][maxn], inv[maxn];

void init()
{
    scanf("%d%d", &N, &M);
    inv[1] = 1;
    for(int i = 2;i < maxn;++i)
        inv[i] = LL(mod-mod/i) * inv[mod%i] % mod;
}
void work()
{
    F[0][1] = 1;
    for(int i = 1;i <= N;++i) for(int j = 1;j < maxn;++j)
    {
        for(int a = 0;a < i;++a)
        {
            G[i][j] = (G[i][j] + (LL) F[a][j] * F[i-1-a][j]) % mod;
            for(int b = j+1;b <= i+1 && b < maxn;++b)
            {
                G[i][j] = (G[i][j] + (LL) F[a][b] * F[i-1-a][j]) % mod;
                G[i][j] = (G[i][j] + (LL) F[a][j] * F[i-1-a][b]) % mod;
            }
        }
        //get G[i][j]
        for(int x = N-1;x >= 0;--x) for(int y = 1;y < maxn;++y) if(F[x][y])
        {
            int C = 1;
            for(int t = 1;x+t*i <= N && y+t*j < maxn;++t)
            {
                C = (LL) C * (G[i][j]-1+t) % mod * inv[t] % mod;
                F[x+t*i][y+t*j] = (F[x+t*i][y+t*j] + (LL) F[x][y] * C) % mod;
            }
        }
    }
    printf("%d\n", F[N][M]);
}
int main()
{
    init();
    work();
    return 0;
}

