using namespace std;
typedef long long LL;
const int maxn=5e4+2;
const int maxm=20+2;
const int B=200+2;
int cnt=1;
bitset<B> a[maxn];
int nxt[maxm][maxn];
bool vis[maxm][maxn];
map<bitset<B>,int> mp;
LL dp[maxm][maxm][maxn];
void DP(){
	for (int i=1;i<=cnt;i++){
		int j=0;
		for (;j<10;j++) if (a[i][j]) break;
		for (;j<10;j++) dp[0][j][i]=1;
	}
	for (int i=1;i<maxm-1;i++)
		for (int j=1;j<=cnt;j++)
			if (vis[maxm-1-i][j])
				for (int k=0;k<10;k++)
					for (int l=0;l<10;l++)
						dp[i][l][j]+=dp[i-1][l][nxt[j][k]];
}
int bit[maxm];
LL solve(LL x,int k){
	if (x==0) return 1;
	int len=0;
	while (x){
		bit[len++]=x%10;
		x/=10;
	}
	int u=1;
	LL ret=0;
	for (int i=len-1;i>=0;i--){
		for (int j=0;j<bit[i]+(i==0);j++)
			ret+=dp[i][k][nxt[u][j]];
		u=nxt[u][bit[i]];
	}
	return ret;
}
int main(){
	bitset<B> Bit;
	Bit.set(0);
	mp[Bit]=1;
	a[1]=Bit;
	vis[0][1]=true;
	for (int i=1;i<maxm;i++)
		for (int u=1;u<=cnt;u++)
			if (vis[i-1][u])
				for (int j=0;j<10;j++){
					if (!nxt[u][j])
						if (!j) nxt[u][j]=u;
						else{
							Bit.reset();
							for (int k=j;k<B;k++)
								if (a[u][k]) Bit[k-j]=1;
							for (int k=0;k<B-j;k++)
								if (a[u][k]) Bit[k+j]=1;
							for (int k=1;k<j;k++)
								if (a[u][k]) Bit[j-k]=1;
							if (mp.count(Bit)) nxt[u][j]=mp[Bit];
							else{
								nxt[u][j]=mp[Bit]=++cnt;
								a[cnt]=Bit;
							}
						}
					vis[i][nxt[u][j]]=true;
				}
	DP();
	int kase;
	scanf("%d",&kase);
	while (kase--){
		LL l,r;
		int k;
		scanf("%I64d%I64d%d",&l,&r,&k);
		printf("%I64d\n",solve(r,k)-solve(l-1,k));
	}
	return 0;
}

