using namespace std;
int middle(vector<int> city,int ind,int num)
{
    ind--;
    int criminal=0;
    for(int i=ind+1;i<num;i++)
    {
        static int r=ind-1;
        if(city[i]==city[r]&&city[i]==1)
        {
            criminal+=2;
        }
        r--;
    }
    if(city[ind]==1){criminal++;}
    return criminal;
}
int small(vector<int> city,int ind,int num)
{
    ind--;
    int criminal=0;
    if(ind==0)
    {
        for(int i=0;i<num;i++)
        {
            if(city[i]==1)
            {
                criminal++;
            }
        }
    }
    else
    {
        int f;
        for(int i=ind+1;i<num;i++)
        {
            static int r=ind-1;
            if(city[i]==city[r]&&city[i]==1)
            {
                criminal+=2;
            }
            r--;
            if(r<0)
            {
                f=i+1;
                break;
            }
        }
        for(int i=f;i<num;i++)
        {
            if(city[i]==1)
            {
                criminal++;
            }
        }
        if(city[ind]==1){criminal++;}
    }
    return criminal;
}
int bigger(vector<int> city,int ind,int num)
{
    ind--;
    int criminal=0;
    if(ind==num-1)
    {
        for(int r=ind;r>0;r--)
        {
            if(city[r]==1)
            {
                criminal++;
            }
        }
    }
    else
    {
        int f;
        for(int i=ind+1;i<num;i++)
        {
            static int r=ind-1;
            if(city[i]==city[r]&&city[i]==1)
            {
                criminal+=2;
            }
            r--;
            if(i==num-1)
            {
                f=r;
                break;
            }
            for(int r=f;r>0;r--)
            {
                if(city[r]==1)
                {
                    criminal++;
                }
            }
        }
        if(city[ind]==1){criminal++;}
    }
    return criminal;
}
int main()
{
    int num,ind,criminal=0,ele;
    vector<int>city;
    cin>>num>>ind;
    for(int i=0;i<num;i++)
    {
        cin>>ele;
        city.push_back(ele);
    }
    if(ind==(num/2)+1)
    {
        criminal=middle(city,ind,num);
    }
    else
    {
        if(ind<=num/2)
        {
            criminal=small(city,ind,num);
        }
        else
        {
            criminal=bigger(city,ind,num);
        }
    }
    cout<<criminal;
    return 0;
}

