    lli data;
    node(int a){
        left=NULL,right=NULL,data=a;
    }
    void go(){
        if(data>=2){
            node *te= new node(data/2);
            node *te2= new node(data/2);
            if(left)left->right=te;
            if(right)right->left=te2;
            te->left=left,te->right=this;
            te2->left=this,te2->right=right;
            left=te,right=te2;
            data%=2;
            right->go(),left->go();
