    return ret;
}
vector<int> g(const std::string& s) {
    vector<int> ret(s.size() + 1, 0);
    for (auto i = 0; i < s.size(); ++i) {
        if (s[i] == 'A') {
            ret[i + 1] = ret[i] + 1;
        }
    }
    return ret;
}
