template<int m>
struct mint {
    int x = 0;
    mint(int64_t a = 0) { if (a < 0) a = a % m + m; if (a >= m) a %= m; x = static_cast<int>(a); }
    friend istream& operator>>(istream& in, mint& a) { int64_t y; in >> y; a = y; return in; }
    friend ostream& operator<<(ostream& out, mint a) { return out << a.x; }
    explicit operator int() const { return x; }
    static int mod_inv(int a, int mod = m) {
        // https://en.wikipedia.org/wiki/Extended_Euclidean_algorithm#Example
        int g = mod, r = a, z = 0, y = 1;
        while (r != 0) { int q = g / r; g %= r; swap(g, r); z -= q * y; swap(z, y); }
        return z < 0 ? z + mod : z;
    }
    mint inv() const { return mod_inv(x, m); }
    friend mint binpow(mint a, int64_t b) { mint res = 1; while (b) { if (b & 1) res *= a; b >>= 1; a *= a; } return res; }
    mint pow(int64_t b) const { return binpow(*this, b); }
    mint operator-() const { return x ? m - x : 0; }
    mint& operator+=(const mint& a) { x += a.x; if (x >= m) x -= m; return *this; }
    mint& operator-=(const mint& a) { x -= a.x; if (x < 0) x += m; return *this; }
    static unsigned fast_mod(uint64_t x, unsigned mod = m) {
        return x % mod;
    }
    mint& operator*=(const mint& a) { x = fast_mod((uint64_t) x * a.x); return *this; }
    mint& operator/=(const mint& a) { return *this *= a.inv(); }
    friend mint operator+(mint a, const mint& b) { return a += b; }
    friend mint operator-(mint a, const mint& b) { return a -= b; }
    friend mint operator*(mint a, const mint& b) { return a *= b; }
    friend mint operator/(mint a, const mint& b) { return a /= b; }
    mint& operator++() { x = x == m - 1 ? 0 : x + 1; return *this; }
    mint& operator--() { x = x == 0 ? m - 1 : x - 1; return *this; }
    mint operator++(int) { mint a = *this; ++*this; return a; }
    mint operator--(int) { mint a = *this; --*this; return a; }
    bool operator==(const mint& a) const { return x == a.x; }
    bool operator!=(const mint& a) const { return x != a.x; }
};

con int mod = 998244353;

#define mi mint<mod>

con int N = 405;
con int K = 26;

mi dp[N][N][N][3][3];
int c[K];

void Solve() {    
    int n;
    cin >> n;
    forn(i, 0, K-1) {
        cin >> c[i];
    }
    mi ans = mi(26) * mi(26) * mi(25).pow(n - 2);
    /*
    dp[1][1][0][2][0] = 1;
    dp[1][0][1][2][1] = 1;
    dp[1][0][0][2][2] = K - 2;
    */
    
    dp[2][2][0][0][0]= 1;
    dp[2][1][1][0][1] = 1;
    dp[2][1][1][1][0] = 1;
    dp[2][0][2][1][1] = 1;
    dp[2][1][0][2][0] = K - 2;
    dp[2][1][0][0][2] = K - 2;
    dp[2][0][1][2][1] = K - 2;
    dp[2][0][1][1][2] = K - 2;
    dp[2][0][0][2][2] = (K - 2) * (K - 2);

    forn(i, 2, n) {
        forn(a, 0, n) {
            forn(b, 0, n) {
                forn(x, 0, 2) {
                    forn(y, 0, 2) {
                        mi cur = dp[i - 1][a][b][x][y];
                        if (x != 0) {
                            dp[i][a + 1][b][y][0] += cur;
                        }
                        if (x != 1) {
                            dp[i][a][b + 1][y][1] += cur;
                        }
                        if (x == 2) {
                            dp[i][a][b][y][2] += cur * mi(K - 3);
                        }
                        else {
                            dp[i][a][b][y][2] += cur * mi(K - 2);
                        }
                    }
                }
            }
        }
    }
    forn(i, 0, K-1) {
        mi cur = 0;
        forn(a, 0, n) {
            forn(b, 0, n) {
                forn(x, 0, 2) {
                    forn(y, 0, 2) {
                        if (a > c[i]) {
                            cur += dp[n][a][b][x][y];
                        }
                    }
                }
            }
        }
        ans -= cur;
    }
    forn(i, 0, K-1) {
        forn(j, i+1, K-1) {
            mi cur = 0;
            forn(a, 0, n) {
                forn(b, 0, n) {
                    forn(x, 0, 2) {
                        forn(y, 0, 2) {
                            if (a > c[i] && b > c[j]) {
                                cur += dp[n][a][b][x][y];
                            }
                        }
                    }
                }
            }
            ans += cur;
        }
    }
    out(ans);
}
    
