const long long INF = 1e18;
const int32_t M = 1e9 + 7;
const int32_t MM = 998244353;

ll gcd(ll a, ll b){
    if (b > a){
        return gcd(b, a);
    }
    if (b == 0){
        return a;
    }
    return gcd(b, a % b);
}
ll expo(ll a, ll b, ll mod){
    ll res = 1;
    while (b > 0){
        if (b & 1)
            res = (res * a) % mod;
        a = (a * a) % mod;
        b = b >> 1;
    }
    return res;
}
void extendgcd(ll a, ll b, ll *v){
    if (b == 0){
        v[0] = 1;
        v[1] = 0;
        v[2] = a;
        return;
    }
    extendgcd(b, a % b, v);
    ll x = v[1];
    v[1] = v[0] - v[1] * (a / b);
    v[0] = x;
    return;
}
vector<ll> sieve(ll n){
    ll *arr = new ll[n + 1]();
    vector<ll> vect;
    for (ll i = 2; i <= n; i++)
        if (arr[i] == 0){
            vect.push_back(i);
            for (ll j = 2 * i; j <= n; j += i)
                arr[j] = 1;
        }
    return vect;
}
ll mminv(ll a, ll b){
    ll arr[3];
    extendgcd(a, b, arr);
    return arr[0];
} // For non-prime b
ll mminvprime(ll a, ll b) { return expo(a, b - 2, b); }
ll mod_add(ll a, ll b, ll m){
    a = a % m;
    b = b % m;
    return (((a + b) % m) + m) % m;
}
ll mod_mul(ll a, ll b, ll m){
    a = a % m;
    b = b % m;
    return (((a * b) % m) + m) % m;
}
ll mod_sub(ll a, ll b, ll m){
    a = a % m;
    b = b % m;
    return (((a - b) % m) + m) % m;
}
ll mod_div(ll a, ll b, ll m){
    a = a % m;
    b = b % m;
    return (mod_mul(a, mminvprime(b, m), m) + m) % m;
} // For prime m
ll phin(ll n){
    ll number = n;
    if (n % 2 == 0){
        number /= 2;
        while (n % 2 == 0)
            n /= 2;
    }
    for (ll i = 3; i <= sqrt(n); i += 2){
        if (n % i == 0){
            while (n % i == 0)
                n /= i;
            number = (number / i * (i - 1));
        }
    }
    if (n > 1)
        number = (number / n * (n - 1));
    return number;
} // O(sqrt(N))

const ll NC = 100;
ll fact[NC], ifact[NC], inv[NC];

struct comb_init{
    comb_init(){
        inv[1] = 1;
        for (ll i = 2; i < NC; ++i){
            inv[i] = (M - M / i) * inv[M % i] % M;
        }
        fact[0] = ifact[0] = 1;
        for (ll i = 1; i < NC; ++i){
            fact[i] = fact[i - 1] * i % M;
            ifact[i] = ifact[i - 1] * inv[i] % M;
        }
    }
} comb_init_;

ll combination(ll n, ll r, ll m){
    if (n < r || r < 0)
        return 0;
    ll val1 = fact[n];
    ll val2 = ifact[n - r];
    ll val3 = ifact[r];
    return (((val1 * val2) % m) * val3) % m;
}

