void solve(){
    ull i,j,k;
    ull x,y;
    cin>>x>>y;
    if(x==y){
        yesss;
        return;
    }
    if(x==0){
        if(y==1||y==2){
            yesss;
        }
        else
            nooo;
        return;
    }

    string s1 = bitset<63>(x).to_string();
    string s2 = bitset<63>(y).to_string();

    i = 0;
    while(i < s1.length() && s1[i]=='0')
        i++;
    s1 = s1.substr(i, s1.length() - i + 1);
    bool flag = false;
    size_t found = s2.find(s1);
    if (found != string::npos)
        flag = true;

    reverse(all(s1));

    size_t found = s2.find(s1);
    if (found != string::npos)
        flag = true;

    if(!flag){
        nooo;
        return;
    }

    queue<ull> agenda;
    agenda.push(x);
    vis[x] = true;

    while(!agenda.empty()){
        ull curr = agenda.front();
        agenda.pop();
        if (curr == y){
            yesss;
            return;
        }
        vis[curr] = true;
        string temp1 = bitset<63>(curr).to_string();
        // d1(temp1);
        string temp2 = temp1;
        temp1 += "0";
        temp2 += "1";
        reverse(temp1.begin(), temp1.end());
        while(!temp1.empty() && temp1.back()=='0')
            temp1.pop_back();

        reverse(temp2.begin(), temp2.end());
        while(!temp2.empty() && temp2.back()=='0')
            temp2.pop_back();

        // d2(temp1, temp2);
        ull tc1 = bitset<63>(temp1).to_ullong();
        ull tc2 = bitset<63>(temp2).to_ullong();
        if(!vis[tc1] && setbits(tc1) <= setbits(y))
            agenda.push(tc1);
        if(!vis[tc2] && setbits(tc2) <= setbits(y))
            agenda.push(tc2);
    }
    nooo;
    return;
}

