#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef vector<int> Poly;
const int N = 1 << 20;
int n, G, mod, r[N], Inv[N]; Poly f, g, vf, T, P, ans;
vector<int> factor;
inline int add(int x, int y) { return x + y >= mod ? x + y - mod : x + y; }
inline int dec(int x, int y) { return x - y < 0 ? x - y + mod : x - y; }
inline int mul(int x, int y) { return (ll)x * y % mod; }
inline int qpow(int a, int b) {
	int ans = 1;
	for (; b; b >>= 1, a = mul(a, a)) if (b & 1) ans = mul(ans, a);
	return ans;
}
inline void NTT(Poly &A, int len, int type){
	for (int i = 0; i < len; ++ i) if(i < r[i]) swap(A[i], A[r[i]]);
	for (int mid = 1; mid < len; mid <<= 1) {
		int Wn = qpow(G, (mod - 1) / (mid << 1));
		if (type < 0) Wn = qpow(Wn, mod - 2);
		for (int j = 0; j < len; j += (mid << 1))
			for (int k = 0, w = 1; k < mid; ++ k, w = mul(w, Wn)) {
				int x = A[j + k], y = mul(w, A[j + k + mid]);
				A[j + k] = add(x, y), A[j + k + mid] = dec(x, y);
			}
	}
	if (type > 0) return;
	for (int i = 0; i < len; ++ i) A[i] = mul(A[i], Inv[len]);
}
inline void init_rev(int len) {
	for (int i = 0; i < len; ++ i) r[i] = r[i >> 1] >> 1 | ((i & 1) * (len >> 1));
}
inline Poly operator + (const Poly&a, const Poly&b) {
	Poly c = a; c.resize(max(a.size(), b.size()));
	for (int i = 0; i < b.size(); ++ i) c[i] = add(c[i], b[i]);
	return c;
}
inline Poly operator - (const Poly&a, const Poly&b) {
	Poly c = a; c.resize(max(a.size(), b.size()));
	for (int i = 0; i < b.size(); ++ i) c[i] = dec(c[i], b[i]);
	return c;
}
inline Poly operator * (Poly a, Poly b) {
	int n = a.size(), m = b.size(), l = 1;
	while (l < n + m - 1) l <<= 1;
	init_rev(l);
	a.resize(l), NTT(a, l, 1);
	b.resize(l), NTT(b, l, 1);
	for (int i = 0; i < l; ++ i) a[i] = mul(a[i], b[i]);
	NTT(a, l, -1);
	a.resize(n + m - 1);
	return a;
}
inline Poly operator * (Poly a, int b) {
	for (int i = 0; i < a.size(); ++ i) a[i] = mul(a[i], b);
	return a;
}
inline Poly Deriv(Poly a) {
	for (int i = 0; i + 1 < a.size(); ++ i) a[i] = mul(a[i + 1], i + 1);
	return a.pop_back(), a;
}
inline Poly Integ(Poly a) {
	a.emplace_back(0);
	for (int i = a.size() - 1; i; -- i) a[i] = mul(a[i - 1], Inv[i]);
	return a[0] = 0, a;
}
inline Poly Polyinv(const Poly&a, int lim) {
	Poly c, b(1, qpow(a[0], mod - 2));
	for (int l = 4; (l >> 2) < lim; l <<= 1) {
		init_rev(l);
		c = a, c.resize(l >> 1);
		c.resize(l), NTT(c, l, 1);
		b.resize(l), NTT(b, l, 1);
		for (int i = 0; i < l; ++ i) b[i] = mul(b[i], dec(2, mul(b[i], c[i])));
		NTT(b, l, -1), b.resize(l >> 1);
	}
	return b.resize(lim), b;
}
inline Poly Polyinv(const Poly&a) { return Polyinv(a, a.size()); }
inline Poly Polyln(Poly a, int lim) {
	a = Integ(Deriv(a) * Polyinv(a, lim));
	return a.resize(lim), a;
}
inline Poly Polyln(const Poly&a) { return Polyln(a, a.size()); }
inline Poly Polyexp(const Poly&a, int lim) {
	Poly c, b(1, 1); int n = a.size();
	for (int i = 2; (i >> 1) < lim; i <<= 1) {
		c = Polyln(b, i);
		for (int j = 0; j < i; ++ j) c[j] = dec(j < n ? a[j] : 0, c[j]);
		c[0] = add(c[0], 1);
		b = b * c, b.resize(i);
	}
	return b.resize(lim), b;
}
inline Poly Polyexp(const Poly&a) { return Polyexp(a, a.size()); }
inline void precalc() {
	Inv[0] = Inv[1] = 1;
	for (int i = 2; i < N; ++ i) Inv[i] = mul(mod - mod / i, Inv[mod % i]);
}
Poly exp_f0, fef, xfef, exp_xfef;
inline Poly Newton_Method_f(int len) {
	if (len == 1) { vector<int> f(2); f[0] = 0, f[1] = 1; return f; }
	Poly f = Newton_Method_f(len + 1 >> 1);
	exp_f0 = Polyexp(f, len), fef = f * exp_f0; xfef.resize(len);
	for (int i = 1; i < len; ++ i) xfef[i] = fef[i - 1]; xfef[0] = 0;
	exp_xfef = Polyexp(xfef, len), xfef = exp_xfef + fef;
	for (int i = len - 1; i; -- i) xfef[i] = xfef[i - 1]; xfef[0] = 0;
	for (int i = len - 1; i; -- i) exp_xfef[i] = exp_xfef[i - 1]; exp_xfef[0] = 1;
	exp_xfef = exp_xfef * (fef + exp_f0), exp_xfef.resize(len);
	for (int i = len - 1; i; -- i) exp_xfef[i] = exp_xfef[i - 1]; exp_xfef[0] = mod - 1;
	f = f - (xfef - f) * Polyinv(exp_xfef);
	return f.resize(len), f;
}
int main() {
	scanf("%d%d", &n, &mod);
	int phi = mod - 1;
	for (int i = 2; i * i <= phi; ++ i)
		if (phi % i == 0) {
			while (phi % i == 0) phi /= i;
			factor.emplace_back(i);
		}
	if (phi > 1) factor.emplace_back(phi);
	for (int i = 1; ; ++ i) {
		if (__gcd(i, mod) != 1) continue;
		int flag = true;
		for (auto x : factor)
			if (qpow(i, (mod - 1) / x) == 1) {
				flag = false; break;
			}
		if (flag) { G = i; break; }
	}
	precalc();
	f = Newton_Method_f(100000), f.resize(n + 1);
	vf = Polyexp(f);
	for (int i = vf.size() - 1; i; -- i) vf[i] = vf[i - 1];
	vf[0] = 0;
	g = f - f * vf, g.resize(n + 1);
	P = vf + f - g;
	T = P * g + P, T.resize(n + 1);
	T[0] = 1, vf[0] = 1;
	for (int i = 1; i <= n; ++ i) {
		if (T[i]) T[i] = mod - T[i];
		if (vf[i]) vf[i] = mod - vf[i];
	}
	T = Polyln(T), vf = Polyln(vf);
	for (int i = 1; i <= n; ++ i) {
		if (T[i]) T[i] = mod - T[i];
		if (vf[i]) vf[i] = mod - vf[i];
	}
	ans = Polyexp(T - vf - f + g);
	for (int i = 1, fac = 1; i <= n; ++ i) fac = mul(fac, i);
	printf("%d\n", mul(ans[n], fac));
	return 0;
}

