long long power(  long long x,
                            long long        y, long long   p)
{
    long long ans = 1;
 
    x = x % p;
 
    while (y > 0)
    {
        if (y & 1)
            ans = (ans * x) % p;
        y = y >> 1;
        x = (x * x) % p;
        //cout<<ans<<"\n";
    }
    return ans;
}
 
