void fft(vector<cd>& p, bool invert) {
    ll n = p.size();
    vector<int> rev(n); rev[0] = 0;
    for (int i = 1; i < n; i++) {
        rev[i] = (rev[i>>1]>>1) + (i%2 ? n/2 : 0);
        if (i < rev[i]) swap(p[i], p[rev[i]]);
    }
    vector<cd> w(n);
    for (int i = 0; i < n; i++) w[i] = polar(1.0, ll(2*i)*M_PI / n * (invert ? -1 : 1));
    for (int len = 1; len < n; len *= 2) {
        int m = n / len / 2;
        for (int i = 0; i < n; i += 2*len) {
            for (int j = 0; j < len; j++) {
                cd even = p[i+j], odd = p[i+j+len];
                p[i+j] = even + w[m*j]*odd;
                p[i+j+len] = even - w[m*j]*odd;
            }
        }
    }
    if (invert)
        for (cd& x : p) x /= n;
}
vector<ll> conv_mod(const vector<ll> a, const vector<ll> b) {
    int d = a.size()+b.size()-1;
    int n2 = 1; while (n2 <= d) n2 *= 2;
    ll M = sqrt(MOD);
    vector<cd> inf(n2), ins(n2), outf(n2), outs(n2);
    for (int i = 0; i < a.size(); i++) inf[i] = cd(a[i]/M, a[i]%M);
    for (int i = 0; i < b.size(); i++) ins[i] = cd(b[i]/M, b[i]%M);
    fft(inf, false); fft(ins, false);
    //cout << "debugging inf, ins" << endl;
    //for (int i = 0; i < n2; i++) cout << inf[i] << " "; cout << endl;
    //for (int i = 0; i < n2; i++) cout << ins[i] << " "; cout << endl;
    for (int i = 0; i < n2; i++) {
        int j = n2-i;
        outf[i] = (inf[i] + conj(inf[j]))*ins[i] / cd(2);
        outs[i] = (inf[i] - conj(inf[j]))*ins[i] / cd(2) / cd(0, 1);
    }
    fft(outf, true); fft(outs, true);
    //cout << "debugging outf, outs" << endl;
    //for (int i = 0; i < n2; i++) cout << outf[i] << " "; cout << endl;
    //for (int i = 0; i < n2; i++) cout << outs[i] << " "; cout << endl;
    vector<ll> res(d+1);
    for (int i = 0; i <= d; i++) {
        ll a = llround(outf[i].real()), c = llround(outs[i].imag());
        ll b = llround(outf[i].imag() + outs[i].real());
        res[i] = ((a%MOD*M + b)%MOD*M + c)%MOD;
    }
    return res;
}

vector<ll> naive_mult(vector<ll> a, vector<ll> b) {
    vector<ll> res(a.size()-1+b.size()-1+1, 0);
    for (int i = 0; i < a.size(); i++) {
        for (int j = 0; j < b.size(); j++) {
            res[i+j] = (res[i+j] + a[i]*b[j]) % MOD;
        }
    }
    return res;
}

