void ntt(int *a, int n, int flag){
    for(int i=(n>>1), j=1; j<n; j++){
        if(i<j) swap(a[i], a[j]);
        int k = (n>>1);
        while(i&k){i^=k; k>>=1;}
        i^=k;
    }
    for(int k=2; k<=n; k<<=1){
        int rt = power(g, (mod-1)/k);
        if(flag == -1)
            rt = power(rt, mod-2);
        for(int i=0; i<n; i+=k){
            int del = 1;
            for(int j=i; j<i+k/2; j++){
                int u = a[j], v = 1ll * del * a[j+k/2] % mod;
                a[j] = (u + v) % mod;
                a[j+k/2] = (u - v + mod) % mod;
                del = 1ll * del * rt % mod;
            }
        }
    }
    if(flag == -1){
        int inv = power(n, mod-2);
        for(int i=0; i<n; i++)
            a[i] = 1ll * a[i] * inv % mod;
    }
}
