ll BSGS()
{
    int B=sqrt(1.0*(1ll<<ed))+1;
    int z[N],b[N<<1],c[N<<1];
    memset(z,0,sizeof z); z[0]=1;
    memset(b,0,sizeof b); b[0]=1;
    ha[h(z)]=0;
    for(int i=1;i<=B;i++)
    {
        for(int j=ed;j>=1;j--) z[j]=z[j-1];
        z[0]=0;
        work(z,ed);
        if(i!=B) ha[h(z)]=i;
    }
    for(int k=1;k<=B;k++)
    {
        memset(c,0,sizeof c);
        for(int i=0;i<=ed;i++)
        {
            if(!z[i]) continue;
            for(int j=0;j<=ed;j++) 
                c[i+j]=c[i+j]^(z[i]*b[j]);
        }
        memcpy(b,c,sizeof c);
        work(b,ed<<1);
        int t=h(b);
        if(ha.count(t)) return k*B-ha[t];
    }
    return -1;
}
