map<pair<int, pair<int, pair<char, int>>>, int> dp;

int f(int idx, int lead, char x, int modulo, string s) {

	if (idx == s.size()) {
		if (modulo == 0) return 1;
		else return 0;
	}
	int ans = 0;
	if (dp.find({idx, {lead, {x, modulo}}}) != dp.end()) return dp[ {idx, {lead, {x, modulo}}}];;
	//if (dp[idx][lead][x - '0'][modulo] != -1) return dp[idx][lead][x - '0'][modulo];
	if (lead == 1 && s[idx] == '0') return 0;
	if (s[idx] >= '0' && s[idx] <= '9') {
		int modulo2 = (modulo * 10 + (s[idx] - '0')) % 25;
		ans += f(idx + 1, 0, x, modulo2, s);
	}
	else if (s[idx] == '_') {
		if (!lead)ans += f(idx + 1, 0, x, (modulo * 10) % 25, s);

		for (int i = 1; i < 10; i++) {
			ans += f(idx + 1, 0, x, (modulo * 10 + i) % 25, s);
		}


	}
	else {
		if (x == '#') {
			if (!lead)ans += f(idx + 1, 0, '0', (modulo * 10) % 25, s);

			for (int i = 1; i < 10; i++) {
				ans += f(idx + 1, 0, i + '0', (modulo * 10 + i) % 25, s);

			}
		}
		else {
			ans += f(idx + 1, 0, x, (modulo * 10 + (x - '0')) % 25, s);
		}

	}
	dp[ {idx, {lead, {x, modulo}}}] = ans;
	return ans;

}

