lli add(lli a,lli b)
{
    return (a%MOD + b%MOD)%MOD;
}
lli mul(lli a,lli b)
{
    return (a%MOD * b%MOD)%MOD;
}
lli binpow(lli a,lli b)
{
    lli r=1;
    while(b)
    {
        if(b%2)
            r=mul(r,a);
        a=mul(a,a);
        b/=2;
    }
    return r;
}
lli fact(lli n)
{
    lli r=1;
    for(lli i=1;i<=n;i++)
        r=mul(r,i);
    return r;
}
lli ncr(lli n,lli r)
{
    lli f1=fact(n);
    lli f2=fact(r);
    lli f3=fact(n-r);
    f2=binpow(f2,MOD-2);
    f3=binpow(f3,MOD-2);
    return mul(f1,mul(f2,f3));
}
