/* MOD must be a prime*/

const int MAXN = 251;

int n, k;
ll dp[MAXN][MAXN];    // 前i小权值的边，最后一边的权值为j的方案

namespace Combinatory {
ll qpow (ll x, ll n) {
    if (x >= MOD) x %= MOD;
    ll res = 1;
    for (; n; x = x * x % MOD, n >>= 1)
        if (n & 1) res = res * x % MOD;
    if (res < 0) res += MOD;
    return res;
}
ll inv (ll x) {
    return qpow (x, MOD - 2);
}
ll fac[MAXN], invfac[MAXN];
ll QPOW[MAXN][MAXN * MAXN];
void initC (int n) {
    ASSERT (1 <= n && n <= MAXN && n < MOD);
    fac[0] = 1, invfac[0] = 1;
    for (int i = 1; i <= n; ++i)
        fac[i] = 1LL * fac[i - 1] * i % MOD;
    invfac[n] = inv (fac[n]);
    for (int i = n - 1; i >= 0; --i)
        invfac[i] = 1LL * invfac[i + 1] * (i + 1) % MOD;
    for (int i = 1; i <= n; ++i) {
        QPOW[i][0] = 1;
        for (int j = 1; j <= n * n; ++j)
            QPOW[i][j] = QPOW[i][j - 1] * i % MOD;
    }
}
ll A (ll n, ll m) {
    ASSERT (fac[0] && n <= MAXN);
    return (m < 0 || n < m) ? 0 : 1LL * fac[n] * invfac[n - m] % MOD;
}
ll C (ll n, ll m) {
    ASSERT (fac[0] && n <= MAXN);
    return (m < 0 || n < m) ? 0 : A (n, m) * invfac[m] % MOD;
}
}
using namespace Combinatory;


void purin_solve() {
    RD (n, k);
    initC (n);
    dp[0][0] = 1;
    for (int x = 0; x <= n - 1; ++x) {
        for (int i = 0; x + i <= n - 1; ++i) {
            for (int j = 0; j + 1 <= k; ++j) {
                if (dp[x][j] == 0)
                    continue;
                int e1 = C (i, 2) + x * i;
//                int e2 = C (x + i, 2) - C (x, 2);
//                D2 (e1, e2);
//                assert (e1 == e2);
                dp[x + i][j + 1] += 1LL * dp[x][j] * C (n - 1 - x, i) % MOD * QPOW [k - (j + 1) + 1][e1] % MOD;
                if (dp[x + i][j + 1] >= MOD)
                    dp[x + i][j + 1] -= MOD;
            }
        }
    }
    WT (dp[n - 1][k]);
}

