void factinit() {
    for (int i = 1; i < N; ++i) fact[i] = i * fact[i - 1] % mod, factinv[i] = modinverse(fact[i]);
    for (int i = 0; i < N; ++i) for (int j = 0; j < N; ++j) combs[i][j] = comb(i, j);
}

