ll helpme(int i = 0, int j = 1, int num = 0) {

    auto &me = dp[i][j][num];
    if (me != -1) return me;
    int combb = combs[i][num];
    if (i == n - 1) return combb;

    me = helpme(i + 1, j, num + 1) * bpow(j, n - 2 - i) % mod;
    for (int l = j + 1; l <= k; ++l) me += combb * bpow(l, n - 2 - i) % mod * helpme(i + 1, l, 1) % mod, me %= mod;

