ll modpow(ll x, ll y) {
    ll xs = x;
    ll answer = 1;
    while(y) {
        if (y&1) {
            answer = (answer * xs) % MODD;
        }
        y >>= 1;
        xs = (xs * xs) % MODD;
    }
    return answer;
}

ll B(ll x) {
    return (x*(x+1))/2;
}

ll B(ll a, ll b) {
    ll ret = B(b)-B(a-1);
    return ret;
}
