    cin>>n>>k;

    fact[0]=factinv[0]=1;
    for(int i=1;i<=n;i++) {
        fact[i]=(fact[i-1]*i)%MODD;
        factinv[i]=modpow(fact[i], MODD-2);
    }


    // 1 to n
    for(int i=0;i<=n;i++) {
        for(int j=0;j<=B(n);j++) {
            MP[i][j]=modpow(i,j);
        }
    }


    for(int st=n;st>=1;st--) {
        for(int min_val=1;min_val<=k+1;min_val++) {
            if (st == n)  {
                dp[st][min_val]=1;
                continue;
            }


            ll ans = 0;
            for(int en=st;en<=n;en++) {
                ll b = B(st-1,en-1);
                // st to en has the same value x;
                for(int x=min_val;x<=k;x++) {
                    ll v = MP[k-x+1][b]*factinv[en-st+1]%MODD;
                    ans += v*dp[en+1][x+1]%MODD;
                    ans%=MODD;
                }
            }
            ans%=MODD;
            dp[st][min_val]=ans;
        }
    }

    cout << dp[1][1]*fact[n-1]%MODD << endl;

