int p[250][40000],c[250][250];
int cal(int x,int y){
    if(y==0 or x==y) return 1;
    if(c[x][y]) return c[x][y];
    return c[x][y]=(cal(x-1,y)+cal(x-1,y-1))%mod;
}
void init(){
    memset(dp,-1,sizeof dp);
    for(int i=1;i<=k;i++){
        p[i][0]=1;
        for(int j=1;j<=n*(n-1)/2;j++){
            p[i][j]=1ll*p[i][j-1]*i%mod; //NOLINT
        }
    }
}
int dfs(int mx,int tot){
    if(~dp[mx][tot]) return dp[mx][tot];
    long long res=0;
    if(tot==0 ) return 1;
    if(mx==1) return p[k][tot*(tot-1)/2];
    for(int i=0;i<=tot;i++){
        int cx=cal(tot,i)*p[k-mx+1][(i-1)*i/2+i*(tot-i)]%mod;
        res+=cx*dfs(mx-1,tot-i)%mod;
    }
    return dp[mx][tot]=res%mod;  //NOLINT
}
