using ll = long long;
const int N = 255;
const int MOD = 998244353;
ll binom[N][N];

ll add(ll a, ll b) {
    a += b;
    if (a > MOD) a -= MOD;
    return a;
} 

ll mull(ll a, ll b) {
    return a * b % MOD;
}


void solve() {
    int n, k; cin >> n >> k;
    for(int i = 1; i <= n; ++i) {
        binom[i][0] = 1; binom[i][i] = 1;
        for(int j = 1; j < i; ++j){
            binom[i][j] = binom[i - 1][j] + binom[i - 1][j - 1];
        }
    }

    auto pw = [](ll a, ll b) {
        ll res = 1;
        while(b) {
            if (b & 1) res = mull(res, a);
            a = mull(a, a);
            b >>= 1;
        }
        return res;
    };

    vector<vector<ll>> dp(n + 1, vector<ll> (k + 1));
    for (int j = 0; j <= k; j++) dp[0][j] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= k; j++) {
            dp[i][j] = dp[i][j - 1];
            for (int t = 1; t <= i; t++) {
                int edges = i * (i - 1) - (i - t) * (i - t - 1); edges >>= 1;
                dp[i][j] = add(dp[i][j], binom[i][t] * pw(k - j + 1, edges)
                    % MOD * dp[i - t][j - 1] % MOD); 
            }
        }
    }

    cout << dp[n - 1][k] << "\n";
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);
    solve();
}

