void solve() {
	int n = nxt() - 1, k = nxt();
	InvfactStuff<mod> stuff(n);
	vector<Mint> dp(n + 1);
	dp[0] = 1;
	vector<Mint> tmp(n + 1);
	for (int mx = 1; mx <= k; ++mx) {
		vector<Mint> ot(n + 1);
		for (int i = 0; i <= n; ++i) {
			dp[i] *= Mint(k + 1 - mx).pow(i * (i - 1) / 2).inverse();
			ot[i] = stuff.inverse_factorial(i);
		}
		dp = ntt.multiply(dp, ot);
		dp.resize(n + 1);
		for (int i = 0; i <= n; ++i) {
			dp[i] *= Mint(k + 1 - mx).pow(i * (i - 1) / 2);
		}
	}
	cout << dp[n] * stuff.factorial(n) << "\n";
}

