struct ST{
    vector<ll> st;
    int start;
    int endd;

    void init(int n){
        start = 1;
        while(start < n){
            start = start * 2;
        }
        endd = start*2 - 1;
        st.resize(endd+1);
    }
    void initV(int n, vector<int>& v){
        for(int i =0;i<n;i++){
            st[start+i] = v[i];
        }
        recurseST(1);
    }

    void recurseST(int cur){
        if(cur >= start) return;
        recurseST(cur *2);
        recurseST(cur *2 + 1);
        st[cur] = st[cur*2] + st[cur*2+1];
    }

    void setI(int i, ll x){
        i = i + start;
        st[i] = x;
        i = i / 2;
        while(i >= 1){
            st[i] = max(st[i*2], st[i*2 + 1]);
            i = i / 2;
        }
    }


    void decrease(int i){
        decreaseST(i + start);
    }
    void decreaseST(int cur){
        st[cur]--;
        cur = cur / 2;
        while(cur >= 1){
            st[cur]--;
            cur = cur/2;
        }
    }
    ll getSum(int l, int r){
        return getSum(1, l+start, r+start, start, endd);
    }
    ll getSum(int cur, int l, int r, int h, int t){
        if(r < h || l > t) return 0;
        if(h >= l&& t <= r)return st[cur];
        return getSum(cur*2, l, r, h, (h+t)/2)+ getSum(cur*2 + 1, l,r,(h+t)/2 +1, t);
    }
    ll getMax(int l, int r){
        return getMax(1, l+start, r+start, start, endd);
    }

    ll getMax(int cur, int l, int r, int head, int tail){
        if(r < head || l > tail) return LLONG_MIN;
        if(head >= l && tail <= r) return st[cur];
        return max(getMax(cur*2, l, r, head, (head+tail)/2), getMax(cur*2 + 1, l,r,(head+tail)/2 +1, tail));
    }
};
