using namespace std;

template<int MOD, int RT> struct mint {
	static const int mod = MOD;
	static constexpr mint rt() { return RT; } // primitive root for FFT
	int v; explicit operator int() const { return v; } // explicit -> don't silently convert to int
	mint() :v(0) {}
	mint(__int64 _v) {
		v = int((-MOD < _v&& _v < MOD) ? _v : _v % MOD);
		if (v < 0) v += MOD;
	}
	bool operator==(const mint& o) const {
		return v == o.v;
	}
	friend bool operator!=(const mint& a, const mint& b) {
		return !(a == b);
	}
	friend bool operator<(const mint& a, const mint& b) {
		return a.v < b.v;
	}
	// friend void re(mint& a) { __int64 x; re(x); a = mint(x); }
	// friend str ts(mint a) { return ts(a.v); }

	mint& operator+=(const mint& o) {
		if ((v += o.v) >= MOD) v -= MOD;
		return *this;
	}
	mint& operator-=(const mint& o) {
		if ((v -= o.v) < 0) v += MOD;
		return *this;
	}
	mint& operator*=(const mint& o) {
		v = int((__int64)v * o.v % MOD); return *this;
	}
	mint& operator/=(const mint& o) { return (*this) *= inv(o); }
	friend mint pow(mint a, __int64 p) {
		mint ans = 1; assert(p >= 0);
		for (; p; p /= 2, a *= a) if (p & 1) ans *= a;
		return ans;
	}
	friend mint inv(const mint& a) {
		assert(a.v != 0);
		return pow(a, MOD - 2);
	}

	mint operator-() const { return mint(-v); }
	mint& operator++() { return *this += 1; }
	mint& operator--() { return *this -= 1; }
	friend mint operator+(mint a, const mint& b) { return a += b; }
	friend mint operator-(mint a, const mint& b) { return a -= b; }
	friend mint operator*(mint a, const mint& b) { return a *= b; }
	friend mint operator/(mint a, const mint& b) { return a /= b; }
};
#define MOD 998244353 
typedef mint<MOD, 5> mint1;
int n, k;
void init(){
	cin >> n >> k;
}
void calccnk(vector<vector<mint1>> &cnk, int n) {
	cnk[0][0] = 1;
	for (int i = 1; i <= n; i++) {
		cnk[i][0] = 1;
		for (int j = 1; j <= i; j++) {
			cnk[i][j] = cnk[i - 1][j - 1];
			if (j < i)
				cnk[i][j] += cnk[i - 1][j];
		}
	}
}
void solve(){
	auto f = vector<vector<mint1>>(n + 1, vector<mint1>(k + 1));
	vector<vector<mint1>> cnk = vector<vector<mint1>>(n + 1, vector<mint1>(n + 1));
	calccnk(cnk, n);
	for (int i = 0; i <= k; i++) {
		f[0][i] = 1;
	}
	f[1][0] = 0;
	for (int i = 1; i <= n; i++) {
		f[i][0] = 0;
		f[i][1] = pow(k, i * (i - 1) / 2);
		for (int p = 2; p <= k; p++) {
			f[i][p] = f[i][p - 1];
			for (int j = 1; j <= i; j++) {
				//c(i,j) * pow(k - p + 1, j * (j - 1) / 2) * f(i - j, p - 1) * pow(k - p + 1, j * (i - j))
				mint1 tmp;
				tmp = cnk[i][j] * pow(mint1(k - p + 1), j * (j - 1) / 2 + j * (i - j)) * f[i - j][p - 1];
				f[i][p] += tmp;
			}
		}
	}

	cout << (int)f[n - 1][k] << "\n";
}

