inline ll calc(int l,int r){
	ll ret=0;
	for(int x=l,y=0;x<=r;x=y+1){
		y=r/(r/x);
		ret+=phi[r/x]*(y-x+1);
	}
	return ret;
}
inline void solve(int x,int l,int r,int ql,int qr){
	if(l>r) return ;
	int mid=(l+r)>>1,pos=ql;ll now=calc(min(qr+1,mid),mid);
