const int N = 207;
const int SUM = N*N;
int MOD;
int binpow(ll x,int power){
    ll mult = x%MOD;
    x = 1;
    while(power){
        if (power&1)
            x = x*mult%MOD;
        mult = mult*mult%MOD;
        power = power>>1;
    }
    return x;
}
ll fact[N],rev[N];
int C(int n,int k){
    return fact[n]*rev[k]%MOD*rev[n-k]%MOD;
}
int dp[20][SUM][N],mv[N];
int last;
int n;
int F(int cur,int sum,int cnt,int mi){
    if (cur*mi<sum || sum>cur*cnt || sum<mi*cnt)
        return 0;
    if (dp[cur-mi][sum][cnt]!=-1)
        return dp[cur-mi][sum][cnt];

    if (cur==mi){
        if (sum!=mi*cnt || cnt>mi || cnt==0)
            dp[cur-mi][sum][cnt] = 0;
        else
            dp[cur-mi][sum][cnt] = 1;
        return dp[cur-mi][sum][cnt];
    }
    dp[cur-mi][sum][cnt] = F(cur-1,sum,cnt,mi);
    int sa = 0;
    for(int add = 1;add<=cnt && sa<=sum;++add){
        sa+=cur;
        ll ret = F(cur-1,sum-sa,cnt-add,mi);
        if (ret==0)
            continue;
        ret = ret*C(cnt,add);
        if (ret>MOD*2)
            ret%=MOD;
        if (ret>=MOD)
            ret-=MOD;
        dp[cur-mi][sum][cnt]+=ret;
        if (dp[cur-mi][sum][cnt]>=MOD)
            dp[cur-mi][sum][cnt]-=MOD;
    }
    return dp[cur-mi][sum][cnt];
}
void solve(){

    cin>>n>>MOD;
    fact[0] = 1;
    for(int i = 1;i<N;++i){
        fact[i] = fact[i-1]*i%MOD;
    }
    rev[N-1] = binpow(fact[N-1],MOD-2);
    for(int i = N-2;i>=0;--i){
       rev[i] = rev[i+1]*(i+1)%MOD;
    }

    for(int i = n+1;i>=1;--i){
        int sum = 0,cnt = 0;
        for(int j = i;j<=n+1;++j){
           while(i*j>=sum+j)
               sum+=j,mv[++cnt] = j;
