long long dp[201][201][201];
long long fac[201];
long long inv[201];

long long power(long long k, int p, int M) {
    if (p == 0) {
        return 1;
    }
    long long y = power (k, p/2, M);
    long long z = y * y % M;
    if (p % 2 == 0) {
        return z;
    }
    else {
        return z * k % M;
    }
}

void computeMod(int M) {
